window.__TOPIC_JS=window.__TOPIC_JS||{};window.__TOPIC_JS["類義語の使い分け"]={
"_note": "05. 類義語の使い分け — mỗi nhóm so sánh một dòng. ĐỊNH DẠNG MỖI NHÓM: label, note, items [word, reading, meaning, example, example_reading, example_meaning, examples]. TRƯỜNG antonym (tuỳ chọn): từ trái nghĩa, dạng \"từ（cách đọc）: nghĩa\", nhiều từ cách nhau bằng \" / \". TRƯỜNG antonym_hanviet (tuỳ chọn, đi kèm antonym): âm Hán Việt của từng từ trái nghĩa, viết thường như trường hanviet, cùng thứ tự và cách nhau bằng \" / \" (từ chỉ có kana, không có chữ Hán, để trống). SỐ LƯỢNG: 100 nhóm / 272 từ.",
"id": "5. 類義語の使い分け",
"title": "類義語の使い分け",
"icon": "🎯",
"category": "ref",
"kind": "compare",
"compare": [
{"label":"目的／目標","note":"目的(もくてき): MỤC ĐÍCH cuối cùng, lý do sâu xa của hành động. 目標(もくひょう): MỤC TIÊU cụ thể, có thể đo lường được để đạt tới mục đích.","items":[{"word":"目的","reading":"もくてき","meaning":"mục đích (lý do sâu xa)","example":"健康になることが運動の目的です。","example_reading":"けんこうになることがうんどうのもくてきです。","example_meaning":"Trở nên khỏe mạnh là mục đích của việc tập thể dục.","examples":[{"example":"日本へ来た目的は、日本語を勉強することです。","example_reading":"にほんへきたもくてきは、にほんごをべんきょうすることです。","example_meaning":"Mục đích tôi đến Nhật là để học tiếng Nhật."},{"example":"目的を忘れずに、最後までがんばりましょう。","example_reading":"もくてきをわすれずに、さいごまでがんばりましょう。","example_meaning":"Đừng quên mục đích, hãy cố gắng đến cùng nhé."}]},{"word":"目標","reading":"もくひょう","meaning":"mục tiêu (cụ thể, đo lường được)","example":"一か月で三キロ痩せるのが目標です。","example_reading":"いっかげつでさんきろやせるのがもくひょうです。","example_meaning":"Mục tiêu là giảm 3kg trong một tháng.","examples":[{"example":"今年の目標は、日本語能力試験に合格することです。","example_reading":"ことしのもくひょうは、にほんごのうりょくしけんにごうかくすることです。","example_meaning":"Mục tiêu năm nay là đỗ kỳ thi năng lực tiếng Nhật."},{"example":"毎日一時間歩くという目標を立てました。","example_reading":"まいにちいちじかんあるくというもくひょうをたてました。","example_meaning":"Tôi đã đặt ra mục tiêu mỗi ngày đi bộ một tiếng."}]}]},
{"label":"猶予／延長／延滞","note":"猶予(ゆうよ): GIA HẠN thêm thời gian trước khi hết hạn (còn thời gian chuẩn bị). 延長(えんちょう): KÉO DÀI thêm thời gian/khoảng cách so với ban đầu. 延滞(えんたい): TRỄ HẠN, chậm trả (nợ, thanh toán) sau khi đã quá hạn.","items":[{"word":"猶予","reading":"ゆうよ","meaning":"gia hạn (trước khi hết hạn)","example":"支払いを一週間猶予してもらいました。","example_reading":"しはらいをいっしゅうかんゆうよしてもらいました。","example_meaning":"Tôi đã được gia hạn thanh toán thêm một tuần.","examples":[{"example":"返事は、もう少し猶予をいただけませんか。","example_reading":"へんじは、もうすこしゆうよをいただけませんか。","example_meaning":"Anh có thể cho tôi thêm chút thời gian để trả lời không?"},{"example":"期限まで三日の猶予があります。","example_reading":"きげんまでみっかのゆうよがあります。","example_meaning":"Còn ba ngày nữa mới đến hạn."}]},{"word":"延長","reading":"えんちょう","meaning":"kéo dài thêm","example":"契約を一年延長しました。","example_reading":"けいやくをいちねんえんちょうしました。","example_meaning":"Tôi đã gia hạn hợp đồng thêm một năm.","examples":[{"example":"会議が三十分延長されました。","example_reading":"かいぎがさんじゅっぷんえんちょうされました。","example_meaning":"Cuộc họp đã bị kéo dài thêm ba mươi phút."},{"example":"図書館の貸し出し期間を一週間延長してもらいました。","example_reading":"としょかんのかしだしきかんをいっしゅうかんえんちょうしてもらいました。","example_meaning":"Tôi đã được gia hạn thời gian mượn sách thư viện thêm một tuần."}]},{"word":"延滞","reading":"えんたい","meaning":"trễ hạn, chậm trả (đã quá hạn)","example":"家賃の支払いが延滞しています。","example_reading":"やちんのしはらいがえんたいしています。","example_meaning":"Việc trả tiền nhà đang bị trễ hạn.","examples":[{"example":"図書館の本を延滞して、延滞料を払いました。","example_reading":"としょかんのほんをえんたいして、えんたいりょうをはらいました。","example_meaning":"Tôi trả sách thư viện trễ hạn nên đã phải nộp phí phạt."},{"example":"カードの支払いが延滞すると、利息がかかります。","example_reading":"かーどのしはらいがえんたいすると、りそくがかかります。","example_meaning":"Nếu chậm thanh toán thẻ thì sẽ bị tính lãi."}]}]},
{"label":"必要／大切／重要","note":"必要(ひつよう): CẦN THIẾT (không có thì không được). 大切(たいせつ): QUAN TRỌNG mang tính tình cảm, trân trọng. 重要(じゅうよう): QUAN TRỌNG mang tính khách quan, ảnh hưởng lớn.","items":[{"word":"必要","reading":"ひつよう","meaning":"cần thiết","example":"水は生きるために必要です。","example_reading":"みずはいきるためにひつようです。","example_meaning":"Nước là thứ cần thiết để sống.","examples":[{"example":"旅行にはパスポートが必要です。","example_reading":"りょこうにはぱすぽーとがひつようです。","example_meaning":"Đi du lịch thì cần có hộ chiếu."},{"example":"手伝いが必要なら、いつでも言ってください。","example_reading":"てつだいがひつようなら、いつでもいってください。","example_meaning":"Nếu cần giúp đỡ thì cứ nói với tôi bất cứ lúc nào."}]},{"word":"大切","reading":"たいせつ","meaning":"quan trọng, trân trọng","example":"家族は私にとって大切です。","example_reading":"かぞくはわたしにとってたいせつです。","example_meaning":"Gia đình rất quan trọng và đáng trân trọng đối với tôi.","examples":[{"example":"友達からもらった手紙を大切にしています。","example_reading":"ともだちからもらったてがみをたいせつにしています。","example_meaning":"Tôi trân trọng lá thư nhận được từ bạn."},{"example":"時間を大切に使いましょう。","example_reading":"じかんをたいせつにつかいましょう。","example_meaning":"Hãy trân trọng và sử dụng thời gian thật tốt."}]},{"word":"重要","reading":"じゅうよう","meaning":"quan trọng (khách quan, ảnh hưởng lớn)","example":"これは重要な会議です。","example_reading":"これはじゅうようなかいぎです。","example_meaning":"Đây là một cuộc họp quan trọng.","examples":[{"example":"パスポートは重要な書類ですから、なくさないでください。","example_reading":"ぱすぽーとはじゅうようなしょるいですから、なくさないでください。","example_meaning":"Hộ chiếu là giấy tờ quan trọng nên đừng làm mất."},{"example":"彼の発言は、今後の計画に重要な影響を与えました。","example_reading":"かれのはつげんは、こんごのけいかくにじゅうようなえいきょうをあたえました。","example_meaning":"Phát biểu của anh ấy đã ảnh hưởng lớn đến kế hoạch sắp tới."}]}]},
{"label":"心配／不安","note":"心配(しんぱい): LO LẮNG cho một đối tượng/sự việc cụ thể, thường hướng ra ngoài. 不安(ふあん): BẤT AN, cảm giác lo âu mơ hồ về tương lai, hướng vào cảm xúc bản thân.","items":[{"word":"心配","reading":"しんぱい","meaning":"lo lắng (cho ai/việc gì đó)","example":"子供の健康が心配です。","example_reading":"こどものけんこうがしんぱいです。","example_meaning":"Tôi lo lắng cho sức khỏe của con.","examples":[{"example":"夜になっても娘が帰らないので、心配しています。","example_reading":"よるになってもむすめがかえらないので、しんぱいしています。","example_meaning":"Trời tối rồi mà con gái chưa về nên tôi đang lo."},{"example":"私のことは心配しなくても大丈夫ですよ。","example_reading":"わたしのことはしんぱいしなくてもだいじょうぶですよ。","example_meaning":"Đừng lo cho tôi, tôi ổn mà."}]},{"word":"不安","reading":"ふあん","meaning":"bất an, lo âu (cảm giác mơ hồ)","example":"将来に不安を感じます。","example_reading":"しょうらいにふあんをかんじます。","example_meaning":"Tôi cảm thấy bất an về tương lai.","examples":[{"example":"初めての海外生活に、少し不安があります。","example_reading":"はじめてのかいがいせいかつに、すこしふあんがあります。","example_meaning":"Tôi hơi bất an về cuộc sống ở nước ngoài lần đầu tiên."},{"example":"理由はわからないが、なんとなく不安で眠れない。","example_reading":"りゆうはわからないが、なんとなくふあんでねむれない。","example_meaning":"Không rõ lý do nhưng cứ thấy bất an nên không ngủ được."}]}]},
{"label":"残念／悲しい","note":"残念(ざんねん): TIẾC NUỐI, đáng tiếc (khi kỳ vọng không thành). 悲しい(かなしい): BUỒN, đau lòng về mặt cảm xúc sâu sắc hơn.","items":[{"word":"残念","reading":"ざんねん","meaning":"tiếc, đáng tiếc","example":"試合に負けて残念です。","example_reading":"しあいにまけてざんねんです。","example_meaning":"Thua trận đấu thật đáng tiếc.","examples":[{"example":"雨で旅行が中止になって、とても残念でした。","example_reading":"あめでりょこうがちゅうしになって、とてもざんねんでした。","example_meaning":"Chuyến du lịch bị hủy vì mưa, thật đáng tiếc."},{"example":"残念ながら、そのパーティーには行けません。","example_reading":"ざんねんながら、そのぱーてぃーにはいけません。","example_meaning":"Tiếc là tôi không thể đến bữa tiệc đó."}]},{"word":"悲しい","reading":"かなしい","meaning":"buồn, đau lòng","example":"ペットが死んで悲しいです。","example_reading":"ぺっとがしんでかなしいです。","example_meaning":"Thú cưng mất khiến tôi buồn.","examples":[{"example":"親友が遠くへ引っ越してしまって、悲しいです。","example_reading":"しんゆうがとおくへひっこしてしまって、かなしいです。","example_meaning":"Bạn thân chuyển đến nơi xa, tôi thấy buồn."},{"example":"悲しい映画を見て、涙が止まりませんでした。","example_reading":"かなしいえいがをみて、なみだがとまりませんでした。","example_meaning":"Xem bộ phim buồn, nước mắt tôi không ngừng rơi."}]}]},
{"label":"気持ち／気分","note":"気持ち(きもち): CẢM XÚC/TÌNH CẢM nói chung, có thể hướng đến người khác (biết ơn, yêu thích). 気分(きぶん): TRẠNG THÁI TINH THẦN/THỂ CHẤT nhất thời của bản thân (vui, mệt, khó chịu).","items":[{"word":"気持ち","reading":"きもち","meaning":"cảm xúc, tình cảm","example":"感謝の気持ちを伝えます。","example_reading":"かんしゃのきもちをつたえます。","example_meaning":"Truyền đạt lòng biết ơn.","examples":[{"example":"相手の気持ちを考えて話しましょう。","example_reading":"あいてのきもちをかんがえてはなしましょう。","example_meaning":"Hãy nghĩ đến cảm xúc của đối phương khi nói chuyện."},{"example":"彼女に好きだという気持ちを伝えたいです。","example_reading":"かのじょにすきだというきもちをつたえたいです。","example_meaning":"Tôi muốn nói với cô ấy tình cảm yêu thích của mình."}]},{"word":"気分","reading":"きぶん","meaning":"trạng thái tinh thần nhất thời","example":"今日は気分がいいです。","example_reading":"きょうはきぶんがいいです。","example_meaning":"Hôm nay tâm trạng tôi tốt.","examples":[{"example":"朝から気分が悪くて、会社を休みました。","example_reading":"あさからきぶんがわるくて、かいしゃをやすみました。","example_meaning":"Từ sáng đã thấy khó chịu trong người nên tôi nghỉ làm."},{"example":"気分を変えるために、散歩に行きました。","example_reading":"きぶんをかえるために、さんぽにいきました。","example_meaning":"Tôi đi dạo để đổi tâm trạng."}]}]},
{"label":"習慣／癖","note":"習慣(しゅうかん): THÓI QUEN tốt, được hình thành có ý thức, thường trung tính hoặc tích cực. 癖(くせ): TẬT, thói quen nhỏ vô thức, thường mang sắc thái hơi tiêu cực.","items":[{"word":"習慣","reading":"しゅうかん","meaning":"thói quen (có ý thức)","example":"毎朝運動する習慣があります。","example_reading":"まいあさうんどうするしゅうかんがあります。","example_meaning":"Tôi có thói quen tập thể dục mỗi sáng.","examples":[{"example":"寝る前に本を読むのが私の習慣です。","example_reading":"ねるまえにほんをよむのがわたしのしゅうかんです。","example_meaning":"Đọc sách trước khi ngủ là thói quen của tôi."},{"example":"日本には、食事の前に「いただきます」と言う習慣があります。","example_reading":"にほんには、しょくじのまえに「いただきます」というしゅうかんがあります。","example_meaning":"Ở Nhật có tập quán nói \"Itadakimasu\" trước bữa ăn."}]},{"word":"癖","reading":"くせ","meaning":"tật, thói quen vô thức","example":"爪を噛む癖があります。","example_reading":"つめをかむくせがあります。","example_meaning":"Tôi có tật cắn móng tay.","examples":[{"example":"考えるとき、髪を触る癖があります。","example_reading":"かんがえるとき、かみをさわるくせがあります。","example_meaning":"Tôi có tật hay sờ tóc mỗi khi suy nghĩ."},{"example":"悪い癖はなかなか直りません。","example_reading":"わるいくせはなかなかなおりません。","example_meaning":"Tật xấu mãi không sửa được."}]}]},
{"label":"経験／体験","note":"経験(けいけん): KINH NGHIỆM tích lũy qua nhiều lần, mang tính kiến thức/kỹ năng. 体験(たいけん): TRẢI NGHIỆM một lần cụ thể, nhấn mạnh cảm nhận trực tiếp bằng cơ thể.","items":[{"word":"経験","reading":"けいけん","meaning":"kinh nghiệm (tích lũy)","example":"仕事の経験が豊富です。","example_reading":"しごとのけいけんがほうふです。","example_meaning":"Có nhiều kinh nghiệm làm việc.","examples":[{"example":"彼は教師として二十年の経験があります。","example_reading":"かれはきょうしとしてにじゅうねんのけいけんがあります。","example_meaning":"Anh ấy có hai mươi năm kinh nghiệm làm giáo viên."},{"example":"失敗も大切な経験になります。","example_reading":"しっぱいもたいせつなけいけんになります。","example_meaning":"Thất bại cũng trở thành kinh nghiệm quý giá."}]},{"word":"体験","reading":"たいけん","meaning":"trải nghiệm (một lần cụ thể)","example":"農業を体験しました。","example_reading":"のうぎょうをたいけんしました。","example_meaning":"Tôi đã trải nghiệm làm nông nghiệp.","examples":[{"example":"京都で着物を着る体験をしました。","example_reading":"きょうとできものをきるたいけんをしました。","example_meaning":"Tôi đã trải nghiệm mặc kimono ở Kyoto."},{"example":"先週、陶芸の体験教室に参加しました。","example_reading":"せんしゅう、とうげいのたいけんきょうしつにさんかしました。","example_meaning":"Tuần trước tôi đã tham gia lớp trải nghiệm làm gốm."}]}]},
{"label":"理由／原因","note":"理由(りゆう): LÝ DO cho một hành động/quyết định có chủ ý (mang tính chủ quan). 原因(げんいん): NGUYÊN NHÂN dẫn đến một kết quả/hiện tượng (mang tính khách quan).","items":[{"word":"理由","reading":"りゆう","meaning":"lý do (cho hành động có chủ ý)","example":"遅刻した理由を説明します。","example_reading":"ちこくしたりゆうをせつめいします。","example_meaning":"Giải thích lý do đi trễ.","examples":[{"example":"仕事を辞めた理由を教えてください。","example_reading":"しごとをやめたりゆうをおしえてください。","example_meaning":"Hãy cho tôi biết lý do anh nghỉ việc."},{"example":"理由もなく、人を疑ってはいけません。","example_reading":"りゆうもなく、ひとをうたがってはいけません。","example_meaning":"Không được nghi ngờ người khác mà không có lý do."}]},{"word":"原因","reading":"げんいん","meaning":"nguyên nhân (khách quan)","example":"事故の原因を調べます。","example_reading":"じこのげんいんをしらべます。","example_meaning":"Điều tra nguyên nhân tai nạn.","examples":[{"example":"火事の原因は、たばこの火だったそうです。","example_reading":"かじのげんいんは、たばこのひだったそうです。","example_meaning":"Nghe nói nguyên nhân vụ cháy là do tàn thuốc lá."},{"example":"寝不足が頭痛の原因かもしれません。","example_reading":"ねぶそくがずつうのげんいんかもしれません。","example_meaning":"Có thể thiếu ngủ là nguyên nhân gây đau đầu."}]}]},
{"label":"用事／用件","note":"用事(ようじ): VIỆC BẬN, việc cần làm nói chung (thường là việc cá nhân). 用件(ようけん): NỘI DUNG CÔNG VIỆC cụ thể cần trao đổi, thường dùng trong ngữ cảnh công việc/liên lạc.","items":[{"word":"用事","reading":"ようじ","meaning":"việc bận, việc cần làm","example":"急な用事ができました。","example_reading":"きゅうなようじができました。","example_meaning":"Tôi có việc gấp phát sinh.","examples":[{"example":"今日は用事があるので、先に帰ります。","example_reading":"きょうはようじがあるので、さきにかえります。","example_meaning":"Hôm nay tôi có việc bận nên xin về trước."},{"example":"銀行や郵便局など、いくつか用事を済ませてきました。","example_reading":"ぎんこうやゆうびんきょくなど、いくつかようじをすませてきました。","example_meaning":"Tôi đã giải quyết vài việc như đi ngân hàng, bưu điện."}]},{"word":"用件","reading":"ようけん","meaning":"nội dung công việc cần trao đổi","example":"ご用件をお伺いします。","example_reading":"ごようけんをおうかがいします。","example_meaning":"Xin cho biết nội dung quý khách cần trao đổi.","examples":[{"example":"用件を手短にお話しください。","example_reading":"ようけんをてみじかにおはなしください。","example_meaning":"Xin hãy trình bày ngắn gọn nội dung cần trao đổi."},{"example":"電話の用件は、来週の打ち合わせについてでした。","example_reading":"でんわのようけんは、らいしゅうのうちあわせについてでした。","example_meaning":"Nội dung cuộc gọi là về buổi họp bàn tuần sau."}]}]},
{"label":"賛成／同意","note":"賛成(さんせい): TÁN THÀNH một ý kiến/đề xuất cụ thể (thường trong cuộc họp, biểu quyết). 同意(どうい): ĐỒNG Ý, thể hiện sự nhất trí về quan điểm nói chung, đôi khi mang tính pháp lý (đồng ý điều khoản).","items":[{"word":"賛成","reading":"さんせい","meaning":"tán thành (ý kiến, đề xuất)","example":"その意見に賛成です。","example_reading":"そのいけんにさんせいです。","example_meaning":"Tôi tán thành ý kiến đó.","examples":[{"example":"私は駅前に公園を作る案に賛成です。","example_reading":"わたしはえきまえにこうえんをつくるあんにさんせいです。","example_meaning":"Tôi tán thành đề xuất xây công viên trước nhà ga."},{"example":"賛成の人は、手を挙げてください。","example_reading":"さんせいのひとは、てをあげてください。","example_meaning":"Ai tán thành xin giơ tay."}]},{"word":"同意","reading":"どうい","meaning":"đồng ý (quan điểm/điều khoản)","example":"契約内容に同意しました。","example_reading":"けいやくないようにどういしました。","example_meaning":"Tôi đã đồng ý với nội dung hợp đồng.","examples":[{"example":"利用規約に同意してから、登録してください。","example_reading":"りようきやくにどういしてから、とうろくしてください。","example_meaning":"Hãy đồng ý với điều khoản sử dụng rồi mới đăng ký."},{"example":"彼の意見には全面的に同意します。","example_reading":"かれのいけんにはぜんめんてきにどういします。","example_meaning":"Tôi hoàn toàn đồng ý với ý kiến của anh ấy."}]}]},
{"label":"苦手／下手","note":"苦手(にがて): KHÔNG GIỎI/NGẠI làm gì, mang cả yếu tố cảm xúc (không thích, sợ). 下手(へた): VỤNG, KÉM về mặt kỹ năng thuần túy, không liên quan cảm xúc.","items":[{"word":"苦手","reading":"にがて","meaning":"không giỏi, ngại (có yếu tố cảm xúc)","example":"人前で話すのが苦手です。","example_reading":"ひとまえではなすのがにがてです。","example_meaning":"Tôi ngại nói trước đám đông.","examples":[{"example":"私は辛い食べ物が苦手です。","example_reading":"わたしはからいたべものがにがてです。","example_meaning":"Tôi không ăn được đồ cay."},{"example":"数学は嫌いではありませんが、少し苦手です。","example_reading":"すうがくはきらいではありませんが、すこしにがてです。","example_meaning":"Tôi không ghét toán nhưng hơi ngại nó."}]},{"word":"下手","reading":"へた","meaning":"vụng, kém (kỹ năng)","example":"字が下手です。","example_reading":"じがへたです。","example_meaning":"Chữ viết của tôi xấu.","examples":[{"example":"私は歌が下手なので、カラオケには行きません。","example_reading":"わたしはうたがへたなので、からおけにはいきません。","example_meaning":"Tôi hát dở nên không đi karaoke."},{"example":"下手でもいいから、自分で絵を描いてみましょう。","example_reading":"へたでもいいから、じぶんでえをかいてみましょう。","example_meaning":"Vụng cũng không sao, hãy thử tự vẽ tranh xem."}]}]},
{"label":"上手／得意","note":"上手(じょうず): GIỎI về mặt kỹ năng, thường dùng để khen người khác (khách quan). 得意(とくい): SỞ TRƯỜNG, tự tin vào khả năng của bản thân (mang tính chủ quan, tự đánh giá).","items":[{"word":"上手","reading":"じょうず","meaning":"giỏi (kỹ năng, khách quan)","example":"彼はピアノが上手です。","example_reading":"かれはぴあのがじょうずです。","example_meaning":"Anh ấy chơi piano giỏi.","examples":[{"example":"彼女は日本語を話すのが上手ですね。","example_reading":"かのじょはにほんごをはなすのがじょうずですね。","example_meaning":"Cô ấy nói tiếng Nhật giỏi nhỉ."},{"example":"母は料理の上手な人です。","example_reading":"ははははりょうりのじょうずなひとです。","example_meaning":"Mẹ tôi là người nấu ăn giỏi."}]},{"word":"得意","reading":"とくい","meaning":"sở trường, tự tin (chủ quan)","example":"料理が得意です。","example_reading":"りょうりがとくいです。","example_meaning":"Nấu ăn là sở trường của tôi.","examples":[{"example":"私は数学が得意で、よく友達に教えます。","example_reading":"わたしはすうがくがとくいで、よくともだちにおしえます。","example_meaning":"Tôi giỏi toán nên hay kèm bạn bè."},{"example":"彼の得意な料理はカレーです。","example_reading":"かれのとくいなりょうりはかれーです。","example_meaning":"Món sở trường của anh ấy là cà ri."}]}]},
{"label":"邪魔／迷惑","note":"邪魔(じゃま): CẢN TRỞ trực tiếp một hành động cụ thể đang diễn ra. 迷惑(めいわく): GÂY PHIỀN, làm phiền lòng người khác nói chung, phạm vi rộng hơn.","items":[{"word":"邪魔","reading":"じゃま","meaning":"cản trở (hành động cụ thể)","example":"勉強の邪魔をしないでください。","example_reading":"べんきょうのじゃまをしないでください。","example_meaning":"Đừng cản trở việc học của tôi.","examples":[{"example":"そこに立たれると邪魔なので、どいてください。","example_reading":"そこにたたれるとじゃまなので、どいてください。","example_meaning":"Bạn đứng đó thì vướng, làm ơn tránh ra."},{"example":"仕事中に電話が来て、邪魔されました。","example_reading":"しごとちゅうにでんわがきて、じゃまされました。","example_meaning":"Đang làm việc thì có điện thoại gọi đến làm gián đoạn."}]},{"word":"迷惑","reading":"めいわく","meaning":"gây phiền (rộng hơn)","example":"近所に迷惑をかけました。","example_reading":"きんじょにめいわくをかけました。","example_meaning":"Tôi đã làm phiền hàng xóm.","examples":[{"example":"電車の中で大きな声で話すと、他の人の迷惑になります。","example_reading":"でんしゃのなかでおおきなこえではなすと、ほかのひとのめいわくになります。","example_meaning":"Nói to trong tàu điện sẽ gây phiền cho người khác."},{"example":"夜遅くに電話をして、ご迷惑ではなかったですか。","example_reading":"よるおそくにでんわをして、ごめいわくではなかったですか。","example_meaning":"Tôi gọi điện muộn thế này, có làm phiền anh không?"}]}]},
{"label":"変更／変化","note":"変更(へんこう): THAY ĐỔI có chủ ý, do con người quyết định (lịch trình, kế hoạch). 変化(へんか): BIẾN ĐỔI tự nhiên, diễn ra theo thời gian, không nhất thiết có chủ ý.","items":[{"word":"変更","reading":"へんこう","meaning":"thay đổi (có chủ ý)","example":"予定を変更しました。","example_reading":"よていをへんこうしました。","example_meaning":"Tôi đã thay đổi lịch trình.","examples":[{"example":"住所が変わったので、登録を変更します。","example_reading":"じゅうしょがかわったので、とうろくをへんこうします。","example_meaning":"Vì địa chỉ đã đổi nên tôi sẽ thay đổi thông tin đăng ký."},{"example":"会議の時間が三時に変更になりました。","example_reading":"かいぎのじかんがさんじにへんこうになりました。","example_meaning":"Giờ họp đã được đổi sang ba giờ."}]},{"word":"変化","reading":"へんか","meaning":"biến đổi (tự nhiên, theo thời gian)","example":"気候が変化しています。","example_reading":"きこうがへんかしています。","example_meaning":"Khí hậu đang biến đổi.","examples":[{"example":"十年で町は大きく変化しました。","example_reading":"じゅうねんでまちはおおきくへんかしました。","example_meaning":"Trong mười năm, thành phố đã biến đổi rất nhiều."},{"example":"季節の変化で、体調をくずす人が多いです。","example_reading":"きせつのへんかで、たいちょうをくずすひとがおおいです。","example_meaning":"Nhiều người đổ bệnh vì thời tiết thay đổi theo mùa."}]}]},
{"label":"準備／用意","note":"準備(じゅんび): CHUẨN BỊ mang tính quá trình, kỹ lưỡng, có thể kéo dài. 用意(ようい): CHUẨN BỊ SẴN SÀNG một thứ cụ thể, thường nhanh gọn hơn, mang tính 'đã sẵn'.","items":[{"word":"準備","reading":"じゅんび","meaning":"chuẩn bị (quá trình, kỹ lưỡng)","example":"試験の準備をしています。","example_reading":"しけんのじゅんびをしています。","example_meaning":"Tôi đang chuẩn bị cho kỳ thi.","examples":[{"example":"明日の発表の準備はもう終わりましたか。","example_reading":"あしたのはっぴょうのじゅんびはもうおわりましたか。","example_meaning":"Bạn đã chuẩn bị xong cho bài thuyết trình ngày mai chưa?"},{"example":"旅行に行く前に、少しずつ準備を進めています。","example_reading":"りょこうにいくまえに、すこしずつじゅんびをすすめています。","example_meaning":"Trước chuyến du lịch, tôi đang chuẩn bị dần dần."}]},{"word":"用意","reading":"ようい","meaning":"chuẩn bị sẵn (một thứ cụ thể)","example":"朝ごはんを用意しました。","example_reading":"あさごはんをよういしました。","example_meaning":"Tôi đã chuẩn bị sẵn bữa sáng.","examples":[{"example":"お客さんのために、お茶とお菓子を用意しました。","example_reading":"おきゃくさんのために、おちゃとおかしをよういしました。","example_meaning":"Tôi đã chuẩn bị sẵn trà và bánh cho khách."},{"example":"傘を用意しておいたほうがいいですよ。","example_reading":"かさをよういしておいたほうがいいですよ。","example_meaning":"Bạn nên chuẩn bị sẵn ô thì hơn."}]}]},
{"label":"授業／講義","note":"授業(じゅぎょう): TIẾT HỌC nói chung, dùng cho mọi cấp học (tiểu học đến đại học). 講義(こうぎ): BÀI GIẢNG, thường chỉ dùng ở bậc ĐẠI HỌC trở lên, mang tính học thuật.","items":[{"word":"授業","reading":"じゅぎょう","meaning":"tiết học (nói chung)","example":"今日は授業が三つあります。","example_reading":"きょうはじゅぎょうがみっつあります。","example_meaning":"Hôm nay tôi có ba tiết học.","examples":[{"example":"授業中は携帯電話の電源を切ってください。","example_reading":"じゅぎょうちゅうはけいたいでんわのでんげんをきってください。","example_meaning":"Trong giờ học hãy tắt nguồn điện thoại."},{"example":"先生の授業はわかりやすくて、おもしろいです。","example_reading":"せんせいのじゅぎょうはわかりやすくて、おもしろいです。","example_meaning":"Giờ học của thầy dễ hiểu và thú vị."}]},{"word":"講義","reading":"こうぎ","meaning":"bài giảng (đại học, học thuật)","example":"経済学の講義を受けます。","example_reading":"けいざいがくのこうぎをうけます。","example_meaning":"Tôi nghe bài giảng kinh tế học.","examples":[{"example":"大学で歴史の講義を聞きました。","example_reading":"だいがくでれきしのこうぎをききました。","example_meaning":"Tôi đã nghe bài giảng lịch sử ở đại học."},{"example":"教授の講義はレベルが高くて、メモが大変です。","example_reading":"きょうじゅのこうぎはれべるがたかくて、めもがたいへんです。","example_meaning":"Bài giảng của giáo sư trình độ cao nên ghi chép rất vất vả."}]}]},
{"label":"給料／収入","note":"給料(きゅうりょう): LƯƠNG nhận từ công ty (một nguồn cụ thể). 収入(しゅうにゅう): THU NHẬP nói chung, có thể gồm nhiều nguồn (lương, đầu tư, kinh doanh...).","items":[{"word":"給料","reading":"きゅうりょう","meaning":"lương (từ công ty)","example":"来週給料をもらいます。","example_reading":"らいしゅうきゅうりょうをもらいます。","example_meaning":"Tuần sau tôi nhận lương.","examples":[{"example":"給料が出たら、家族に何かプレゼントしたいです。","example_reading":"きゅうりょうがでたら、かぞくになにかぷれぜんとしたいです。","example_meaning":"Khi nhận lương, tôi muốn tặng gia đình món quà gì đó."},{"example":"この会社は給料が高いので人気があります。","example_reading":"このかいしゃはきゅうりょうがたかいのでにんきがあります。","example_meaning":"Công ty này lương cao nên được ưa chuộng."}]},{"word":"収入","reading":"しゅうにゅう","meaning":"thu nhập (nói chung, nhiều nguồn)","example":"副業で収入が増えました。","example_reading":"ふくぎょうでしゅうにゅうがふえました。","example_meaning":"Thu nhập của tôi tăng nhờ làm thêm nghề tay trái.","examples":[{"example":"年間の収入が増えて、税金も多くなりました。","example_reading":"ねんかんのしゅうにゅうがふえて、ぜいきんもおおくなりました。","example_meaning":"Thu nhập hằng năm tăng nên thuế cũng nhiều hơn."},{"example":"彼は不安定な収入で生活しています。","example_reading":"かれはふあんていなしゅうにゅうでせいかつしています。","example_meaning":"Anh ấy sống bằng nguồn thu nhập không ổn định."}]}]},
{"label":"責任／義務","note":"責任(せきにん): TRÁCH NHIỆM, hậu quả mà người ta phải gánh chịu nếu làm sai/không làm. 義務(ぎむ): NGHĨA VỤ, việc bắt buộc phải làm theo quy định/pháp luật/đạo đức.","items":[{"word":"責任","reading":"せきにん","meaning":"trách nhiệm (gánh chịu hậu quả)","example":"この失敗の責任を取ります。","example_reading":"このしっぱいのせきにんをとります。","example_meaning":"Tôi sẽ chịu trách nhiệm về thất bại này.","examples":[{"example":"部長は、部下のミスに対して責任があります。","example_reading":"ぶちょうは、ぶかのみすにたいしてせきにんがあります。","example_meaning":"Trưởng phòng có trách nhiệm với lỗi của cấp dưới."},{"example":"自分の言葉には責任を持ちなさい。","example_reading":"じぶんのことばにはせきにんをもちなさい。","example_meaning":"Hãy chịu trách nhiệm về lời nói của mình."}]},{"word":"義務","reading":"ぎむ","meaning":"nghĩa vụ (bắt buộc theo quy định)","example":"税金を納めるのは国民の義務です。","example_reading":"ぜいきんをおさめるのはこくみんのぎむです。","example_meaning":"Nộp thuế là nghĩa vụ của công dân.","examples":[{"example":"子供に教育を受けさせるのは、親の義務です。","example_reading":"こどもにきょういくをうけさせるのは、おやのぎむです。","example_meaning":"Cho con cái đi học là nghĩa vụ của cha mẹ."},{"example":"日本では、車に乗るとき、シートベルトをする義務があります。","example_reading":"にほんでは、くるまにのるとき、しーとべるとをするぎむがあります。","example_meaning":"Ở Nhật, khi đi ô tô có nghĩa vụ phải thắt dây an toàn."}]}]},
{"label":"見る／眺める／見つめる","note":"見る: 'nhìn/xem' chung nhất, dùng cho mọi trường hợp (xem TV, nhìn bản đồ). 眺める: ngắm nhìn phong cảnh từ xa, thong thả, thư thái. 見つめる: nhìn chăm chú, không rời mắt vào một đối tượng (mắt, mặt, tương lai), thường mang cảm xúc.","items":[{"word":"見る","reading":"みる","meaning":"nhìn, xem","example":"毎晩、テレビでニュースを見ます。","example_reading":"まいばん、てれびでにゅーすをみます。","example_meaning":"Mỗi tối tôi xem tin tức trên tivi.","examples":[{"example":"私は昨日、友達と映画を見ました。","example_reading":"わたしはきのう、ともだちとえいがをみました。","example_meaning":"Hôm qua tôi đã xem phim với bạn."},{"example":"机の上の地図を見てください。","example_reading":"つくえのうえのちずをみてください。","example_meaning":"Hãy nhìn bản đồ trên bàn."}]},{"word":"眺める","reading":"ながめる","meaning":"ngắm nhìn, phóng tầm mắt","example":"山の上から、町の景色を眺めた。","example_reading":"やまのうえから、まちのけしきをながめた。","example_meaning":"Tôi ngắm cảnh thị trấn từ trên núi.","examples":[{"example":"窓から海をぼんやり眺めるのが好きだ。","example_reading":"まどからうみをぼんやりながめるのがすきだ。","example_meaning":"Tôi thích thẫn thờ ngắm biển từ cửa sổ."},{"example":"彼は縁側に座って、庭の桜を眺めていた。","example_reading":"かれはえんがわにすわって、にわのさくらをながめていた。","example_meaning":"Anh ấy ngồi ở hiên nhà ngắm hoa anh đào trong vườn."}]},{"word":"見つめる","reading":"みつめる","meaning":"nhìn chăm chú, nhìn đăm đăm","example":"彼女は黙って私の目を見つめた。","example_reading":"かのじょはだまってわたしのめをみつめた。","example_meaning":"Cô ấy im lặng nhìn chăm chú vào mắt tôi.","examples":[{"example":"赤ちゃんがお母さんの顔をじっと見つめている。","example_reading":"あかちゃんがおかあさんのかおをじっとみつめている。","example_meaning":"Em bé đang nhìn chăm chú vào mặt mẹ."},{"example":"自分の将来を真剣に見つめ直したい。","example_reading":"じぶんのしょうらいをしんけんにみつめなおしたい。","example_meaning":"Tôi muốn nghiêm túc nhìn lại tương lai của mình."}]}]},
{"label":"話す／言う／しゃべる","note":"話す: nói chuyện, kể, nói một ngôn ngữ (có nội dung, có người nghe). 言う: nói ra lời/câu cụ thể, trích dẫn (〜と言う). しゃべる: nói liến thoắng, tán gẫu, đôi khi lỡ miệng tiết lộ; sắc thái thân mật, suồng sã.","items":[{"word":"話す","reading":"はなす","meaning":"nói chuyện, kể","example":"先生と進路について話しました。","example_reading":"せんせいとしんろについてはなしました。","example_meaning":"Tôi đã nói chuyện với thầy về hướng đi tương lai.","examples":[{"example":"昨日、友達に旅行の計画を話した。","example_reading":"きのう、ともだちにりょこうのけいかくをはなした。","example_meaning":"Hôm qua tôi đã kể cho bạn về kế hoạch du lịch."},{"example":"彼は英語を話すのが上手です。","example_reading":"かれはえいごをはなすのがじょうずです。","example_meaning":"Anh ấy nói tiếng Anh giỏi."}]},{"word":"言う","reading":"いう","meaning":"nói, bảo","example":"「ありがとう」と言うのを忘れました。","example_reading":"「ありがとう」というのをわすれました。","example_meaning":"Tôi đã quên nói 'cảm ơn'.","examples":[{"example":"彼は「明日は行けない」と言った。","example_reading":"かれは「あしたはいけない」といった。","example_meaning":"Anh ấy nói 'ngày mai tôi không đi được'."},{"example":"母に早く寝なさいと言われた。","example_reading":"ははにはやくねなさいといわれた。","example_meaning":"Tôi bị mẹ bảo đi ngủ sớm đi."}]},{"word":"しゃべる","reading":"しゃべる","meaning":"nói liến thoắng, tán gẫu","example":"彼女は友達と二時間もしゃべっていた。","example_reading":"かのじょはともだちとにじかんもしゃべっていた。","example_meaning":"Cô ấy đã tán gẫu với bạn tận hai tiếng.","examples":[{"example":"授業中にしゃべってはいけません。","example_reading":"じゅぎょうちゅうにしゃべってはいけません。","example_meaning":"Không được nói chuyện riêng trong giờ học."},{"example":"兄は口が軽くて、秘密をすぐ人にしゃべってしまう。","example_reading":"あにはくちがかるくて、ひみつをすぐひとにしゃべってしまう。","example_meaning":"Anh tôi lắm mồm, hay lỡ buột miệng nói bí mật cho người khác."}]}]},
{"label":"尋ねる／聞く／問う","note":"尋ねる: hỏi để biết thông tin, hơi trang trọng (hỏi đường, hỏi tên). 聞く: nghe; cũng là 'hỏi' thông thường, khẩu ngữ. 問う: đặt vấn đề, truy cứu (trách nhiệm), hỏi ý kiến; văn viết, trang trọng; 〜を問わず = bất kể.","items":[{"word":"尋ねる","reading":"たずねる","meaning":"hỏi (để biết), hỏi thăm","example":"道に迷って、通りがかりの人に駅への行き方を尋ねた。","example_reading":"みちにまよって、とおりがかりのひとにえきへのいきかたをたずねた。","example_meaning":"Bị lạc đường, tôi hỏi người đi ngang cách đến ga.","examples":[{"example":"警察官は男に名前と住所を尋ねた。","example_reading":"けいさつかんはおとこになまえとじゅうしょをたずねた。","example_meaning":"Cảnh sát hỏi người đàn ông tên và địa chỉ."},{"example":"先生にわからない点を尋ねました。","example_reading":"せんせいにわからないてんをたずねました。","example_meaning":"Tôi đã hỏi thầy những điểm không hiểu."}]},{"word":"聞く","reading":"きく","meaning":"nghe; hỏi","example":"駅へ行く道を駅員に聞きました。","example_reading":"えきへいくみちをえきいんにききました。","example_meaning":"Tôi hỏi nhân viên nhà ga đường đến ga.","examples":[{"example":"毎朝、音楽を聞きながら学校へ行く。","example_reading":"まいあさ、おんがくをききながらがっこうへいく。","example_meaning":"Mỗi sáng tôi vừa nghe nhạc vừa đến trường."},{"example":"友達からその話を聞いて、驚いた。","example_reading":"ともだちからそのはなしをきいて、おどろいた。","example_meaning":"Nghe bạn kể chuyện đó, tôi đã ngạc nhiên."}]},{"word":"問う","reading":"とう","meaning":"đặt câu hỏi, truy cứu, hỏi ý kiến","example":"事故の責任が問われている。","example_reading":"じこのせきにんがとわれている。","example_meaning":"Trách nhiệm về vụ tai nạn đang bị truy cứu.","examples":[{"example":"年齢や経験は問いません。","example_reading":"ねんれいやけいけんはといません。","example_meaning":"Không phân biệt tuổi tác hay kinh nghiệm."},{"example":"国民に信を問うために、選挙が行われた。","example_reading":"こくみんにしんをとうために、せんきょがおこなわれた。","example_meaning":"Cuộc bầu cử được tổ chức để hỏi ý kiến tín nhiệm của người dân."}]}]},
{"label":"考える／思う","note":"考える: suy nghĩ có logic, cân nhắc, nghĩ ra (quá trình dùng đầu óc). 思う: nghĩ/cảm thấy, ý kiến chủ quan, cảm xúc hay nhớ về ai đó (kết quả suy nghĩ, thường 〜と思う).","items":[{"word":"考える","reading":"かんがえる","meaning":"suy nghĩ, cân nhắc","example":"将来のことをよく考えてから決めます。","example_reading":"しょうらいのことをよくかんがえてからきめます。","example_meaning":"Tôi sẽ suy nghĩ kỹ về tương lai rồi mới quyết định.","examples":[{"example":"この問題の答えを三十分考えたが、わからなかった。","example_reading":"このもんだいのこたえをさんじゅっぷんかんがえたが、わからなかった。","example_meaning":"Tôi nghĩ đáp án bài này ba mươi phút mà vẫn không biết."},{"example":"新しい方法を考えるのは楽しい。","example_reading":"あたらしいほうほうをかんがえるのはたのしい。","example_meaning":"Nghĩ ra phương pháp mới thật thú vị."}]},{"word":"思う","reading":"おもう","meaning":"nghĩ, cảm thấy, nhớ về","example":"明日は雨が降ると思います。","example_reading":"あしたはあめがふるとおもいます。","example_meaning":"Tôi nghĩ ngày mai trời sẽ mưa.","examples":[{"example":"故郷の家族のことを思うと、寂しくなる。","example_reading":"こきょうのかぞくのことをおもうと、さびしくなる。","example_meaning":"Nghĩ đến gia đình ở quê, tôi thấy cô đơn."},{"example":"私はこの映画はとても面白いと思った。","example_reading":"わたしはこのえいがはとてもおもしろいとおもった。","example_meaning":"Tôi thấy bộ phim này rất hay."}]}]},
{"label":"探す／求める／探る","note":"探す: tìm thứ bị mất hoặc thứ mình muốn (đồ, nhà, việc). 求める: yêu cầu, mong cầu, tìm kiếm (sự giúp đỡ, nhân tài, điều kiện); trừu tượng. 探る: dò xét, thăm dò, mò mẫm tìm hiểu cái chưa rõ (ý đồ, động tĩnh).","items":[{"word":"探す","reading":"さがす","meaning":"tìm kiếm","example":"なくした鍵を部屋中探した。","example_reading":"なくしたかぎをへやじゅうさがした。","example_meaning":"Tôi tìm chiếc chìa khóa bị mất khắp phòng.","examples":[{"example":"新しいアパートを探しています。","example_reading":"あたらしいあぱーとをさがしています。","example_meaning":"Tôi đang tìm căn hộ mới."},{"example":"彼は仕事を探して、毎日面接に行っている。","example_reading":"かれはしごとをさがして、まいにちめんせつにいっている。","example_meaning":"Anh ấy đang tìm việc, ngày nào cũng đi phỏng vấn."}]},{"word":"求める","reading":"もとめる","meaning":"yêu cầu, mong cầu, tìm kiếm","example":"会社は経験のある人材を求めている。","example_reading":"かいしゃはけいけんのあるじんざいをもとめている。","example_meaning":"Công ty đang tìm kiếm nhân sự có kinh nghiệm.","examples":[{"example":"彼は警察に助けを求めた。","example_reading":"かれはけいさつにたすけをもとめた。","example_meaning":"Anh ấy đã cầu cứu cảnh sát."},{"example":"客は店に誠実な対応を求める。","example_reading":"きゃくはみせにせいじつなたいおうをもとめる。","example_meaning":"Khách hàng đòi hỏi cửa hàng ứng xử chân thành."}]},{"word":"探る","reading":"さぐる","meaning":"dò xét, thăm dò, mò tìm","example":"刑事は犯人の動きをこっそり探った。","example_reading":"けいじははんにんのうごきをこっそりさぐった。","example_meaning":"Thám tử lén dò xét động tĩnh của hung thủ.","examples":[{"example":"彼の本心を探るために、遠回しに質問した。","example_reading":"かれのほんしんをさぐるために、とおまわしにしつもんした。","example_meaning":"Để dò ý thật của anh ta, tôi hỏi vòng vo."},{"example":"暗闇の中、手で壁を探りながら進んだ。","example_reading":"くらやみのなか、てでかべをさぐりながらすすんだ。","example_meaning":"Trong bóng tối, tôi lần mò tường bằng tay mà tiến lên."}]}]},
{"label":"買う／購入する","note":"買う: mua, từ thông dụng hằng ngày. 購入する: mua (cách nói trang trọng/văn bản, kinh doanh, thường đồ giá trị hoặc mua số lượng, hệ thống).","items":[{"word":"買う","reading":"かう","meaning":"mua","example":"スーパーで牛乳とパンを買いました。","example_reading":"すーぱーでぎゅうにゅうとぱんをかいました。","example_meaning":"Tôi đã mua sữa và bánh mì ở siêu thị.","examples":[{"example":"誕生日に母へ花を買った。","example_reading":"たんじょうびにははへはなをかった。","example_meaning":"Tôi đã mua hoa tặng mẹ nhân dịp sinh nhật."},{"example":"新しい靴が欲しくて、安い店で買うつもりだ。","example_reading":"あたらしいくつがほしくて、やすいみせでかうつもりだ。","example_meaning":"Tôi muốn có đôi giày mới nên định mua ở cửa hàng rẻ."}]},{"word":"購入する","reading":"こうにゅうする","meaning":"mua (trang trọng)","example":"当店では、商品をオンラインで購入することができます。","example_reading":"とうてんでは、しょうひんをおんらいんでこうにゅうすることができます。","example_meaning":"Tại cửa hàng chúng tôi, quý khách có thể mua sản phẩm trực tuyến.","examples":[{"example":"会社は新しいシステムを購入した。","example_reading":"かいしゃはあたらしいしすてむをこうにゅうした。","example_meaning":"Công ty đã mua hệ thống mới."},{"example":"ご購入いただいた商品は三日以内にお届けします。","example_reading":"ごこうにゅういただいたしょうひんはみっかいないにおとどけします。","example_meaning":"Sản phẩm quý khách đã mua sẽ được giao trong vòng ba ngày."}]}]},
{"label":"使う／利用する／活用する","note":"使う: dùng (đồ vật, tiền, từ ngữ), nghĩa chung. 利用する: tận dụng/sử dụng dịch vụ, cơ sở, phương tiện (tàu, thư viện). 活用する: vận dụng hiệu quả để phát huy giá trị tối đa (thời gian, kiến thức, đồ cũ).","items":[{"word":"使う","reading":"つかう","meaning":"dùng, sử dụng","example":"このペンを使ってもいいですか。","example_reading":"このぺんをつかってもいいですか。","example_meaning":"Tôi dùng cây bút này được không?","examples":[{"example":"彼は毎日、お金をたくさん使う。","example_reading":"かれはまいにち、おかねをたくさんつかう。","example_meaning":"Anh ấy ngày nào cũng tiêu nhiều tiền."},{"example":"日本語の敬語は使い方が難しい。","example_reading":"にほんごのけいごはつかいかたがむずかしい。","example_meaning":"Kính ngữ tiếng Nhật khó ở cách dùng."}]},{"word":"利用する","reading":"りようする","meaning":"sử dụng (dịch vụ, cơ sở)","example":"通勤にはいつも電車を利用しています。","example_reading":"つうきんにはいつもでんしゃをりようしています。","example_meaning":"Tôi luôn đi tàu điện để đi làm.","examples":[{"example":"図書館は誰でも無料で利用できます。","example_reading":"としょかんはだれでもむりょうでりようできます。","example_meaning":"Ai cũng có thể sử dụng thư viện miễn phí."},{"example":"駐車場をご利用の方は、受付でお知らせください。","example_reading":"ちゅうしゃじょうをごりようのかたは、うけつけでおしらせください。","example_meaning":"Quý khách sử dụng bãi đỗ xe vui lòng báo tại quầy lễ tân."}]},{"word":"活用する","reading":"かつようする","meaning":"vận dụng, tận dụng hiệu quả","example":"空いた時間を活用して、資格の勉強をしている。","example_reading":"あいたじかんをかつようして、しかくのべんきょうをしている。","example_meaning":"Tôi tận dụng thời gian rảnh để học lấy chứng chỉ.","examples":[{"example":"学んだ知識を仕事に活用したい。","example_reading":"まなんだちしきをしごとにかつようしたい。","example_meaning":"Tôi muốn vận dụng kiến thức đã học vào công việc."},{"example":"古い建物を活用して、新しいカフェを作った。","example_reading":"ふるいたてものをかつようして、あたらしいかふぇをつくった。","example_meaning":"Họ tận dụng tòa nhà cũ để làm quán cà phê mới."}]}]},
{"label":"始める／開始／スタート","note":"始める: bắt đầu (động từ, bắt đầu hành động; 〜始める sau động từ). 開始: bắt đầu (danh từ Hán, trang trọng, sự kiện/thủ tục, hay dùng bị động 開始される). スタート: xuất phát/khởi đầu (katakana, đua, cuộc sống, dự án; sắc thái khởi hành).","items":[{"word":"始める","reading":"はじめる","meaning":"bắt đầu","example":"来週からピアノを習い始めます。","example_reading":"らいしゅうからぴあのをならいはじめます。","example_meaning":"Từ tuần sau tôi bắt đầu học piano.","examples":[{"example":"先生は九時に授業を始めた。","example_reading":"せんせいはくじにじゅぎょうをはじめた。","example_meaning":"Thầy bắt đầu buổi học lúc chín giờ."},{"example":"そろそろ勉強を始めよう。","example_reading":"そろそろべんきょうをはじめよう。","example_meaning":"Sắp đến lúc bắt đầu học rồi."}]},{"word":"開始","reading":"かいし","meaning":"khởi đầu, bắt đầu (trang trọng)","example":"試合は午後一時に開始される。","example_reading":"しあいはごごいちじにかいしされる。","example_meaning":"Trận đấu sẽ bắt đầu lúc một giờ chiều.","examples":[{"example":"新商品の販売を開始しました。","example_reading":"しんしょうひんのはんばいをかいししました。","example_meaning":"Chúng tôi đã bắt đầu bán sản phẩm mới."},{"example":"工事の開始が一週間遅れた。","example_reading":"こうじのかいしがいっしゅうかんおくれた。","example_meaning":"Việc khởi công bị trễ một tuần."}]},{"word":"スタート","reading":"すたーと","meaning":"xuất phát, khởi đầu","example":"号砲と同時に、選手たちが一斉にスタートした。","example_reading":"ごうほうとどうじに、せんしゅたちがいっせいにすたーとした。","example_meaning":"Cùng lúc với tiếng súng lệnh, các vận động viên đồng loạt xuất phát.","examples":[{"example":"来月から新しい生活がスタートする。","example_reading":"らいげつからあたらしいせいかつがすたーとする。","example_meaning":"Từ tháng sau cuộc sống mới sẽ bắt đầu."},{"example":"彼女は小さな店からスタートして、大きな会社を作った。","example_reading":"かのじょはちいさなみせからすたーとして、おおきながいしゃをつくった。","example_meaning":"Cô ấy khởi nghiệp từ một cửa hàng nhỏ rồi xây dựng nên công ty lớn."}]}]},
{"label":"終わる／終了／完了","note":"終わる: kết thúc (động từ, tự nhiên, hết). 終了: kết thúc (trang trọng, thông báo, sự kiện/giờ hoạt động/đăng ký). 完了: hoàn tất, xong xuôi toàn bộ công việc/thao tác (nhấn mạnh đã làm xong hết).","items":[{"word":"終わる","reading":"おわる","meaning":"kết thúc, xong","example":"授業は三時に終わります。","example_reading":"じゅぎょうはさんじにおわります。","example_meaning":"Giờ học kết thúc lúc ba giờ.","examples":[{"example":"宿題が終わったら、遊びに行ってもいいよ。","example_reading":"しゅくだいがおわったら、あそびにいってもいいよ。","example_meaning":"Làm xong bài tập thì con có thể đi chơi."},{"example":"夏休みが終わって、また学校が始まった。","example_reading":"なつやすみがおわって、またがっこうがはじまった。","example_meaning":"Kỳ nghỉ hè kết thúc, trường lại bắt đầu."}]},{"word":"終了","reading":"しゅうりょう","meaning":"kết thúc (trang trọng)","example":"本日の営業は午後八時で終了します。","example_reading":"ほんじつのえいぎょうはごごはちじでしゅうりょうします。","example_meaning":"Hôm nay chúng tôi kết thúc kinh doanh lúc tám giờ tối.","examples":[{"example":"受付は先週で終了しました。","example_reading":"うけつけはせんしゅうでしゅうりょうしました。","example_meaning":"Việc tiếp nhận đăng ký đã kết thúc từ tuần trước."},{"example":"試験終了の合図があるまで、席を立たないでください。","example_reading":"しけんしゅうりょうのあいずがあるまで、せきをたたないでください。","example_meaning":"Xin đừng rời chỗ cho đến khi có hiệu lệnh kết thúc bài thi."}]},{"word":"完了","reading":"かんりょう","meaning":"hoàn tất","example":"引っ越しの準備がすべて完了した。","example_reading":"ひっこしのじゅんびがすべてかんりょうした。","example_meaning":"Việc chuẩn bị chuyển nhà đã hoàn tất toàn bộ.","examples":[{"example":"ダウンロードが完了しました。","example_reading":"だうんろーどがかんりょうしました。","example_meaning":"Việc tải xuống đã hoàn tất."},{"example":"登録の手続きは完了しています。","example_reading":"とうろくのてつづきはかんりょうしています。","example_meaning":"Thủ tục đăng ký đã hoàn tất."}]}]},
{"label":"助ける／手伝う／救う","note":"助ける: giúp đỡ người đang gặp khó khăn/nguy hiểm, cứu giúp. 手伝う: giúp một tay vào công việc (người chủ chính vẫn là người kia). 救う: cứu thoát khỏi nguy hiểm/khổ nạn nghiêm trọng, cứu mạng, cứu vớt tinh thần.","items":[{"word":"助ける","reading":"たすける","meaning":"giúp đỡ, cứu giúp","example":"川でおぼれている子どもを助けた。","example_reading":"かわでおぼれているこどもをたすけた。","example_meaning":"Tôi đã cứu đứa trẻ đang đuối nước ở sông.","examples":[{"example":"困っている人がいたら、助けてあげましょう。","example_reading":"こまっているひとがいたら、たすけてあげましょう。","example_meaning":"Nếu có người gặp khó khăn thì hãy giúp họ."},{"example":"事故にあった人を助けるために、救急車を呼んだ。","example_reading":"じこにあったひとをたすけるために、きゅうきゅうしゃをよんだ。","example_meaning":"Tôi đã gọi xe cứu thương để giúp người bị tai nạn."}]},{"word":"手伝う","reading":"てつだう","meaning":"giúp một tay","example":"母の料理を手伝いました。","example_reading":"ははのりょうりをてつだいました。","example_meaning":"Tôi đã giúp mẹ nấu ăn.","examples":[{"example":"引っ越しを手伝ってもらえませんか。","example_reading":"ひっこしをてつだってもらえませんか。","example_meaning":"Bạn giúp tôi chuyển nhà được không?"},{"example":"週末は父の店を手伝っている。","example_reading":"しゅうまつはちちのみせをてつだっている。","example_meaning":"Cuối tuần tôi phụ giúp cửa hàng của bố."}]},{"word":"救う","reading":"すくう","meaning":"cứu, cứu vớt","example":"医者は多くの命を救った。","example_reading":"いしゃはおおくのいのちをすくった。","example_meaning":"Vị bác sĩ đã cứu sống nhiều người.","examples":[{"example":"その寄付が、貧しい子どもたちを救うだろう。","example_reading":"そのきふが、まずしいこどもたちをすくうだろう。","example_meaning":"Khoản quyên góp đó sẽ cứu giúp những đứa trẻ nghèo."},{"example":"彼の一言が、落ち込んでいた私の心を救ってくれた。","example_reading":"かれのひとことが、おちこんでいたわたしのこころをすくってくれた。","example_meaning":"Một lời của anh ấy đã cứu vớt tâm hồn đang chán nản của tôi."}]}]},
{"label":"教える／伝える／知らせる","note":"教える: dạy, chỉ cho (kiến thức, cách làm, đường đi). 伝える: truyền đạt lời nhắn, cảm xúc, văn hóa đến người khác. 知らせる: báo tin, thông báo sự việc (kết quả, sự cố) để người ta biết.","items":[{"word":"教える","reading":"おしえる","meaning":"dạy, chỉ bảo","example":"田中先生は私たちに英語を教えています。","example_reading":"たなかせんせいはわたしたちにえいごをおしえています。","example_meaning":"Thầy Tanaka dạy tiếng Anh cho chúng tôi.","examples":[{"example":"駅までの道を教えてください。","example_reading":"えきまでのみちをおしえてください。","example_meaning":"Xin hãy chỉ cho tôi đường đến ga."},{"example":"兄は弟に自転車の乗り方を教えた。","example_reading":"あにはおとうとにじてんしゃののりかたをおしえた。","example_meaning":"Anh trai đã dạy em trai cách đi xe đạp."}]},{"word":"伝える","reading":"つたえる","meaning":"truyền đạt, nhắn lại","example":"山田さんに、会議が三時からだと伝えてください。","example_reading":"やまださんに、かいぎがさんじからだとつたえてください。","example_meaning":"Xin hãy nhắn anh Yamada rằng cuộc họp bắt đầu từ ba giờ.","examples":[{"example":"感謝の気持ちを言葉で伝えたい。","example_reading":"かんしゃのきもちをことばでつたえたい。","example_meaning":"Tôi muốn truyền đạt lòng biết ơn bằng lời nói."},{"example":"昔の文化を次の世代に伝えていく。","example_reading":"むかしのぶんかをつぎのせだいにつたえていく。","example_meaning":"Chúng ta sẽ truyền lại văn hóa xưa cho thế hệ sau."}]},{"word":"知らせる","reading":"しらせる","meaning":"thông báo, báo tin","example":"試験の結果は、メールでお知らせします。","example_reading":"しけんのけっかは、めーるでおしらせします。","example_meaning":"Kết quả thi sẽ được thông báo qua email.","examples":[{"example":"地震が起きたら、すぐ家族に知らせてください。","example_reading":"じしんがおきたら、すぐかぞくにしらせてください。","example_meaning":"Nếu có động đất, hãy báo ngay cho gia đình."},{"example":"彼は友達に結婚を知らせた。","example_reading":"かれはともだちにけっこんをしらせた。","example_meaning":"Anh ấy đã báo tin kết hôn cho bạn bè."}]}]},
{"label":"怒る／叱る","note":"怒る: giận, nổi giận (cảm xúc của bản thân, có thể vì bực tức). 叱る: mắng, quở trách người nhỏ/cấp dưới nhằm sửa dạy; có mục đích giáo dục, đối tượng thường là người ít tuổi/thấp hơn.","items":[{"word":"怒る","reading":"おこる","meaning":"giận, nổi giận","example":"彼は約束を忘れた私に怒っている。","example_reading":"かれはやくそくをわすれたわたしにおこっている。","example_meaning":"Anh ấy đang giận tôi vì tôi quên lời hứa.","examples":[{"example":"そんなに怒らないでください。","example_reading":"そんなにおこらないでください。","example_meaning":"Xin đừng giận như vậy."},{"example":"父は嘘をつかれて、とても怒った。","example_reading":"ちちはうそをつかれて、とてもおこった。","example_meaning":"Bố bị nói dối nên đã rất tức giận."}]},{"word":"叱る","reading":"しかる","meaning":"mắng, quở trách","example":"先生は宿題を忘れた生徒を叱った。","example_reading":"せんせいはしゅくだいをわすれたせいとをしかった。","example_meaning":"Thầy giáo đã mắng học sinh quên bài tập.","examples":[{"example":"母は、道に飛び出した弟を厳しく叱った。","example_reading":"ははは、みちにとびだしたおとうとをきびしくしかった。","example_meaning":"Mẹ đã mắng nghiêm khắc đứa em chạy ra đường."},{"example":"子どもを叱るときは、理由もきちんと説明したい。","example_reading":"こどもをしかるときは、りゆうもきちんとせつめいしたい。","example_meaning":"Khi mắng con, tôi muốn giải thích rõ lý do."}]}]},
{"label":"驚く／びっくり／仰天","note":"驚く: ngạc nhiên (từ chuẩn, dùng chung, cả văn viết). びっくり: giật mình, ngạc nhiên (khẩu ngữ, thân mật, hay dùng với する). 仰天: kinh ngạc tột độ, sửng sốt (mạnh, hơi văn chương/báo chí).","items":[{"word":"驚く","reading":"おどろく","meaning":"ngạc nhiên, kinh ngạc","example":"突然の大きな音に驚いた。","example_reading":"とつぜんのおおきなおとにおどろいた。","example_meaning":"Tôi giật mình vì tiếng động lớn đột ngột.","examples":[{"example":"彼の日本語の上手さには驚くばかりだ。","example_reading":"かれのにほんごのじょうずさにはおどろくばかりだ。","example_meaning":"Tôi chỉ biết kinh ngạc trước tiếng Nhật giỏi của anh ấy."},{"example":"試験の結果を見て、みんな驚いた顔をしていた。","example_reading":"しけんのけっかをみて、みんなおどろいたかおをしていた。","example_meaning":"Nhìn kết quả thi, ai nấy đều có vẻ mặt ngạc nhiên."}]},{"word":"びっくり","reading":"びっくり","meaning":"giật mình, ngạc nhiên (khẩu ngữ)","example":"急に名前を呼ばれて、びっくりしました。","example_reading":"きゅうになまえをよばれて、びっくりしました。","example_meaning":"Bị gọi tên đột ngột nên tôi giật cả mình.","examples":[{"example":"あの店の値段の高さにはびっくりしたよ。","example_reading":"あのみせのねだんのたかさにはびっくりしたよ。","example_meaning":"Mình sốc vì giá ở tiệm đó đắt quá."},{"example":"誕生日に友達がサプライズで来てくれて、びっくりした。","example_reading":"たんじょうびにともだちがさぷらいずできてくれて、びっくりした。","example_meaning":"Bạn bất ngờ đến chúc mừng sinh nhật làm tôi giật mình."}]},{"word":"仰天","reading":"ぎょうてん","meaning":"sửng sốt, kinh hoàng","example":"彼の突然の引退発表に、ファンは仰天した。","example_reading":"かれのとつぜんのいんたいはっぴょうに、ふぁんはぎょうてんした。","example_meaning":"Người hâm mộ sửng sốt trước thông báo giải nghệ đột ngột của anh ấy.","examples":[{"example":"値段を聞いて、思わず仰天してしまった。","example_reading":"ねだんをきいて、おもわずぎょうてんしてしまった。","example_meaning":"Nghe giá, tôi bất giác sững sờ."},{"example":"世間を仰天させるニュースが流れた。","example_reading":"せけんをぎょうてんさせるにゅーすがながれた。","example_meaning":"Một tin tức làm cả xã hội kinh ngạc đã được lan truyền."}]}]},
{"label":"嬉しい／楽しい／面白い","note":"嬉しい: vui mừng vì điều tốt xảy ra với mình (cảm xúc trước sự việc). 楽しい: vui vẻ, thích thú khi đang trải qua hoạt động/thời gian. 面白い: thú vị, hay, buồn cười (đánh giá đối tượng như truyện, phim, người).","items":[{"word":"嬉しい","reading":"うれしい","meaning":"vui mừng","example":"友達に誕生日を祝ってもらって、とても嬉しい。","example_reading":"ともだちにたんじょうびをいわってもらって、とてもうれしい。","example_meaning":"Được bạn chúc mừng sinh nhật, tôi rất vui.","examples":[{"example":"合格の知らせを聞いて、嬉しくて涙が出た。","example_reading":"ごうかくのしらせをきいて、うれしくてなみだがでた。","example_meaning":"Nghe tin đậu, tôi vui đến phát khóc."},{"example":"久しぶりに会えて嬉しいです。","example_reading":"ひさしぶりにあえてうれしいです。","example_meaning":"Lâu lắm mới gặp được bạn, tôi rất vui."}]},{"word":"楽しい","reading":"たのしい","meaning":"vui vẻ, thích thú","example":"昨日の旅行はとても楽しかった。","example_reading":"きのうのりょこうはとてもたのしかった。","example_meaning":"Chuyến đi hôm qua rất vui.","examples":[{"example":"友達と話すのは楽しい。","example_reading":"ともだちとはなすのはたのしい。","example_meaning":"Nói chuyện với bạn bè rất vui."},{"example":"家族みんなで食べる晩ご飯は楽しいね。","example_reading":"かぞくみんなでたべるばんごはんはたのしいね。","example_meaning":"Bữa tối cả nhà cùng ăn thật vui nhỉ."}]},{"word":"面白い","reading":"おもしろい","meaning":"thú vị, hay, buồn cười","example":"この漫画は本当に面白い。","example_reading":"このまんがはほんとうにおもしろい。","example_meaning":"Bộ truyện tranh này thật sự rất hay.","examples":[{"example":"彼の話は面白くて、みんなが笑った。","example_reading":"かれのはなしはおもしろくて、みんながわらった。","example_meaning":"Chuyện của anh ấy buồn cười nên ai cũng cười."},{"example":"面白い本を見つけたので、貸してあげるよ。","example_reading":"おもしろいほんをみつけたので、かしてあげるよ。","example_meaning":"Mình tìm được cuốn sách hay nên cho cậu mượn nhé."}]}]},
{"label":"大きい／巨大／膨大","note":"大きい: to, lớn (kích thước, mức độ nói chung). 巨大: khổng lồ về kích thước vật thể hữu hình, vượt xa thông thường. 膨大: đồ sộ, khổng lồ về số lượng/khối lượng trừu tượng (dữ liệu, thời gian, chi phí), không dùng cho hình dáng.","items":[{"word":"大きい","reading":"おおきい","meaning":"to, lớn","example":"この靴は私には大きいです。","example_reading":"このくつはわたしにはおおきいです。","example_meaning":"Đôi giày này to so với tôi.","examples":[{"example":"庭に大きい木がある。","example_reading":"にわにおおきいきがある。","example_meaning":"Trong vườn có một cái cây to."},{"example":"弟は私より体が大きい。","example_reading":"おとうとはわたしよりからだがおおきい。","example_meaning":"Em trai tôi to con hơn tôi."}]},{"word":"巨大","reading":"きょだい","meaning":"khổng lồ, đồ sộ (kích thước)","example":"海に巨大なクジラが現れた。","example_reading":"うみにきょだいなくじらがあらわれた。","example_meaning":"Một con cá voi khổng lồ xuất hiện ngoài biển.","examples":[{"example":"町の中心に巨大なビルが建っている。","example_reading":"まちのちゅうしんにきょだいなびるがたっている。","example_meaning":"Giữa trung tâm thị trấn có một tòa nhà khổng lồ."},{"example":"巨大な台風が日本に近づいている。","example_reading":"きょだいなたいふうがにほんにちかづいている。","example_meaning":"Một cơn bão cực lớn đang tiến gần Nhật Bản."}]},{"word":"膨大","reading":"ぼうだい","meaning":"đồ sộ, khổng lồ (số lượng)","example":"この研究には膨大なデータが必要だ。","example_reading":"このけんきゅうにはぼうだいなでーたがひつようだ。","example_meaning":"Nghiên cứu này cần lượng dữ liệu khổng lồ.","examples":[{"example":"引っ越しには膨大な時間と費用がかかった。","example_reading":"ひっこしにはぼうだいなじかんとひようがかかった。","example_meaning":"Việc chuyển nhà tốn thời gian và chi phí rất lớn."},{"example":"資料の量が膨大で、全部読むのに一週間かかった。","example_reading":"しりょうのりょうがぼうだいで、ぜんぶよむのにいっしゅうかんかかった。","example_meaning":"Lượng tài liệu quá đồ sộ, đọc hết mất một tuần."}]}]},
{"label":"小さい／細かい／狭い","note":"小さい: nhỏ (kích thước, âm lượng, tuổi). 細かい: chi tiết, nhỏ li ti, tỉ mỉ; cũng là tiền lẻ, người khắt khe. 狭い: hẹp, chật (không gian, diện tích, đường, tầm nhìn).","items":[{"word":"小さい","reading":"ちいさい","meaning":"nhỏ","example":"この服は子どもには小さい。","example_reading":"このふくはこどもにはちいさい。","example_meaning":"Bộ quần áo này nhỏ đối với đứa trẻ.","examples":[{"example":"小さい声で話してください。","example_reading":"ちいさいこえではなしてください。","example_meaning":"Xin hãy nói nhỏ tiếng."},{"example":"小さい犬を飼っています。","example_reading":"ちいさいいぬをかっています。","example_meaning":"Tôi nuôi một chú chó nhỏ."}]},{"word":"細かい","reading":"こまかい","meaning":"chi tiết, nhỏ li ti, tỉ mỉ","example":"細かい字は読みにくい。","example_reading":"こまかいじはよみにくい。","example_meaning":"Chữ nhỏ li ti rất khó đọc.","examples":[{"example":"彼は細かいことまで気にする性格だ。","example_reading":"かれはこまかいことまできにするせいかくだ。","example_meaning":"Anh ấy có tính hay để ý cả những chuyện nhỏ nhặt."},{"example":"一万円札を細かいお金に替えてもらった。","example_reading":"いちまんえんさつをこまかいおかねにかえてもらった。","example_meaning":"Tôi đã nhờ đổi tờ mười nghìn yên thành tiền lẻ."}]},{"word":"狭い","reading":"せまい","meaning":"hẹp, chật","example":"私の部屋は狭いですが、住みやすいです。","example_reading":"わたしのへやはせまいですが、すみやすいです。","example_meaning":"Phòng tôi chật nhưng dễ sống.","examples":[{"example":"この道は狭くて、車が通れない。","example_reading":"このみちはせまくて、くるまがとおれない。","example_meaning":"Con đường này hẹp nên xe hơi không đi qua được."},{"example":"彼は視野が狭くて、他人の意見を聞かない。","example_reading":"かれはしやがせまくて、たにんのいけんをきかない。","example_meaning":"Anh ta tầm nhìn hạn hẹp và không nghe ý kiến người khác."}]}]},
{"label":"美しい／きれい／素敵","note":"美しい: đẹp một cách trang nhã, trang trọng, dùng cho cảnh vật, giọng nói, tâm hồn (văn viết). きれい: đẹp và cũng có nghĩa sạch sẽ, gọn gàng, dùng hằng ngày. 素敵: tuyệt, đáng yêu, hợp gu, thể hiện cảm nhận chủ quan của người nói.","items":[{"word":"美しい","reading":"うつくしい","meaning":"đẹp (trang nhã, trang trọng)","example":"夕日に照らされた海はとても美しい。","example_reading":"ゆうひにてらされたうみはとてもうつくしい。","example_meaning":"Biển được ánh hoàng hôn chiếu rọi thật đẹp.","examples":[{"example":"彼女は美しい声で歌った。","example_reading":"かのじょはうつくしいこえでうたった。","example_meaning":"Cô ấy hát bằng một giọng hát đẹp."},{"example":"美しい日本語を話せるようになりたい。","example_reading":"うつくしいにほんごをはなせるようになりたい。","example_meaning":"Tôi muốn nói được tiếng Nhật đẹp."}]},{"word":"きれい","reading":"きれい","meaning":"đẹp; sạch sẽ","example":"この部屋はいつもきれいですね。","example_reading":"このへやはいつもきれいですね。","example_meaning":"Căn phòng này lúc nào cũng sạch sẽ nhỉ.","examples":[{"example":"手をきれいに洗ってください。","example_reading":"てをきれいにあらってください。","example_meaning":"Hãy rửa tay cho sạch."},{"example":"きれいな花をもらいました。","example_reading":"きれいなはなをもらいました。","example_meaning":"Tôi đã được tặng một bó hoa đẹp."}]},{"word":"素敵","reading":"すてき","meaning":"tuyệt, đáng yêu, hợp gu","example":"そのワンピース、とても素敵ですね。","example_reading":"そのわんぴーす、とてもすてきですね。","example_meaning":"Chiếc váy liền đó đẹp quá nhỉ.","examples":[{"example":"素敵な人と出会って結婚したい。","example_reading":"すてきなひととであってけっこんしたい。","example_meaning":"Tôi muốn gặp được một người tuyệt vời rồi kết hôn."},{"example":"週末は素敵な時間を過ごしました。","example_reading":"しゅうまつはすてきなじかんをすごしました。","example_meaning":"Cuối tuần tôi đã trải qua khoảng thời gian tuyệt vời."}]}]},
{"label":"すごい／素晴らしい／立派","note":"すごい: ghê, kinh khủng, khẩu ngữ, dùng được cho cả điều tốt lẫn xấu (すごい雨). 素晴らしい: tuyệt vời, khen ngợi nghiêm túc, mang nghĩa tích cực. 立派: đàng hoàng, chỉn chu, đáng nể về quy mô hoặc nhân cách.","items":[{"word":"すごい","reading":"すごい","meaning":"ghê, giỏi kinh khủng","example":"今日はすごい雨ですね。","example_reading":"きょうはすごいあめですね。","example_meaning":"Hôm nay mưa dữ dội nhỉ.","examples":[{"example":"日本語が上手ですね。すごい！","example_reading":"にほんごがじょうずですね。すごい！","example_meaning":"Bạn giỏi tiếng Nhật nhỉ. Giỏi quá!"},{"example":"すごく疲れたので、早く寝ます。","example_reading":"すごくつかれたので、はやくねます。","example_meaning":"Vì mệt kinh khủng nên tôi sẽ đi ngủ sớm."}]},{"word":"素晴らしい","reading":"すばらしい","meaning":"tuyệt vời","example":"素晴らしい演奏をありがとうございました。","example_reading":"すばらしいえんそうをありがとうございました。","example_meaning":"Cảm ơn vì màn trình diễn tuyệt vời.","examples":[{"example":"山の上からの景色は素晴らしかった。","example_reading":"やまのうえからのけしきはすばらしかった。","example_meaning":"Phong cảnh nhìn từ trên núi thật tuyệt vời."},{"example":"それは素晴らしい考えだと思います。","example_reading":"それはすばらしいかんがえだとおもいます。","example_meaning":"Tôi nghĩ đó là một ý tưởng tuyệt vời."}]},{"word":"立派","reading":"りっぱ","meaning":"đàng hoàng, đáng nể","example":"彼は立派な医者になった。","example_reading":"かれはりっぱないしゃになった。","example_meaning":"Anh ấy đã trở thành một bác sĩ đáng nể.","examples":[{"example":"立派な家に住んでいる。","example_reading":"りっぱないえにすんでいる。","example_meaning":"Anh ấy sống trong một ngôi nhà đồ sộ, chỉn chu."},{"example":"小さいのに一人で留守番ができて立派だ。","example_reading":"ちいさいのにひとりでるすばんができてりっぱだ。","example_meaning":"Còn bé mà đã ở nhà một mình được, thật đáng khen."}]}]},
{"label":"難しい／困難／大変","note":"難しい: khó (về độ phức tạp của vấn đề, kỹ năng), dùng hằng ngày. 困難: khó khăn, trở ngại, văn viết trang trọng, thường đi với 状況, 実行. 大変: vất vả, mệt nhọc, hoặc nghiêm trọng, chuyện lớn; không nói về độ khó của bài tập.","items":[{"word":"難しい","reading":"むずかしい","meaning":"khó","example":"この問題は難しくて、答えがわかりません。","example_reading":"このもんだいはむずかしくて、こたえがわかりません。","example_meaning":"Bài này khó quá, tôi không biết đáp án.","examples":[{"example":"漢字を覚えるのは難しい。","example_reading":"かんじをおぼえるのはむずかしい。","example_meaning":"Học thuộc chữ Hán thật khó."},{"example":"彼の気持ちを理解するのは難しい。","example_reading":"かれのきもちをりかいするのはむずかしい。","example_meaning":"Hiểu được cảm xúc của anh ấy thật khó."}]},{"word":"困難","reading":"こんなん","meaning":"khó khăn, trở ngại","example":"資金不足で計画の実行が困難になった。","example_reading":"しきんぶそくでけいかくのじっこうがこんなんになった。","example_meaning":"Do thiếu vốn nên việc thực hiện kế hoạch trở nên khó khăn.","examples":[{"example":"彼は困難な状況でもあきらめなかった。","example_reading":"かれはこんなんなじょうきょうでもあきらめなかった。","example_meaning":"Anh ấy không bỏ cuộc dù trong hoàn cảnh khó khăn."},{"example":"雪のため、車で行くのは困難だ。","example_reading":"ゆきのため、くるまでいくのはこんなんだ。","example_meaning":"Vì tuyết nên đi bằng ô tô rất khó khăn."}]},{"word":"大変","reading":"たいへん","meaning":"vất vả; nghiêm trọng","example":"子供が三人いて、毎日大変です。","example_reading":"こどもがさんにんいて、まいにちたいへんです。","example_meaning":"Có ba đứa con nên ngày nào cũng vất vả.","examples":[{"example":"大変だ！財布がない！","example_reading":"たいへんだ！さいふがない！","example_meaning":"Nguy rồi! Tôi mất ví rồi!"},{"example":"昨日は大変な一日でした。","example_reading":"きのうはたいへんないちにちでした。","example_meaning":"Hôm qua là một ngày vất vả."}]}]},
{"label":"簡単／単純／容易","note":"簡単: dễ, đơn giản, không tốn công, dùng hằng ngày. 単純: đơn giản về cấu trúc, không phức tạp; về người có thể mang nghĩa đơn giản, cả tin. 容易: dễ dàng, văn viết trang trọng, hay đi với phủ định (容易ではない).","items":[{"word":"簡単","reading":"かんたん","meaning":"dễ, đơn giản","example":"この料理は簡単に作れます。","example_reading":"このりょうりはかんたんにつくれます。","example_meaning":"Món này có thể nấu dễ dàng.","examples":[{"example":"簡単な質問に答えてください。","example_reading":"かんたんなしつもんにこたえてください。","example_meaning":"Hãy trả lời những câu hỏi đơn giản."},{"example":"日本語の簡単な挨拶ができます。","example_reading":"にほんごのかんたんなあいさつができます。","example_meaning":"Tôi chào hỏi đơn giản được bằng tiếng Nhật."}]},{"word":"単純","reading":"たんじゅん","meaning":"đơn giản (cấu trúc); đơn thuần","example":"この機械の仕組みは単純だ。","example_reading":"このきかいのしくみはたんじゅんだ。","example_meaning":"Cơ cấu của chiếc máy này rất đơn giản.","examples":[{"example":"彼は単純だから、すぐ人を信じてしまう。","example_reading":"かれはたんじゅんだから、すぐひとをしんじてしまう。","example_meaning":"Anh ấy đơn giản nên hay dễ tin người."},{"example":"単純な作業を毎日繰り返している。","example_reading":"たんじゅんなさぎょうをまいにちくりかえしている。","example_meaning":"Ngày nào tôi cũng lặp lại công việc đơn điệu."}]},{"word":"容易","reading":"ようい","meaning":"dễ dàng (trang trọng)","example":"彼女に勝つのは容易ではない。","example_reading":"かのじょにかつのはよういではない。","example_meaning":"Thắng được cô ấy không dễ.","examples":[{"example":"新しい環境に慣れるのは容易なことではない。","example_reading":"あたらしいかんきょうになれるのはよういなことではない。","example_meaning":"Làm quen với môi trường mới không phải chuyện dễ."},{"example":"容易に想像できる結果だ。","example_reading":"よういにそうぞうできるけっかだ。","example_meaning":"Đây là kết quả có thể dễ dàng hình dung."}]}]},
{"label":"珍しい／貴重／希少","note":"珍しい: hiếm gặp, lạ, ít xảy ra (sự việc, vật lạ). 貴重: quý giá, đáng trân trọng (thời gian, kinh nghiệm, tư liệu). 希少: số lượng ít ỏi, hiếm (động vật, kim loại), nhấn mạnh sự khan hiếm.","items":[{"word":"珍しい","reading":"めずらしい","meaning":"hiếm gặp, lạ","example":"この辺で雪が降るのは珍しい。","example_reading":"このへんでゆきがふるのはめずらしい。","example_meaning":"Vùng này mà có tuyết rơi là hiếm.","examples":[{"example":"珍しい切手を集めている。","example_reading":"めずらしいきってをあつめている。","example_meaning":"Tôi đang sưu tầm những con tem lạ."},{"example":"珍しいですね、あなたが遅刻するなんて。","example_reading":"めずらしいですね、あなたがちこくするなんて。","example_meaning":"Hiếm thấy nhỉ, bạn mà lại đến muộn."}]},{"word":"貴重","reading":"きちょう","meaning":"quý giá","example":"貴重なお時間をいただき、ありがとうございます。","example_reading":"きちょうなおじかんをいただき、ありがとうございます。","example_meaning":"Cảm ơn anh chị đã dành thời gian quý báu.","examples":[{"example":"博物館には貴重な資料がたくさんある。","example_reading":"はくぶつかんにはきちょうなしりょうがたくさんある。","example_meaning":"Bảo tàng có nhiều tư liệu quý giá."},{"example":"留学は貴重な経験になった。","example_reading":"りゅうがくはきちょうなけいけんになった。","example_meaning":"Du học đã trở thành một trải nghiệm quý giá."}]},{"word":"希少","reading":"きしょう","meaning":"hiếm (số lượng ít)","example":"このトキは世界でも希少な鳥だ。","example_reading":"このときはせかいでもきしょうなとりだ。","example_meaning":"Loài cò quăm này là loài chim hiếm cả trên thế giới.","examples":[{"example":"希少な金属が携帯電話に使われている。","example_reading":"きしょうなきんぞくがけいたいでんわにつかわれている。","example_meaning":"Kim loại hiếm được dùng trong điện thoại di động."},{"example":"数が少なく、希少価値が高い。","example_reading":"かずがすくなく、きしょうかちがたかい。","example_meaning":"Số lượng ít nên giá trị hiếm có rất cao."}]}]},
{"label":"丁寧／慎重／念入り","note":"丁寧: lịch sự, cẩn thận, tỉ mỉ trong cách đối xử, cách nói, cách làm. 慎重: thận trọng, cân nhắc kỹ để tránh sai lầm hay rủi ro. 念入り: kỹ lưỡng, tốn nhiều công sức và thời gian, làm đến nơi đến chốn.","items":[{"word":"丁寧","reading":"ていねい","meaning":"lịch sự, cẩn thận","example":"先生は丁寧に説明してくれた。","example_reading":"せんせいはていねいにせつめいしてくれた。","example_meaning":"Thầy giáo đã giải thích cho tôi một cách kỹ lưỡng.","examples":[{"example":"丁寧な言葉で話しましょう。","example_reading":"ていねいなことばではなしましょう。","example_meaning":"Hãy nói bằng lời lẽ lịch sự."},{"example":"本を丁寧に扱ってください。","example_reading":"ほんをていねいにあつかってください。","example_meaning":"Hãy cẩn thận khi cầm sách."}]},{"word":"慎重","reading":"しんちょう","meaning":"thận trọng","example":"慎重に運転してください。","example_reading":"しんちょうにうんてんしてください。","example_meaning":"Hãy lái xe thận trọng.","examples":[{"example":"彼は何でも慎重に考えてから決める。","example_reading":"かれはなんでもしんちょうにかんがえてからきめる。","example_meaning":"Anh ấy việc gì cũng suy nghĩ thận trọng rồi mới quyết định."},{"example":"大事な契約なので、慎重な判断が必要だ。","example_reading":"だいじなけいやくなので、しんちょうなはんだんがひつようだ。","example_meaning":"Vì là hợp đồng quan trọng nên cần phán đoán thận trọng."}]},{"word":"念入り","reading":"ねんいり","meaning":"kỹ lưỡng, chu đáo","example":"出かける前に念入りに化粧をした。","example_reading":"でかけるまえにねんいりにけしょうをした。","example_meaning":"Trước khi ra ngoài tôi đã trang điểm rất kỹ.","examples":[{"example":"部屋を念入りに掃除した。","example_reading":"へやをねんいりにそうじした。","example_meaning":"Tôi đã dọn phòng thật kỹ lưỡng."},{"example":"念入りに調べたが、間違いは見つからなかった。","example_reading":"ねんいりにしらべたが、まちがいはみつからなかった。","example_meaning":"Tôi đã kiểm tra rất kỹ nhưng không tìm thấy lỗi nào."}]}]},
{"label":"勉強／学習","note":"勉強: học bài, học tập nói chung; dùng hằng ngày, còn có nghĩa học được bài học, hoặc giảm giá (勉強になる). 学習: sự học như một quá trình, mang tính khoa học, giáo dục, hay dùng trong văn viết, thuật ngữ (学習指導, 機械学習).","items":[{"word":"勉強","reading":"べんきょう","meaning":"học tập, học bài","example":"毎晩二時間日本語を勉強しています。","example_reading":"まいばんにじかんにほんごをべんきょうしています。","example_meaning":"Mỗi tối tôi học tiếng Nhật hai tiếng.","examples":[{"example":"勉強になりました。ありがとうございます。","example_reading":"べんきょうになりました。ありがとうございます。","example_meaning":"Tôi đã học hỏi được nhiều. Cảm ơn bạn."},{"example":"試験の前は友達と図書館で勉強する。","example_reading":"しけんのまえはともだちととしょかんでべんきょうする。","example_meaning":"Trước kỳ thi tôi học cùng bạn ở thư viện."}]},{"word":"学習","reading":"がくしゅう","meaning":"học (quá trình, mang tính giáo dục)","example":"子供の学習意欲を高める方法を考えている。","example_reading":"こどものがくしゅういよくをたかめるほうほうをかんがえている。","example_meaning":"Tôi đang nghĩ cách nâng cao động lực học tập của trẻ.","examples":[{"example":"この学習アプリは毎日使えます。","example_reading":"このがくしゅうあぷりはまいにちつかえます。","example_meaning":"Ứng dụng học tập này dùng được hằng ngày."},{"example":"失敗から学習することも大切だ。","example_reading":"しっぱいからがくしゅうすることもたいせつだ。","example_meaning":"Rút kinh nghiệm học hỏi từ thất bại cũng rất quan trọng."}]}]},
{"label":"仕事／職業","note":"仕事: công việc, việc làm cụ thể đang làm hoặc nơi làm việc (仕事が忙しい, 仕事に行く). 職業: nghề nghiệp, loại nghề (bác sĩ, giáo viên), dùng khi nói về nghề hoặc điền vào giấy tờ.","items":[{"word":"仕事","reading":"しごと","meaning":"công việc","example":"今日は仕事が忙しくて、昼ご飯を食べられなかった。","example_reading":"きょうはしごとがいそがしくて、ひるごはんをたべられなかった。","example_meaning":"Hôm nay công việc bận quá nên tôi không ăn trưa được.","examples":[{"example":"父は銀行で仕事をしている。","example_reading":"ちちはぎんこうでしごとをしている。","example_meaning":"Bố tôi làm việc ở ngân hàng."},{"example":"仕事が終わったら、電話します。","example_reading":"しごとがおわったら、でんわします。","example_meaning":"Xong việc tôi sẽ gọi điện."}]},{"word":"職業","reading":"しょくぎょう","meaning":"nghề nghiệp","example":"あなたの職業は何ですか。","example_reading":"あなたのしょくぎょうはなんですか。","example_meaning":"Nghề nghiệp của bạn là gì?","examples":[{"example":"将来、人の役に立つ職業に就きたい。","example_reading":"しょうらい、ひとのやくにたつしょくぎょうにつきたい。","example_meaning":"Sau này tôi muốn làm một nghề giúp ích cho mọi người."},{"example":"申込書に名前と職業を書いてください。","example_reading":"もうしこみしょになまえとしょくぎょうをかいてください。","example_meaning":"Hãy viết tên và nghề nghiệp vào đơn đăng ký."}]}]},
{"label":"会社／企業","note":"会社: công ty cụ thể mình làm hoặc đang nói tới, dùng hằng ngày (会社に行く). 企業: doanh nghiệp nói chung như một đơn vị kinh tế, dùng khi bàn xã hội, kinh tế (大企業, 中小企業).","items":[{"word":"会社","reading":"かいしゃ","meaning":"công ty","example":"私は東京の会社で働いています。","example_reading":"わたしはとうきょうのかいしゃではたらいています。","example_meaning":"Tôi làm việc ở một công ty tại Tokyo.","examples":[{"example":"会社まで電車で三十分かかります。","example_reading":"かいしゃまででんしゃでさんじゅっぷんかかります。","example_meaning":"Đi tàu đến công ty mất ba mươi phút."},{"example":"明日は会社を休みます。","example_reading":"あしたはかいしゃをやすみます。","example_meaning":"Ngày mai tôi nghỉ làm."}]},{"word":"企業","reading":"きぎょう","meaning":"doanh nghiệp","example":"大企業に就職するのは簡単ではない。","example_reading":"だいきぎょうにしゅうしょくするのはかんたんではない。","example_meaning":"Xin vào tập đoàn lớn không hề đơn giản.","examples":[{"example":"環境問題に取り組む企業が増えている。","example_reading":"かんきょうもんだいにとりくむきぎょうがふえている。","example_meaning":"Số doanh nghiệp giải quyết vấn đề môi trường đang tăng."},{"example":"この地域には中小企業が多い。","example_reading":"このちいきにはちゅうしょうきぎょうがおおい。","example_meaning":"Khu vực này có nhiều doanh nghiệp vừa và nhỏ."}]}]},
{"label":"家／住宅／建物","note":"家: nhà của mình, nơi ở, gia đình; vừa là tòa nhà vừa là mái ấm (家に帰る). 住宅: nhà ở dùng để cư trú, hay dùng trong ngữ cảnh khu dân cư, bất động sản (住宅街, 住宅ローン). 建物: tòa nhà, công trình nói chung, không nhất thiết để ở.","items":[{"word":"家","reading":"いえ","meaning":"nhà (nơi ở của mình)","example":"私の家は駅から近いです。","example_reading":"わたしのいえはえきからちかいです。","example_meaning":"Nhà tôi gần ga.","examples":[{"example":"家に帰ってゆっくり休みたい。","example_reading":"いえにかえってゆっくりやすみたい。","example_meaning":"Tôi muốn về nhà nghỉ ngơi thong thả."},{"example":"彼は郊外に新しい家を建てた。","example_reading":"かれはこうがいにあたらしいいえをたてた。","example_meaning":"Anh ấy đã xây một căn nhà mới ở ngoại ô."}]},{"word":"住宅","reading":"じゅうたく","meaning":"nhà ở, nhà dân","example":"この辺りは静かな住宅街だ。","example_reading":"このあたりはしずかなじゅうたくがいだ。","example_meaning":"Khu này là khu dân cư yên tĩnh.","examples":[{"example":"住宅ローンを三十年かけて返す。","example_reading":"じゅうたくろーんをさんじゅうねんかけてかえす。","example_meaning":"Tôi trả khoản vay mua nhà trong ba mươi năm."},{"example":"駅の近くに新しい住宅が建った。","example_reading":"えきのちかくにあたらしいじゅうたくがたった。","example_meaning":"Nhà ở mới đã được xây gần nhà ga."}]},{"word":"建物","reading":"たてもの","meaning":"tòa nhà, công trình","example":"あの高い建物は市役所です。","example_reading":"あのたかいたてものはしやくしょです。","example_meaning":"Tòa nhà cao kia là ủy ban thành phố.","examples":[{"example":"古い建物なので、地震が心配だ。","example_reading":"ふるいたてものなので、じしんがしんぱいだ。","example_meaning":"Vì là tòa nhà cũ nên tôi lo về động đất."},{"example":"建物の中ではたばこを吸わないでください。","example_reading":"たてもののなかではたばこをすわないでください。","example_meaning":"Xin đừng hút thuốc trong tòa nhà."}]}]},
{"label":"ついに／とうとう／やっと／結局","note":"ついに: cuối cùng thì (sau thời gian dài), dùng cả kết quả tốt và xấu, hơi trang trọng. とうとう: rốt cuộc cũng, thường kèm cảm giác tiếc nuối hoặc kết cục không mong muốn. やっと: mãi mới được, nhấn mạnh sự vất vả, kết quả tốt. 結局: rốt cuộc, tóm lại sau nhiều thay đổi, mang tính tổng kết, không nhất thiết có nỗ lực.","items":[{"word":"ついに","reading":"ついに","meaning":"cuối cùng thì","example":"十年の努力が実って、ついに夢が叶った。","example_reading":"じゅうねんのどりょくがみのって、ついにゆめがかなった。","example_meaning":"Nỗ lực mười năm đơm hoa kết trái, cuối cùng ước mơ đã thành hiện thực.","examples":[{"example":"ついに新しい店がオープンした。","example_reading":"ついにあたらしいみせがおーぷんした。","example_meaning":"Cuối cùng cửa hàng mới cũng đã khai trương."},{"example":"長い工事が、ついに終わった。","example_reading":"ながいこうじが、ついにおわった。","example_meaning":"Công trình kéo dài cuối cùng cũng đã xong."}]},{"word":"とうとう","reading":"とうとう","meaning":"rốt cuộc (thường tiếc nuối)","example":"待っていたが、彼はとうとう来なかった。","example_reading":"まっていたが、かれはとうとうこなかった。","example_meaning":"Tôi đã chờ nhưng rốt cuộc anh ấy không đến.","examples":[{"example":"雨がとうとう雪に変わった。","example_reading":"あめがとうとうゆきにかわった。","example_meaning":"Mưa rốt cuộc đã chuyển thành tuyết."},{"example":"とうとうお金がなくなってしまった。","example_reading":"とうとうおかねがなくなってしまった。","example_meaning":"Rốt cuộc tiền cũng hết sạch mất rồi."}]},{"word":"やっと","reading":"やっと","meaning":"mãi mới, cuối cùng cũng","example":"一時間待って、やっとバスが来た。","example_reading":"いちじかんまって、やっとばすがきた。","example_meaning":"Chờ một tiếng, mãi mới có xe buýt đến.","examples":[{"example":"宿題がやっと終わった。","example_reading":"しゅくだいがやっとおわった。","example_meaning":"Cuối cùng cũng làm xong bài tập."},{"example":"やっと日本語で電話ができるようになった。","example_reading":"やっとにほんごででんわができるようになった。","example_meaning":"Mãi mới gọi điện được bằng tiếng Nhật."}]},{"word":"結局","reading":"けっきょく","meaning":"rốt cuộc, tóm lại","example":"いろいろ考えたが、結局行かないことにした。","example_reading":"いろいろかんがえたが、けっきょくいかないことにした。","example_meaning":"Đã nghĩ nhiều nhưng rốt cuộc tôi quyết định không đi.","examples":[{"example":"結局、彼は何も買わなかった。","example_reading":"けっきょく、かれはなにもかわなかった。","example_meaning":"Rốt cuộc anh ấy chẳng mua gì cả."},{"example":"結局、最後は自分で決めるしかない。","example_reading":"けっきょく、さいごはじぶんできめるしかない。","example_meaning":"Rốt cuộc, cuối cùng chỉ còn cách tự mình quyết định."}]}]},
{"label":"だんだん／次第に／徐々に","note":"だんだん: dần dần, khẩu ngữ, dùng phổ biến nhất cho mọi thay đổi. 次第に: dần dần theo diễn tiến tự nhiên, văn viết hơn, thường là sự thay đổi tự nhiên (trời tối, mưa mạnh). 徐々に: từng chút một, chậm rãi, nhấn mạnh từng bước nhỏ, hay dùng với thay đổi có kiểm soát hoặc hồi phục.","items":[{"word":"だんだん","reading":"だんだん","meaning":"dần dần","example":"だんだん寒くなってきましたね。","example_reading":"だんだんさむくなってきましたね。","example_meaning":"Trời dần dần lạnh rồi nhỉ.","examples":[{"example":"日本語がだんだん分かるようになった。","example_reading":"にほんごがだんだんわかるようになった。","example_meaning":"Tôi dần dần hiểu được tiếng Nhật."},{"example":"だんだん眠くなってきた。","example_reading":"だんだんねむくなってきた。","example_meaning":"Tôi dần thấy buồn ngủ."}]},{"word":"次第に","reading":"しだいに","meaning":"dần dần (diễn tiến tự nhiên)","example":"雨は次第に強くなった。","example_reading":"あめはしだいにつよくなった。","example_meaning":"Mưa dần dần mạnh lên.","examples":[{"example":"次第に空が暗くなってきた。","example_reading":"しだいにそらがくらくなってきた。","example_meaning":"Bầu trời dần dần tối đi."},{"example":"彼女の態度は次第に変わっていった。","example_reading":"かのじょのたいどはしだいにかわっていった。","example_meaning":"Thái độ của cô ấy dần dần thay đổi."}]},{"word":"徐々に","reading":"じょじょに","meaning":"từ từ, từng chút một","example":"薬の効果が徐々に現れてきた。","example_reading":"くすりのこうかがじょじょにあらわれてきた。","example_meaning":"Tác dụng của thuốc dần dần xuất hiện.","examples":[{"example":"徐々に運動の量を増やしていきましょう。","example_reading":"じょじょにうんどうのりょうをふやしていきましょう。","example_meaning":"Hãy tăng dần lượng vận động từng chút một."},{"example":"景気は徐々に回復している。","example_reading":"けいきはじょじょにかいふくしている。","example_meaning":"Nền kinh tế đang phục hồi từ từ."}]}]},
{"label":"すぐ／直ちに／早速","note":"すぐ: ngay, liền, dùng hằng ngày; còn chỉ khoảng cách rất gần (すぐそこ). 直ちに: ngay lập tức, trang trọng, dùng trong chỉ thị, thông báo khẩn. 早速: nhanh chóng bắt tay vào làm ngay sau khi nhận được hoặc có cơ hội, mang tính tích cực, chủ động.","items":[{"word":"すぐ","reading":"すぐ","meaning":"ngay, liền; ngay gần","example":"すぐ行きますから、ちょっと待ってください。","example_reading":"すぐいきますから、ちょっとまってください。","example_meaning":"Tôi đến ngay, xin chờ một chút.","examples":[{"example":"駅はすぐそこです。","example_reading":"えきはすぐそこです。","example_meaning":"Nhà ga ở ngay đằng kia."},{"example":"家に着いたらすぐ電話します。","example_reading":"いえについたらすぐでんわします。","example_meaning":"Về đến nhà tôi sẽ gọi điện ngay."}]},{"word":"直ちに","reading":"ただちに","meaning":"ngay lập tức (trang trọng)","example":"火事の場合は、直ちに避難してください。","example_reading":"かじのばあいは、ただちにひなんしてください。","example_meaning":"Khi có hỏa hoạn, hãy sơ tán ngay lập tức.","examples":[{"example":"事故の連絡を受け、直ちに現場へ向かった。","example_reading":"じこのれんらくをうけ、ただちにげんばへむかった。","example_meaning":"Nhận được tin về vụ tai nạn, tôi đã lập tức tới hiện trường."},{"example":"異常があれば直ちに報告すること。","example_reading":"いじょうがあればただちにほうこくすること。","example_meaning":"Nếu có bất thường phải báo cáo ngay lập tức."}]},{"word":"早速","reading":"さっそく","meaning":"liền, ngay (bắt tay làm)","example":"新しいカメラを買って、早速使ってみた。","example_reading":"あたらしいかめらをかって、さっそくつかってみた。","example_meaning":"Mua máy ảnh mới xong, tôi dùng thử ngay.","examples":[{"example":"早速ですが、本題に入りましょう。","example_reading":"さっそくですが、ほんだいにはいりましょう。","example_meaning":"Xin đi thẳng vào vấn đề chính luôn."},{"example":"先生にもらった本を、早速読み始めた。","example_reading":"せんせいにもらったほんを、さっそくよみはじめた。","example_meaning":"Cuốn sách được thầy cho, tôi bắt đầu đọc ngay."}]}]},
{"label":"たぶん／おそらく／きっと","note":"たぶん: có lẽ, khẩu ngữ, độ chắc chắn khoảng 50-70%. おそらく: nhiều khả năng, trang trọng hơn, dựa trên suy đoán có căn cứ, hay đi với だろう. きっと: chắc chắn, tin tưởng mạnh theo cảm nhận của người nói, độ chắc khoảng 90%, dùng cả khi hy vọng hoặc hứa hẹn.","items":[{"word":"たぶん","reading":"たぶん","meaning":"có lẽ","example":"明日はたぶん雨が降るでしょう。","example_reading":"あしたはたぶんあめがふるでしょう。","example_meaning":"Ngày mai có lẽ trời sẽ mưa.","examples":[{"example":"たぶん山田さんは来ないと思う。","example_reading":"たぶんやまださんはこないとおもう。","example_meaning":"Tôi nghĩ có lẽ anh Yamada sẽ không đến."},{"example":"たぶん今夜は遅くなります。","example_reading":"たぶんこんやはおそくなります。","example_meaning":"Có lẽ tối nay tôi sẽ về muộn."}]},{"word":"おそらく","reading":"おそらく","meaning":"nhiều khả năng, e rằng","example":"今回の試験は、おそらく去年より難しいだろう。","example_reading":"こんかいのしけんは、おそらくきょねんよりむずかしいだろう。","example_meaning":"Kỳ thi lần này nhiều khả năng sẽ khó hơn năm ngoái.","examples":[{"example":"おそらく彼はこの事実を知らなかったのだろう。","example_reading":"おそらくかれはこのじじつをしらなかったのだろう。","example_meaning":"Nhiều khả năng anh ấy đã không biết sự thật này."},{"example":"計画の実現は、おそらく難しいでしょう。","example_reading":"けいかくのじつげんは、おそらくむずかしいでしょう。","example_meaning":"Việc thực hiện kế hoạch e rằng sẽ khó."}]},{"word":"きっと","reading":"きっと","meaning":"chắc chắn là","example":"練習すれば、きっと上手になるよ。","example_reading":"れんしゅうすれば、きっとじょうずになるよ。","example_meaning":"Nếu luyện tập, chắc chắn bạn sẽ giỏi lên.","examples":[{"example":"明日はきっと晴れるよ。","example_reading":"あしたはきっとはれるよ。","example_meaning":"Ngày mai chắc chắn trời sẽ nắng."},{"example":"彼ならきっと来てくれる。","example_reading":"かれならきっときてくれる。","example_meaning":"Nếu là anh ấy thì chắc chắn sẽ đến."}]}]},
{"label":"しかし／ところが／けれども","note":"しかし: nhưng, tuy nhiên, từ nối đầu câu, đối lập thông thường, dùng cả văn viết lẫn nói. ところが: thế nhưng, vế sau là kết quả bất ngờ, trái với dự đoán ở vế trước; không dùng cho ý chí, mệnh lệnh. けれども: nhưng, thường nối hai vế trong cùng một câu (…けれども、…), mềm hơn, khẩu ngữ.","items":[{"word":"しかし","reading":"しかし","meaning":"nhưng, tuy nhiên","example":"彼は努力した。しかし、合格できなかった。","example_reading":"かれはどりょくした。しかし、ごうかくできなかった。","example_meaning":"Anh ấy đã nỗ lực. Tuy nhiên, anh ấy đã không đỗ.","examples":[{"example":"この店は有名だ。しかし、味はあまり良くない。","example_reading":"このみせはゆうめいだ。しかし、あじはあまりよくない。","example_meaning":"Quán này nổi tiếng. Nhưng hương vị không ngon lắm."},{"example":"日本語は難しい。しかし、とても面白い。","example_reading":"にほんごはむずかしい。しかし、とてもおもしろい。","example_meaning":"Tiếng Nhật khó. Nhưng rất thú vị."}]},{"word":"ところが","reading":"ところが","meaning":"thế nhưng (bất ngờ)","example":"天気予報は晴れだった。ところが、午後から雨が降り出した。","example_reading":"てんきよほうははれだった。ところが、ごごからあめがふりだした。","example_meaning":"Dự báo thời tiết là nắng. Thế nhưng từ chiều trời bắt đầu mưa.","examples":[{"example":"簡単だと思って始めた。ところが、やってみると意外に難しかった。","example_reading":"かんたんだとおもってはじめた。ところが、やってみるといがいにむずかしかった。","example_meaning":"Tôi tưởng dễ nên bắt đầu làm. Thế nhưng làm thử mới thấy khó bất ngờ."},{"example":"駅に急いだ。ところが、電車はもう出た後だった。","example_reading":"えきにいそいだ。ところが、でんしゃはもうでたあとだった。","example_meaning":"Tôi vội chạy tới ga. Thế nhưng tàu đã rời đi rồi."}]},{"word":"けれども","reading":"けれども","meaning":"nhưng, tuy (nối trong câu)","example":"行きたいけれども、時間がありません。","example_reading":"いきたいけれども、じかんがありません。","example_meaning":"Tôi muốn đi nhưng không có thời gian.","examples":[{"example":"値段は高いけれども、品質はとてもいい。","example_reading":"ねだんはたかいけれども、ひんしつはとてもいい。","example_meaning":"Giá thì đắt nhưng chất lượng rất tốt."},{"example":"彼は若いけれども、仕事がよくできる。","example_reading":"かれはわかいけれども、しごとがよくできる。","example_meaning":"Anh ấy tuy trẻ nhưng làm việc rất giỏi."}]}]},
{"label":"約束／予約","note":"約束(やくそく): LỜI HỨA, cuộc hẹn giữa người với người. 予約(よやく): ĐẶT TRƯỚC chỗ, vé, phòng (nhà hàng, khách sạn, bệnh viện).","items":[{"word":"約束","reading":"やくそく","meaning":"lời hứa, cuộc hẹn","example":"友達と七時に会う約束をしました。","example_reading":"ともだちとしちじにあうやくそくをしました。","example_meaning":"Tôi đã hẹn gặp bạn lúc 7 giờ.","examples":[{"example":"約束は必ず守ります。","example_reading":"やくそくはかならずまもります。","example_meaning":"Tôi nhất định giữ lời hứa."},{"example":"彼との約束を忘れてしまいました。","example_reading":"かれとのやくそくをわすれてしまいました。","example_meaning":"Tôi lỡ quên mất cuộc hẹn với anh ấy."}]},{"word":"予約","reading":"よやく","meaning":"đặt trước","example":"レストランを予約しました。","example_reading":"れすとらんをよやくしました。","example_meaning":"Tôi đã đặt bàn ở nhà hàng.","examples":[{"example":"ホテルの部屋を二泊予約した。","example_reading":"ほてるのへやをにはくよやくした。","example_meaning":"Tôi đã đặt phòng khách sạn hai đêm."},{"example":"人気の店なので、予約しないと入れません。","example_reading":"にんきのみせなので、よやくしないとはいれません。","example_meaning":"Vì là quán nổi tiếng nên không đặt trước thì không vào được."}]}]},
{"label":"将来／未来","note":"将来(しょうらい): TƯƠNG LAI gần, gắn với cuộc đời, nghề nghiệp, dự định của một người. 未来(みらい): TƯƠNG LAI xa, mang tính rộng và khái quát (thế giới, nhân loại, thời đại).","items":[{"word":"将来","reading":"しょうらい","meaning":"tương lai (của một người)","example":"将来は医者になりたいです。","example_reading":"しょうらいはいしゃになりたいです。","example_meaning":"Tương lai tôi muốn làm bác sĩ.","examples":[{"example":"将来のために貯金しています。","example_reading":"しょうらいのためにちょきんしています。","example_meaning":"Tôi đang tiết kiệm tiền vì tương lai."},{"example":"この子は将来が楽しみだ。","example_reading":"このこはしょうらいがたのしみだ。","example_meaning":"Đứa bé này tương lai thật đáng mong đợi."}]},{"word":"未来","reading":"みらい","meaning":"tương lai (xa, khái quát)","example":"未来の社会はどうなるでしょうか。","example_reading":"みらいのしゃかいはどうなるでしょうか。","example_meaning":"Xã hội tương lai sẽ ra sao nhỉ?","examples":[{"example":"未来の車は空を飛ぶかもしれない。","example_reading":"みらいのくるまはそらをとぶかもしれない。","example_meaning":"Xe hơi của tương lai có thể sẽ bay trên trời."},{"example":"子どもたちの未来を守りたい。","example_reading":"こどもたちのみらいをまもりたい。","example_meaning":"Tôi muốn bảo vệ tương lai của trẻ em."}]}]},
{"label":"昔／以前／かつて","note":"昔(むかし): NGÀY XƯA, thời rất xa, hay dùng khi kể chuyện cổ, hoài niệm. 以前(いぜん): TRƯỚC ĐÂY, một thời điểm trước mốc nào đó (gần hơn 昔). かつて: TỪNG, ngày trước (văn viết/trang trọng, nay đã khác).","items":[{"word":"昔","reading":"むかし","meaning":"ngày xưa","example":"昔々、あるところにおじいさんがいました。","example_reading":"むかしむかし、あるところにおじいさんがいました。","example_meaning":"Ngày xửa ngày xưa, ở một nơi nọ có một ông lão.","examples":[{"example":"昔はこの辺りは田んぼでした。","example_reading":"むかしはこのあたりはたんぼでした。","example_meaning":"Ngày xưa vùng này là ruộng lúa."},{"example":"昔の友達に久しぶりに会った。","example_reading":"むかしのともだちにひさしぶりにあった。","example_meaning":"Lâu lắm rồi tôi mới gặp lại người bạn cũ."}]},{"word":"以前","reading":"いぜん","meaning":"trước đây","example":"以前、この店に来たことがあります。","example_reading":"いぜん、このみせにきたことがあります。","example_meaning":"Trước đây tôi từng đến quán này.","examples":[{"example":"以前より日本語が上手になった。","example_reading":"いぜんよりにほんごがじょうずになった。","example_meaning":"Tiếng Nhật của tôi đã giỏi hơn trước."},{"example":"以前の住所を教えてください。","example_reading":"いぜんのじゅうしょをおしえてください。","example_meaning":"Xin hãy cho tôi biết địa chỉ trước đây."}]},{"word":"かつて","reading":"かつて","meaning":"từng, ngày trước (trang trọng)","example":"かつてここは大きな港町だった。","example_reading":"かつてここはおおきなみなとまちだった。","example_meaning":"Ngày trước nơi đây từng là một thị trấn cảng lớn.","examples":[{"example":"彼はかつて世界一の選手だった。","example_reading":"かれはかつてせかいいちのせんしゅだった。","example_meaning":"Anh ấy từng là tuyển thủ số một thế giới."},{"example":"かつての栄光は、もうありません。","example_reading":"かつてのえいこうは、もうありません。","example_meaning":"Vinh quang năm xưa nay không còn nữa."}]}]},
{"label":"習う／学ぶ","note":"習う(ならう): HỌC kỹ năng từ thầy/người hướng dẫn (đàn, bơi, nấu ăn). 学ぶ(まなぶ): HỌC HỎI, tiếp thu kiến thức và bài học một cách rộng hơn (từ sách vở, kinh nghiệm, thất bại).","items":[{"word":"習う","reading":"ならう","meaning":"học (theo người dạy)","example":"先生にピアノを習っています。","example_reading":"せんせいにぴあのをならっています。","example_meaning":"Tôi đang học đàn piano với cô giáo.","examples":[{"example":"母から料理を習いました。","example_reading":"ははからりょうりをならいました。","example_meaning":"Tôi đã học nấu ăn từ mẹ."},{"example":"週に一回、水泳を習いに行きます。","example_reading":"しゅうにいっかい、すいえいをならいにいきます。","example_meaning":"Mỗi tuần một lần tôi đi học bơi."}]},{"word":"学ぶ","reading":"まなぶ","meaning":"học hỏi, tiếp thu","example":"失敗から多くのことを学びました。","example_reading":"しっぱいからおおくのことをまなびました。","example_meaning":"Tôi đã học được nhiều điều từ thất bại.","examples":[{"example":"大学で経済を学んでいます。","example_reading":"だいがくでけいざいをまなんでいます。","example_meaning":"Tôi đang học kinh tế ở đại học."},{"example":"歴史から学ぶことは大切です。","example_reading":"れきしからまなぶことはたいせつです。","example_meaning":"Học hỏi từ lịch sử là điều quan trọng."}]}]},
{"label":"守る／従う","note":"守る(まもる): BẢO VỆ, GIỮ (lời hứa, luật lệ, quy tắc, người thân). 従う(したがう): TUÂN THEO, nghe theo (mệnh lệnh, chỉ thị, người có quyền hơn).","items":[{"word":"守る","reading":"まもる","meaning":"bảo vệ, giữ (luật, lời hứa)","example":"交通ルールを守りましょう。","example_reading":"こうつうるーるをまもりましょう。","example_meaning":"Hãy tuân thủ luật giao thông.","examples":[{"example":"親は子どもを守るものだ。","example_reading":"おやはこどもをまもるものだ。","example_meaning":"Cha mẹ là người bảo vệ con cái."},{"example":"約束の時間を守ってください。","example_reading":"やくそくのじかんをまもってください。","example_meaning":"Xin hãy giữ đúng giờ đã hẹn."}]},{"word":"従う","reading":"したがう","meaning":"tuân theo, nghe theo","example":"上司の指示に従います。","example_reading":"じょうしのしじにしたがいます。","example_meaning":"Tôi sẽ làm theo chỉ thị của cấp trên.","examples":[{"example":"係員の案内に従ってください。","example_reading":"かかりいんのあんないにしたがってください。","example_meaning":"Xin hãy làm theo hướng dẫn của nhân viên."},{"example":"彼は親の意見に従って、進学を決めた。","example_reading":"かれはおやのいけんにしたがって、しんがくをきめた。","example_meaning":"Anh ấy nghe theo ý kiến của bố mẹ và quyết định học lên."}]}]},
{"label":"続ける／続く／継続","note":"続ける(つづける): TIẾP TỤC làm (tha động từ, do chủ ý). 続く(つづく): TIẾP DIỄN, kéo dài (tự động từ, sự việc tự nó tiếp tục). 継続(けいぞく): DUY TRÌ liên tục (danh từ, trang trọng, hoạt động, hợp đồng).","items":[{"word":"続ける","reading":"つづける","meaning":"tiếp tục (làm gì)","example":"毎日日記を書き続けています。","example_reading":"まいにちにっきをかきつづけています。","example_meaning":"Tôi vẫn tiếp tục viết nhật ký mỗi ngày.","examples":[{"example":"疲れたけれど、仕事を続けた。","example_reading":"つかれたけれど、しごとをつづけた。","example_meaning":"Dù mệt nhưng tôi vẫn tiếp tục làm việc."},{"example":"雨の中でも、練習を続けました。","example_reading":"あめのなかでも、れんしゅうをつづけました。","example_meaning":"Dù trong mưa chúng tôi vẫn tiếp tục luyện tập."}]},{"word":"続く","reading":"つづく","meaning":"tiếp diễn, kéo dài","example":"雨が一週間続いています。","example_reading":"あめがいっしゅうかんつづいています。","example_meaning":"Mưa đã kéo dài suốt một tuần.","examples":[{"example":"この道はまっすぐ駅まで続いている。","example_reading":"このみちはまっすぐえきまでつづいている。","example_meaning":"Con đường này kéo thẳng đến tận nhà ga."},{"example":"暑い日が続くので、体に気をつけてください。","example_reading":"あついひがつづくので、からだにきをつけてください。","example_meaning":"Vì những ngày nóng kéo dài nên hãy giữ gìn sức khỏe."}]},{"word":"継続","reading":"けいぞく","meaning":"duy trì liên tục","example":"長期的な支援を継続します。","example_reading":"ちょうきてきなしえんをけいぞくします。","example_meaning":"Chúng tôi sẽ tiếp tục hỗ trợ lâu dài.","examples":[{"example":"継続は力なり。","example_reading":"けいぞくはちからなり。","example_meaning":"Kiên trì chính là sức mạnh."},{"example":"契約の継続について話し合った。","example_reading":"けいやくのけいぞくについてはなしあった。","example_meaning":"Chúng tôi đã bàn về việc tiếp tục hợp đồng."}]}]},
{"label":"増える／増加／増す","note":"増える(ふえる): TĂNG LÊN về số lượng (tự động từ, khẩu ngữ). 増加(ぞうか): SỰ GIA TĂNG (danh từ, trang trọng, hay dùng trong thống kê). 増す(ます): TĂNG THÊM về mức độ, cường độ (văn viết: 勢い, 不安, 人気).","items":[{"word":"増える","reading":"ふえる","meaning":"tăng lên (số lượng)","example":"最近、外国人の観光客が増えました。","example_reading":"さいきん、がいこくじんのかんこうきゃくがふえました。","example_meaning":"Gần đây khách du lịch nước ngoài đã tăng lên.","examples":[{"example":"体重が三キロ増えてしまった。","example_reading":"たいじゅうがさんきろふえてしまった。","example_meaning":"Tôi lỡ tăng mất ba cân."},{"example":"仕事が増えて、忙しくなった。","example_reading":"しごとがふえて、いそがしくなった。","example_meaning":"Công việc nhiều lên nên tôi trở nên bận rộn."}]},{"word":"増加","reading":"ぞうか","meaning":"gia tăng (trang trọng)","example":"人口が年々増加しています。","example_reading":"じんこうがねんねんぞうかしています。","example_meaning":"Dân số đang tăng lên qua từng năm.","examples":[{"example":"交通事故の件数は増加傾向にある。","example_reading":"こうつうじこのけんすうはぞうかけいこうにある。","example_meaning":"Số vụ tai nạn giao thông có xu hướng tăng."},{"example":"輸出の増加が経済を支えている。","example_reading":"ゆしゅつのぞうかがけいざいをささえている。","example_meaning":"Xuất khẩu tăng đang hỗ trợ nền kinh tế."}]},{"word":"増す","reading":"ます","meaning":"tăng thêm (mức độ)","example":"夜になって、風が勢いを増した。","example_reading":"よるになって、かぜがいきおいをました。","example_meaning":"Đêm xuống, gió mạnh thêm.","examples":[{"example":"日が経つにつれて、不安が増してきた。","example_reading":"ひがたつにつれて、ふあんがましてきた。","example_meaning":"Ngày càng trôi qua, nỗi bất an càng tăng."},{"example":"雨で川の水かさが増している。","example_reading":"あめでかわのみずかさがましている。","example_meaning":"Mực nước sông đang dâng lên vì mưa."}]}]},
{"label":"減る／減少／減らす","note":"減る(へる): GIẢM đi (tự động từ, khẩu ngữ). 減少(げんしょう): SỰ GIẢM SÚT (danh từ, trang trọng, thống kê). 減らす(へらす): LÀM GIẢM (tha động từ, chủ ý giảm bớt).","items":[{"word":"減る","reading":"へる","meaning":"giảm đi, bớt đi","example":"お腹が減りました。","example_reading":"おなかがへりました。","example_meaning":"Tôi đói bụng rồi.","examples":[{"example":"最近、貯金が減ってきた。","example_reading":"さいきん、ちょきんがへってきた。","example_meaning":"Gần đây tiền tiết kiệm của tôi ngày càng ít đi."},{"example":"客が減って、店が困っている。","example_reading":"きゃくがへって、みせがこまっている。","example_meaning":"Khách giảm nên cửa tiệm đang gặp khó khăn."}]},{"word":"減少","reading":"げんしょう","meaning":"sự giảm sút","example":"子どもの数が減少しています。","example_reading":"こどものかずがげんしょうしています。","example_meaning":"Số lượng trẻ em đang giảm.","examples":[{"example":"魚の漁獲量が大きく減少した。","example_reading":"さかなのぎょかくりょうがおおきくげんしょうした。","example_meaning":"Sản lượng đánh bắt cá đã giảm mạnh."},{"example":"人口の減少が社会問題になっている。","example_reading":"じんこうのげんしょうがしゃかいもんだいになっている。","example_meaning":"Dân số giảm đang trở thành vấn đề xã hội."}]},{"word":"減らす","reading":"へらす","meaning":"làm giảm, cắt giảm","example":"塩の量を減らしましょう。","example_reading":"しおのりょうをへらしましょう。","example_meaning":"Hãy giảm lượng muối đi.","examples":[{"example":"残業を減らす努力をしています。","example_reading":"ざんぎょうをへらすどりょくをしています。","example_meaning":"Chúng tôi đang nỗ lực giảm làm thêm giờ."},{"example":"ゴミを減らすために、袋を持ち歩いている。","example_reading":"ごみをへらすために、ふくろをもちあるいている。","example_meaning":"Để giảm rác, tôi luôn mang theo túi bên mình."}]}]},
{"label":"断る／拒否／辞退","note":"断る(ことわる): TỪ CHỐI lời mời, yêu cầu một cách thông thường, lịch sự. 拒否(きょひ): KHƯỚC TỪ dứt khoát, bác bỏ (mạnh, cứng). 辞退(じたい): TỪ CHỐI một cách khiêm nhường việc nhận/tham gia (giải thưởng, chức vụ, lời mời).","items":[{"word":"断る","reading":"ことわる","meaning":"từ chối (lịch sự)","example":"誘いを断るのは難しい。","example_reading":"さそいをことわるのはむずかしい。","example_meaning":"Từ chối lời mời thật khó.","examples":[{"example":"忙しいので、その仕事は断りました。","example_reading":"いそがしいので、そのしごとはことわりました。","example_meaning":"Vì bận nên tôi đã từ chối công việc đó."},{"example":"彼女のお願いを断れなかった。","example_reading":"かのじょのおねがいをことわれなかった。","example_meaning":"Tôi đã không thể từ chối lời nhờ vả của cô ấy."}]},{"word":"拒否","reading":"きょひ","meaning":"khước từ, bác bỏ","example":"彼は要求を完全に拒否した。","example_reading":"かれはようきゅうをかんぜんにきょひした。","example_meaning":"Anh ta đã hoàn toàn bác bỏ yêu cầu.","examples":[{"example":"入国を拒否されてしまった。","example_reading":"にゅうこくをきょひされてしまった。","example_meaning":"Tôi đã bị từ chối nhập cảnh."},{"example":"相手は話し合いを拒否している。","example_reading":"あいてははなしあいをきょひしている。","example_meaning":"Phía bên kia đang khước từ việc đàm phán."}]},{"word":"辞退","reading":"じたい","meaning":"từ chối (khiêm nhường)","example":"選ばれたが、体調が悪いので辞退した。","example_reading":"えらばれたが、たいちょうがわるいのでじたいした。","example_meaning":"Tôi được chọn nhưng vì sức khỏe không tốt nên đã xin từ chối.","examples":[{"example":"優勝したが、賞金は辞退します。","example_reading":"ゆうしょうしたが、しょうきんはじたいします。","example_meaning":"Tuy vô địch nhưng tôi xin không nhận tiền thưởng."},{"example":"彼は会長への就任を辞退した。","example_reading":"かれはかいちょうへのしゅうにんをじたいした。","example_meaning":"Ông ấy đã từ chối nhậm chức chủ tịch."}]}]},
{"label":"謝る／お詫び／反省","note":"謝る(あやまる): XIN LỖI trực tiếp với ai đó (động từ, dùng hàng ngày). お詫び(おわび): LỜI XIN LỖI trang trọng (danh từ, kính ngữ, thông báo, thư từ). 反省(はんせい): TỰ KIỂM ĐIỂM, nhìn lại lỗi lầm để rút kinh nghiệm (không nhất thiết nói với ai).","items":[{"word":"謝る","reading":"あやまる","meaning":"xin lỗi","example":"遅れて、友達に謝りました。","example_reading":"おくれて、ともだちにあやまりました。","example_meaning":"Tôi đến muộn nên đã xin lỗi bạn.","examples":[{"example":"悪いと思ったらすぐ謝るべきだ。","example_reading":"わるいとおもったらすぐあやまるべきだ。","example_meaning":"Nếu thấy mình sai thì nên xin lỗi ngay."},{"example":"何度も謝ったが、許してもらえなかった。","example_reading":"なんどもあやまったが、ゆるしてもらえなかった。","example_meaning":"Tôi đã xin lỗi nhiều lần nhưng không được tha thứ."}]},{"word":"お詫び","reading":"おわび","meaning":"lời xin lỗi (trang trọng)","example":"ご迷惑をおかけしたことをお詫び申し上げます。","example_reading":"ごめいわくをおかけしたことをおわびもうしあげます。","example_meaning":"Chúng tôi xin lỗi vì đã gây phiền hà.","examples":[{"example":"遅延のお詫びに、割引券をお渡しします。","example_reading":"ちえんのおわびに、わりびきけんをおわたしします。","example_meaning":"Để xin lỗi vì sự chậm trễ, chúng tôi xin gửi phiếu giảm giá."},{"example":"お詫びの手紙を書いた。","example_reading":"おわびのてがみをかいた。","example_meaning":"Tôi đã viết một bức thư xin lỗi."}]},{"word":"反省","reading":"はんせい","meaning":"tự kiểm điểm, nhìn lại","example":"自分の失敗を反省しています。","example_reading":"じぶんのしっぱいをはんせいしています。","example_meaning":"Tôi đang tự kiểm điểm lại thất bại của mình.","examples":[{"example":"今日の行動を反省して、明日に生かしたい。","example_reading":"きょうのこうどうをはんせいして、あしたにいかしたい。","example_meaning":"Tôi muốn nhìn lại hành động hôm nay và vận dụng vào ngày mai."},{"example":"彼は反省の色が見えない。","example_reading":"かれははんせいのいろがみえない。","example_meaning":"Anh ta chẳng có vẻ gì là biết hối lỗi."}]}]},
{"label":"褒める／称賛／感心","note":"褒める(ほめる): KHEN (hàng ngày, người trên khen người dưới hoặc bạn bè). 称賛(しょうさん): TÁN DƯƠNG, ca ngợi công khai (trang trọng, thành tích lớn). 感心(かんしん): THÁN PHỤC, cảm kích trước tài năng/hành động của ai (cảm xúc trong lòng).","items":[{"word":"褒める","reading":"ほめる","meaning":"khen","example":"先生に作文を褒められました。","example_reading":"せんせいにさくぶんをほめられました。","example_meaning":"Tôi được cô giáo khen bài văn.","examples":[{"example":"子どもは褒めて育てたほうがいい。","example_reading":"こどもはほめてそだてたほうがいい。","example_meaning":"Nên nuôi dạy trẻ bằng cách khen ngợi."},{"example":"母は私の料理を褒めてくれた。","example_reading":"ははわたしのりょうりをほめてくれた。","example_meaning":"Mẹ đã khen món ăn tôi nấu."}]},{"word":"称賛","reading":"しょうさん","meaning":"tán dương, ca ngợi","example":"彼の勇気ある行動は称賛された。","example_reading":"かれのゆうきあるこうどうはしょうさんされた。","example_meaning":"Hành động dũng cảm của anh ấy đã được ca ngợi.","examples":[{"example":"世界中から称賛の声が上がった。","example_reading":"せかいじゅうからしょうさんのこえがあがった。","example_meaning":"Lời ca ngợi vang lên từ khắp thế giới."},{"example":"優勝チームに称賛の拍手が送られた。","example_reading":"ゆうしょうちーむにしょうさんのはくしゅがおくられた。","example_meaning":"Tràng pháo tay tán dương dành cho đội vô địch."}]},{"word":"感心","reading":"かんしん","meaning":"thán phục, cảm kích","example":"彼の努力には感心します。","example_reading":"かれのどりょくにはかんしんします。","example_meaning":"Tôi thán phục sự nỗ lực của anh ấy.","examples":[{"example":"小学生なのに敬語が使えて、感心した。","example_reading":"しょうがくせいなのにけいごがつかえて、かんしんした。","example_meaning":"Mới là học sinh tiểu học mà đã biết dùng kính ngữ, tôi thật thán phục."},{"example":"彼女の話に思わず感心してしまった。","example_reading":"かのじょのはなしにおもわずかんしんしてしまった。","example_meaning":"Tôi bất giác thán phục câu chuyện của cô ấy."}]}]},
{"label":"笑う／微笑む／苦笑","note":"笑う(わらう): CƯỜI (nói chung, thường thành tiếng). 微笑む(ほほえむ): MỈM CƯỜI, cười nhẹ không thành tiếng. 苦笑(くしょう): CƯỜI GƯỢNG, cười trừ, cười khổ (bất lực, ngượng ngùng).","items":[{"word":"笑う","reading":"わらう","meaning":"cười","example":"みんなで大声で笑いました。","example_reading":"みんなでおおごえでわらいました。","example_meaning":"Mọi người cùng cười lớn.","examples":[{"example":"彼のジョークに思わず笑った。","example_reading":"かれのじょーくにおもわずわらった。","example_meaning":"Tôi bất giác bật cười vì câu đùa của anh ấy."},{"example":"失敗しても、笑って許してくれた。","example_reading":"しっぱいしても、わらってゆるしてくれた。","example_meaning":"Dù tôi làm hỏng, họ vẫn cười và tha thứ."}]},{"word":"微笑む","reading":"ほほえむ","meaning":"mỉm cười","example":"赤ちゃんがにっこり微笑んだ。","example_reading":"あかちゃんがにっこりほほえんだ。","example_meaning":"Em bé mỉm cười tươi tắn.","examples":[{"example":"彼女は優しく微笑んで、うなずいた。","example_reading":"かのじょはやさしくほほえんで、うなずいた。","example_meaning":"Cô ấy mỉm cười dịu dàng và gật đầu."},{"example":"写真の中で、祖母が微笑んでいる。","example_reading":"しゃしんのなかで、そぼがほほえんでいる。","example_meaning":"Trong bức ảnh, bà tôi đang mỉm cười."}]},{"word":"苦笑","reading":"くしょう","meaning":"cười gượng, cười khổ","example":"失敗を指摘されて、苦笑するしかなかった。","example_reading":"しっぱいをしてきされて、くしょうするしかなかった。","example_meaning":"Bị chỉ ra lỗi sai, tôi chỉ biết cười gượng.","examples":[{"example":"彼の言い訳に、みんな苦笑した。","example_reading":"かれのいいわけに、みんなくしょうした。","example_meaning":"Trước lời bào chữa của anh ta, ai cũng cười khổ."},{"example":"苦笑いを浮かべて、その場を離れた。","example_reading":"にがわらいをうかべて、そのばをはなれた。","example_meaning":"Tôi nở nụ cười gượng rồi rời khỏi chỗ đó."}]}]},
{"label":"泣く／涙ぐむ／嘆く","note":"泣く(なく): KHÓC (nói chung, có thể thành tiếng, rơi nước mắt). 涙ぐむ(なみだぐむ): RƯNG RƯNG nước mắt (chưa khóc hẳn, xúc động). 嘆く(なげく): THAN THỞ, đau buồn than vãn về chuyện đáng tiếc.","items":[{"word":"泣く","reading":"なく","meaning":"khóc","example":"映画を見て、大声で泣いてしまった。","example_reading":"えいがをみて、おおごえでないてしまった。","example_meaning":"Xem phim xong, tôi lỡ khóc to.","examples":[{"example":"赤ちゃんが夜中に泣いて、眠れなかった。","example_reading":"あかちゃんがよなかにないて、ねむれなかった。","example_meaning":"Em bé khóc giữa đêm nên tôi không ngủ được."},{"example":"悲しくて、一人で泣きました。","example_reading":"かなしくて、ひとりでなきました。","example_meaning":"Buồn quá nên tôi đã khóc một mình."}]},{"word":"涙ぐむ","reading":"なみだぐむ","meaning":"rưng rưng nước mắt","example":"卒業式で、先生は涙ぐんでいた。","example_reading":"そつぎょうしきで、せんせいはなみだぐんでいた。","example_meaning":"Trong lễ tốt nghiệp, thầy giáo đã rưng rưng nước mắt.","examples":[{"example":"母の手紙を読んで、思わず涙ぐんだ。","example_reading":"ははのてがみをよんで、おもわずなみだぐんだ。","example_meaning":"Đọc thư của mẹ, tôi bất giác rưng rưng nước mắt."},{"example":"彼女は涙ぐみながら、感謝の言葉を述べた。","example_reading":"かのじょはなみだぐみながら、かんしゃのことばをのべた。","example_meaning":"Cô ấy vừa rưng rưng nước mắt vừa nói lời cảm ơn."}]},{"word":"嘆く","reading":"なげく","meaning":"than thở, đau buồn","example":"若者の言葉の乱れを嘆く人は多い。","example_reading":"わかもののことばのみだれをなげくひとはおおい。","example_meaning":"Có nhiều người than phiền về cách nói năng lộn xộn của giới trẻ.","examples":[{"example":"自分の運命を嘆いても、何も変わらない。","example_reading":"じぶんのうんめいをなげいても、なにもかわらない。","example_meaning":"Có than thở về số phận thì cũng chẳng thay đổi được gì."},{"example":"彼は失敗を嘆いてばかりいる。","example_reading":"かれはしっぱいをなげいてばかりいる。","example_meaning":"Anh ta chỉ suốt ngày than thở về thất bại."}]}]},
{"label":"疲れる／疲労／くたびれる","note":"疲れる(つかれる): MỆT (nói chung, thể xác lẫn tinh thần). 疲労(ひろう): MỆT MỎI (danh từ, trang trọng, y học/công việc: 疲労がたまる). くたびれる: MỆT RÃ RỜI, kiệt sức (khẩu ngữ), cũng dùng cho đồ vật cũ sờn.","items":[{"word":"疲れる","reading":"つかれる","meaning":"mệt","example":"今日はたくさん歩いて、疲れました。","example_reading":"きょうはたくさんあるいて、つかれました。","example_meaning":"Hôm nay đi bộ nhiều nên tôi mệt.","examples":[{"example":"人と話すと疲れる。","example_reading":"ひととはなすとつかれる。","example_meaning":"Nói chuyện với người khác khiến tôi mệt."},{"example":"疲れているので、早く寝ます。","example_reading":"つかれているので、はやくねます。","example_meaning":"Vì đang mệt nên tôi sẽ đi ngủ sớm."}]},{"word":"疲労","reading":"ひろう","meaning":"mệt mỏi (trang trọng)","example":"疲労がたまっているので、休みを取りたい。","example_reading":"ひろうがたまっているので、やすみをとりたい。","example_meaning":"Mệt mỏi dồn lại nên tôi muốn xin nghỉ.","examples":[{"example":"長時間の運転は疲労の原因になる。","example_reading":"ちょうじかんのうんてんはひろうのげんいんになる。","example_meaning":"Lái xe lâu là nguyên nhân gây mệt mỏi."},{"example":"彼は疲労のため倒れてしまった。","example_reading":"かれはひろうのためたおれてしまった。","example_meaning":"Anh ấy đã ngã quỵ vì kiệt sức."}]},{"word":"くたびれる","reading":"くたびれる","meaning":"mệt rã rời, kiệt sức","example":"一日中立ちっぱなしで、くたびれた。","example_reading":"いちにちじゅうたちっぱなしで、くたびれた。","example_meaning":"Đứng suốt cả ngày nên tôi mệt rã rời.","examples":[{"example":"待ちくたびれて、帰ってしまった。","example_reading":"まちくたびれて、かえってしまった。","example_meaning":"Chờ mệt quá nên tôi đã về mất."},{"example":"くたびれたコートを、もう十年着ている。","example_reading":"くたびれたこーとを、もうじゅうねんきている。","example_meaning":"Tôi đã mặc chiếc áo khoác sờn cũ này suốt mười năm."}]}]},
{"label":"忙しい／多忙／慌ただしい","note":"忙しい(いそがしい): BẬN (nói chung, dùng hàng ngày). 多忙(たぼう): BẬN RỘN (trang trọng, thư từ, công việc). 慌ただしい(あわただしい): BỘN BỀ, vội vã, rối ren (thời gian gấp, thiếu bình tĩnh).","items":[{"word":"忙しい","reading":"いそがしい","meaning":"bận","example":"今週はとても忙しいです。","example_reading":"こんしゅうはとてもいそがしいです。","example_meaning":"Tuần này tôi rất bận.","examples":[{"example":"忙しいところ、すみません。","example_reading":"いそがしいところ、すみません。","example_meaning":"Xin lỗi vì làm phiền lúc anh đang bận."},{"example":"忙しくて、昼ごはんを食べる時間もなかった。","example_reading":"いそがしくて、ひるごはんをたべるじかんもなかった。","example_meaning":"Bận đến mức không có cả thời gian ăn trưa."}]},{"word":"多忙","reading":"たぼう","meaning":"bận rộn (trang trọng)","example":"ご多忙のところ、恐れ入ります。","example_reading":"ごたぼうのところ、おそれいります。","example_meaning":"Xin lỗi đã làm phiền lúc ngài đang bận rộn.","examples":[{"example":"社長は多忙な毎日を送っている。","example_reading":"しゃちょうはたぼうなまいにちをおくっている。","example_meaning":"Giám đốc đang trải qua những ngày bận rộn."},{"example":"多忙のため、会議には出席できません。","example_reading":"たぼうのため、かいぎにはしゅっせきできません。","example_meaning":"Vì bận rộn nên tôi không thể tham dự cuộc họp."}]},{"word":"慌ただしい","reading":"あわただしい","meaning":"bộn bề, vội vã","example":"年末は慌ただしくて、あっという間に過ぎる。","example_reading":"ねんまつはあわただしくて、あっというまにすぎる。","example_meaning":"Cuối năm bộn bề nên trôi qua trong chớp mắt.","examples":[{"example":"慌ただしい朝は、朝ごはんを食べる暇もない。","example_reading":"あわただしいあさは、あさごはんをたべるひまもない。","example_meaning":"Những buổi sáng vội vã thì chẳng có thời gian ăn sáng."},{"example":"引っ越しの準備で、慌ただしい日が続いた。","example_reading":"ひっこしのじゅんびで、あわただしいひがつづいた。","example_meaning":"Những ngày tất bật chuẩn bị chuyển nhà cứ kéo dài."}]}]},
{"label":"暇／余裕／のんびり","note":"暇(ひま): RẢNH RỖI, có thời gian trống. 余裕(よゆう): THỪA THÃI, DƯ DẢ (thời gian, tiền bạc, tinh thần). のんびり: THONG THẢ, thư thả, không vội vàng.","items":[{"word":"暇","reading":"ひま","meaning":"rảnh rỗi","example":"今日は暇なので、映画を見に行きます。","example_reading":"きょうはひまなので、えいがをみにいきます。","example_meaning":"Hôm nay rảnh nên tôi đi xem phim.","examples":[{"example":"暇があったら、遊びに来てください。","example_reading":"ひまがあったら、あそびにきてください。","example_meaning":"Nếu rảnh thì hãy ghé chơi nhé."},{"example":"暇を持て余して、一日中ゲームをした。","example_reading":"ひまをもてあまして、いちにちじゅうげーむをした。","example_meaning":"Rảnh quá không biết làm gì nên tôi chơi game cả ngày."}]},{"word":"余裕","reading":"よゆう","meaning":"dư dả, thong thả","example":"時間に余裕を持って出かけましょう。","example_reading":"じかんによゆうをもってでかけましょう。","example_meaning":"Hãy ra khỏi nhà sớm để còn dư dả thời gian.","examples":[{"example":"今は忙しくて、旅行する余裕がない。","example_reading":"いまはいそがしくて、りょこうするよゆうがない。","example_meaning":"Bây giờ bận quá nên tôi không có thời gian để đi du lịch."},{"example":"彼は試験前でも余裕の表情だった。","example_reading":"かれはしけんまえでもよゆうのひょうじょうだった。","example_meaning":"Dù trước kỳ thi, anh ấy vẫn có vẻ rất thong dong."}]},{"word":"のんびり","reading":"のんびり","meaning":"thong thả, thư thả","example":"休みの日は、家でのんびり過ごします。","example_reading":"やすみのひは、いえでのんびりすごします。","example_meaning":"Ngày nghỉ tôi thong thả ở nhà.","examples":[{"example":"田舎でのんびり暮らしたい。","example_reading":"いなかでのんびりくらしたい。","example_meaning":"Tôi muốn sống thư thả ở miền quê."},{"example":"温泉にのんびり浸かって、疲れを取った。","example_reading":"おんせんにのんびりつかって、つかれをとった。","example_meaning":"Tôi ngâm suối nước nóng thư giãn để xua tan mệt mỏi."}]}]},
{"label":"急ぐ／焦る／慌てる","note":"急ぐ(いそぐ): VỘI, KHẨN TRƯƠNG làm nhanh (hành động). 焦る(あせる): SỐT RUỘT, NÔN NÓNG (tâm trạng, muốn nhanh mà lo lắng). 慌てる(あわてる): HOẢNG HỐT, CUỐNG LÊN (khi bất ngờ, mất bình tĩnh).","items":[{"word":"急ぐ","reading":"いそぐ","meaning":"vội, khẩn trương","example":"遅れそうなので、急ぎましょう。","example_reading":"おくれそうなので、いそぎましょう。","example_meaning":"Có vẻ sắp muộn rồi, chúng ta nhanh lên thôi.","examples":[{"example":"急ぎの仕事があるので、先に帰ります。","example_reading":"いそぎのしごとがあるので、さきにかえります。","example_meaning":"Tôi có việc gấp nên xin về trước."},{"example":"急がなくても、まだ時間があります。","example_reading":"いそがなくても、まだじかんがあります。","example_meaning":"Không cần vội đâu, vẫn còn thời gian."}]},{"word":"焦る","reading":"あせる","meaning":"nôn nóng, sốt ruột","example":"時間がなくて、焦ってしまった。","example_reading":"じかんがなくて、あせってしまった。","example_meaning":"Không còn thời gian nên tôi đã sốt ruột.","examples":[{"example":"焦らないで、ゆっくりやりなさい。","example_reading":"あせらないで、ゆっくりやりなさい。","example_meaning":"Đừng nôn nóng, cứ từ từ mà làm."},{"example":"周りの人が先に進んで、焦りを感じた。","example_reading":"まわりのひとがさきにすすんで、あせりをかんじた。","example_meaning":"Thấy mọi người xung quanh tiến lên trước, tôi cảm thấy sốt ruột."}]},{"word":"慌てる","reading":"あわてる","meaning":"hoảng hốt, cuống lên","example":"財布がなくて、慌てて探した。","example_reading":"さいふがなくて、あわててさがした。","example_meaning":"Mất ví nên tôi cuống cuồng đi tìm.","examples":[{"example":"慌てると、ミスが増えるよ。","example_reading":"あわてると、みすがふえるよ。","example_meaning":"Cuống lên là sẽ sai nhiều hơn đấy."},{"example":"地震が起きても、慌てずに行動してください。","example_reading":"じしんがおきても、あわてずにこうどうしてください。","example_meaning":"Dù có động đất cũng hãy hành động bình tĩnh, đừng hoảng hốt."}]}]},
{"label":"我慢／辛抱／耐える","note":"我慢(がまん): NHỊN, CHỊU ĐỰNG (cơn đau, ham muốn, bất mãn; khẩu ngữ). 辛抱(しんぼう): KIÊN NHẪN chịu đựng bền bỉ cho đến khi đạt kết quả. 耐える(たえる): CHỊU ĐƯỢC, CHỐNG CHỊU (sức nặng, nóng lạnh, nỗi đau).","items":[{"word":"我慢","reading":"がまん","meaning":"nhịn, chịu đựng","example":"痛いけど、我慢します。","example_reading":"いたいけど、がまんします。","example_meaning":"Đau nhưng tôi sẽ cố nhịn.","examples":[{"example":"ケーキを食べたいのを我慢している。","example_reading":"けーきをたべたいのをがまんしている。","example_meaning":"Tôi đang nhịn không ăn bánh ngọt."},{"example":"もう我慢できない。","example_reading":"もうがまんできない。","example_meaning":"Tôi không thể chịu đựng thêm được nữa."}]},{"word":"辛抱","reading":"しんぼう","meaning":"kiên nhẫn chịu đựng","example":"成功するまで辛抱が必要です。","example_reading":"せいこうするまでしんぼうがひつようです。","example_meaning":"Cần phải kiên nhẫn cho đến khi thành công.","examples":[{"example":"辛抱強く待てば、いいことがある。","example_reading":"しんぼうづよくまてば、いいことがある。","example_meaning":"Nếu kiên nhẫn chờ đợi sẽ có điều tốt đẹp."},{"example":"辛抱して続けた結果、資格が取れた。","example_reading":"しんぼうしてつづけたけっか、しかくがとれた。","example_meaning":"Nhờ kiên trì theo đuổi, tôi đã lấy được chứng chỉ."}]},{"word":"耐える","reading":"たえる","meaning":"chịu được, chống chịu","example":"この橋は大きな地震にも耐えられる。","example_reading":"このはしはおおきなじしんにもたえられる。","example_meaning":"Cây cầu này chịu được cả những trận động đất lớn.","examples":[{"example":"厳しい寒さに耐えて、冬を越した。","example_reading":"きびしいさむさにたえて、ふゆをこした。","example_meaning":"Chịu đựng cái lạnh khắc nghiệt, tôi đã vượt qua mùa đông."},{"example":"彼女は悲しみに耐えていた。","example_reading":"かのじょはかなしみにたえていた。","example_meaning":"Cô ấy đang gắng chịu đựng nỗi buồn."}]}]},
{"label":"比べる／比較／対比","note":"比べる(くらべる): SO SÁNH (hàng ngày, đặt cạnh nhau xem hơn kém). 比較(ひかく): SO SÁNH (trang trọng, phân tích, học thuật). 対比(たいひ): ĐỐI CHIẾU, làm nổi bật sự tương phản giữa hai thứ.","items":[{"word":"比べる","reading":"くらべる","meaning":"so sánh","example":"兄と比べられるのは嫌だ。","example_reading":"あにとくらべられるのはいやだ。","example_meaning":"Tôi ghét bị đem ra so sánh với anh trai.","examples":[{"example":"二つの値段を比べて、安いほうを買った。","example_reading":"ふたつのねだんをくらべて、やすいほうをかった。","example_meaning":"Tôi so giá hai món rồi mua món rẻ hơn."},{"example":"去年に比べて、今年は暑い。","example_reading":"きょねんにくらべて、ことしはあつい。","example_meaning":"So với năm ngoái, năm nay nóng hơn."}]},{"word":"比較","reading":"ひかく","meaning":"so sánh (trang trọng)","example":"各社の商品を比較して選んだ。","example_reading":"かくしゃのしょうひんをひかくしてえらんだ。","example_meaning":"Tôi đã so sánh sản phẩm của các hãng rồi mới chọn.","examples":[{"example":"日本とベトナムの文化を比較する。","example_reading":"にほんとべとなむのぶんかをひかくする。","example_meaning":"So sánh văn hóa Nhật Bản và Việt Nam."},{"example":"他国との比較が難しい問題だ。","example_reading":"たこくとのひかくがむずかしいもんだいだ。","example_meaning":"Đây là vấn đề khó so sánh với các nước khác."}]},{"word":"対比","reading":"たいひ","meaning":"đối chiếu, tương phản","example":"都会と田舎の暮らしを対比して論じた。","example_reading":"とかいといなかのくらしをたいひしてろんじた。","example_meaning":"Tôi đã đối chiếu và bàn luận về cuộc sống thành thị và nông thôn.","examples":[{"example":"白と黒の対比が美しい絵だ。","example_reading":"しろとくろのたいひがうつくしいえだ。","example_meaning":"Đây là bức tranh đẹp nhờ sự tương phản giữa trắng và đen."},{"example":"二人の性格の対比が、物語のおもしろさだ。","example_reading":"ふたりのせいかくのたいひが、ものがたりのおもしろさだ。","example_meaning":"Sự đối lập về tính cách của hai người chính là điểm hay của câu chuyện."}]}]},
{"label":"違い／差／区別","note":"違い(ちがい): KHÁC BIỆT về tính chất, nội dung (A khác B). 差(さ): CHÊNH LỆCH có thể đo bằng con số (giá, điểm, nhiệt độ, tuổi). 区別(くべつ): PHÂN BIỆT, tách ra để nhận ra (hành động).","items":[{"word":"違い","reading":"ちがい","meaning":"sự khác biệt","example":"二つの言葉の違いを教えてください。","example_reading":"ふたつのことばのちがいをおしえてください。","example_meaning":"Hãy cho tôi biết sự khác nhau giữa hai từ này.","examples":[{"example":"日本と私の国の習慣の違いに驚いた。","example_reading":"にほんとわたしのくにのしゅうかんのちがいにおどろいた。","example_meaning":"Tôi ngạc nhiên trước sự khác biệt về phong tục giữa Nhật và nước tôi."},{"example":"双子だが、性格に大きな違いがある。","example_reading":"ふたごだが、せいかくにおおきなちがいがある。","example_meaning":"Tuy là sinh đôi nhưng tính cách rất khác nhau."}]},{"word":"差","reading":"さ","meaning":"chênh lệch","example":"昼と夜の温度の差が大きい。","example_reading":"ひるとよるのおんどのさがおおきい。","example_meaning":"Chênh lệch nhiệt độ giữa ngày và đêm rất lớn.","examples":[{"example":"二人の点数の差はたった一点だった。","example_reading":"ふたりのてんすうのさはたったいってんだった。","example_meaning":"Điểm của hai người chỉ chênh nhau đúng một điểm."},{"example":"年齢の差を気にせず、仲良く話した。","example_reading":"ねんれいのさをきにせず、なかよくはなした。","example_meaning":"Họ không bận tâm đến chênh lệch tuổi tác mà trò chuyện thân thiết."}]},{"word":"区別","reading":"くべつ","meaning":"phân biệt","example":"本物と偽物を区別するのは難しい。","example_reading":"ほんものとにせものをくべつするのはむずかしい。","example_meaning":"Phân biệt hàng thật và hàng giả rất khó.","examples":[{"example":"公私を区別して働く。","example_reading":"こうしをくべつしてはたらく。","example_meaning":"Tôi làm việc và phân biệt rõ chuyện công và tư."},{"example":"この二つの字は似ていて、区別がつかない。","example_reading":"このふたつのじはにていて、くべつがつかない。","example_meaning":"Hai chữ này giống nhau nên tôi không phân biệt được."}]}]},
{"label":"似ている／同じ／そっくり","note":"似ている(にている): GIỐNG nhau ở một số điểm (hình dáng, tính cách, tương tự). 同じ(おなじ): GIỐNG HỆT, CÙNG (đồng nhất hoàn toàn). そっくり: GIỐNG NHƯ ĐÚC, y chang (nhấn mạnh rất giống, khẩu ngữ).","items":[{"word":"似ている","reading":"にている","meaning":"giống, tương tự","example":"私は父に似ています。","example_reading":"わたしはちちににています。","example_meaning":"Tôi giống bố.","examples":[{"example":"この二つの言葉は意味が似ている。","example_reading":"このふたつのことばはいみがにている。","example_meaning":"Hai từ này có nghĩa tương tự nhau."},{"example":"姉と妹は声がよく似ている。","example_reading":"あねといもうとはこえがよくにている。","example_meaning":"Chị gái và em gái có giọng nói rất giống nhau."}]},{"word":"同じ","reading":"おなじ","meaning":"giống hệt, cùng","example":"私たちは同じ会社で働いています。","example_reading":"わたしたちはおなじかいしゃではたらいています。","example_meaning":"Chúng tôi làm việc ở cùng một công ty.","examples":[{"example":"友達と同じ服を買ってしまった。","example_reading":"ともだちとおなじふくをかってしまった。","example_meaning":"Tôi lỡ mua đúng bộ đồ giống bạn."},{"example":"みんな同じ意見だった。","example_reading":"みんなおなじいけんだった。","example_meaning":"Mọi người đều có cùng ý kiến."}]},{"word":"そっくり","reading":"そっくり","meaning":"giống như đúc","example":"彼女は母親にそっくりだ。","example_reading":"かのじょはははおやにそっくりだ。","example_meaning":"Cô ấy giống mẹ như đúc.","examples":[{"example":"その人形は本物そっくりに作られている。","example_reading":"そのにんぎょうはほんものそっくりにつくられている。","example_meaning":"Con búp bê đó được làm giống hệt người thật."},{"example":"双子はそっくりで、誰も区別できない。","example_reading":"ふたごはそっくりで、だれもくべつできない。","example_meaning":"Cặp song sinh giống nhau như đúc, không ai phân biệt được."}]}]},
{"label":"集める／集まる／集中","note":"集める(あつめる): THU THẬP, TẬP HỢP (tha động từ, chủ động gom lại). 集まる(あつまる): TỤ TẬP, ĐƯỢC TẬP HỢP (tự động từ, tự tụ lại). 集中(しゅうちゅう): TẬP TRUNG (tinh thần vào một việc, hoặc dồn về một nơi).","items":[{"word":"集める","reading":"あつめる","meaning":"thu thập, tập hợp","example":"切手を集めるのが趣味です。","example_reading":"きってをあつめるのがしゅみです。","example_meaning":"Sở thích của tôi là sưu tầm tem.","examples":[{"example":"会議のために、資料を集めた。","example_reading":"かいぎのために、しりょうをあつめた。","example_meaning":"Tôi đã thu thập tài liệu cho cuộc họp."},{"example":"寄付を集めて、学校を建てた。","example_reading":"きふをあつめて、がっこうをたてた。","example_meaning":"Họ quyên góp tiền để xây trường học."}]},{"word":"集まる","reading":"あつまる","meaning":"tụ tập, được tập hợp","example":"駅前に百人ぐらい集まっていた。","example_reading":"えきまえにひゃくにんぐらいあつまっていた。","example_meaning":"Khoảng một trăm người đã tụ tập trước nhà ga.","examples":[{"example":"毎月、友達の家に集まります。","example_reading":"まいつき、ともだちのいえにあつまります。","example_meaning":"Mỗi tháng chúng tôi lại tụ tập ở nhà một người bạn."},{"example":"事故現場に人が集まってきた。","example_reading":"じこげんばにひとがあつまってきた。","example_meaning":"Mọi người đã đổ dồn về hiện trường vụ tai nạn."}]},{"word":"集中","reading":"しゅうちゅう","meaning":"tập trung","example":"静かな場所のほうが集中できる。","example_reading":"しずかなばしょのほうがしゅうちゅうできる。","example_meaning":"Ở nơi yên tĩnh thì dễ tập trung hơn.","examples":[{"example":"勉強に集中して、時間を忘れた。","example_reading":"べんきょうにしゅうちゅうして、じかんをわすれた。","example_meaning":"Tôi tập trung học đến mức quên cả thời gian."},{"example":"人口が都市に集中している。","example_reading":"じんこうがとしにしゅうちゅうしている。","example_meaning":"Dân số đang tập trung vào các thành phố."}]}]},
{"label":"選ぶ／選択／決める","note":"選ぶ(えらぶ): CHỌN trong nhiều thứ (hành động). 選択(せんたく): LỰA CHỌN (danh từ, trang trọng, cân nhắc, đáp án). 決める(きめる): QUYẾT ĐỊNH, CHỐT (kết thúc việc phân vân).","items":[{"word":"選ぶ","reading":"えらぶ","meaning":"chọn","example":"好きな色を選んでください。","example_reading":"すきないろをえらんでください。","example_meaning":"Hãy chọn màu mà bạn thích.","examples":[{"example":"たくさんあって、どれを選べばいいか分からない。","example_reading":"たくさんあって、どれをえらべばいいかわからない。","example_meaning":"Nhiều quá nên tôi không biết nên chọn cái nào."},{"example":"彼女は看護師という仕事を選んだ。","example_reading":"かのじょはかんごしというしごとをえらんだ。","example_meaning":"Cô ấy đã chọn nghề y tá."}]},{"word":"選択","reading":"せんたく","meaning":"lựa chọn","example":"正しい選択をするのは難しい。","example_reading":"ただしいせんたくをするのはむずかしい。","example_meaning":"Đưa ra lựa chọn đúng thật là khó.","examples":[{"example":"選択肢の中から一つ選んでください。","example_reading":"せんたくしのなかからひとつえらんでください。","example_meaning":"Hãy chọn một đáp án trong các lựa chọn."},{"example":"選択科目は自由に決められる。","example_reading":"せんたくかもくはじゆうにきめられる。","example_meaning":"Môn tự chọn có thể chọn tự do."}]},{"word":"決める","reading":"きめる","meaning":"quyết định, chốt","example":"旅行の行き先を決めました。","example_reading":"りょこうのいきさきをきめました。","example_meaning":"Tôi đã quyết định điểm đến của chuyến du lịch.","examples":[{"example":"来週の会議の日程を決めましょう。","example_reading":"らいしゅうのかいぎのにっていをきめましょう。","example_meaning":"Hãy chốt lịch cuộc họp tuần sau nào."},{"example":"自分で決めたことは、最後までやる。","example_reading":"じぶんできめたことは、さいごまでやる。","example_meaning":"Việc đã tự mình quyết định thì tôi sẽ làm đến cùng."}]}]},
{"label":"作る／造る／創る","note":"作る(つくる): LÀM, TẠO RA (nói chung: món ăn, đồ vật, quy tắc). 造る(つくる): CHẾ TẠO, XÂY DỰNG quy mô lớn (tàu, nhà máy, rượu, vườn). 創る(つくる): SÁNG TẠO ra cái mới chưa từng có (nghệ thuật, văn hóa, tương lai).","items":[{"word":"作る","reading":"つくる","meaning":"làm, tạo ra (nói chung)","example":"母は毎朝お弁当を作ってくれる。","example_reading":"ははまいあさおべんとうをつくってくれる。","example_meaning":"Mẹ làm cơm hộp cho tôi mỗi sáng.","examples":[{"example":"新しい友達を作りたい。","example_reading":"あたらしいともだちをつくりたい。","example_meaning":"Tôi muốn kết thêm bạn mới."},{"example":"粘土で動物を作った。","example_reading":"ねんどでどうぶつをつくった。","example_meaning":"Tôi đã nặn động vật bằng đất sét."}]},{"word":"造る","reading":"つくる","meaning":"chế tạo, xây dựng (quy mô lớn)","example":"この会社は大きな船を造っています。","example_reading":"このかいしゃはおおきなふねをつくっています。","example_meaning":"Công ty này đóng những con tàu lớn.","examples":[{"example":"庭に池を造った。","example_reading":"にわにいけをつくった。","example_meaning":"Tôi đã xây một cái ao trong vườn."},{"example":"酒を造る職人に話を聞いた。","example_reading":"さけをつくるしょくにんにはなしをきいた。","example_meaning":"Tôi đã nghe chuyện từ người thợ nấu rượu."}]},{"word":"創る","reading":"つくる","meaning":"sáng tạo (cái mới)","example":"新しい文化を創ることが目標だ。","example_reading":"あたらしいぶんかをつくることがもくひょうだ。","example_meaning":"Mục tiêu là sáng tạo ra một nền văn hóa mới.","examples":[{"example":"彼は自分の力で未来を創っていく。","example_reading":"かれはじぶんのちからでみらいをつくっていく。","example_meaning":"Anh ấy sẽ tự mình kiến tạo tương lai bằng sức lực của mình."},{"example":"新しい音楽を創るアーティストになりたい。","example_reading":"あたらしいおんがくをつくるあーてぃすとになりたい。","example_meaning":"Tôi muốn trở thành nghệ sĩ sáng tạo ra âm nhạc mới."}]}]},
{"label":"直す／治す／修理","note":"直す(なおす): SỬA, CHỈNH (lỗi sai, thói quen, đồ vật hỏng nhỏ, kiểu tóc). 治す(なおす): CHỮA TRỊ (bệnh, vết thương). 修理(しゅうり): SỬA CHỮA máy móc, thiết bị (danh từ, thường nhờ thợ).","items":[{"word":"直す","reading":"なおす","meaning":"sửa, chỉnh","example":"間違いを直してください。","example_reading":"まちがいをなおしてください。","example_meaning":"Hãy sửa lỗi sai đi.","examples":[{"example":"悪い癖を直したい。","example_reading":"わるいくせをなおしたい。","example_meaning":"Tôi muốn sửa thói quen xấu."},{"example":"壊れた自転車を直した。","example_reading":"こわれたじてんしゃをなおした。","example_meaning":"Tôi đã sửa chiếc xe đạp bị hỏng."}]},{"word":"治す","reading":"なおす","meaning":"chữa trị","example":"風邪を早く治したい。","example_reading":"かぜをはやくなおしたい。","example_meaning":"Tôi muốn mau khỏi cảm.","examples":[{"example":"薬を飲んで、病気を治します。","example_reading":"くすりをのんで、びょうきをなおします。","example_meaning":"Tôi uống thuốc để chữa bệnh."},{"example":"この傷は、治すのに時間がかかる。","example_reading":"このきずは、なおすのにじかんがかかる。","example_meaning":"Vết thương này mất thời gian để chữa lành."}]},{"word":"修理","reading":"しゅうり","meaning":"sửa chữa (máy móc)","example":"壊れたパソコンを修理に出した。","example_reading":"こわれたぱそこんをしゅうりにだした。","example_meaning":"Tôi đã đem chiếc máy tính hỏng đi sửa.","examples":[{"example":"修理には一週間ほどかかります。","example_reading":"しゅうりにはいっしゅうかんほどかかります。","example_meaning":"Việc sửa chữa mất khoảng một tuần."},{"example":"車の修理代が高くて驚いた。","example_reading":"くるまのしゅうりだいがたかくておどろいた。","example_meaning":"Tôi ngạc nhiên vì tiền sửa xe đắt quá."}]}]},
{"label":"変える／換える／替える","note":"変える(かえる): THAY ĐỔI tính chất, hình thức (ý kiến, kế hoạch, màu sắc). 換える(かえる): ĐỔI sang thứ khác tương đương (tiền, không khí, tàu xe). 替える(かえる): THAY THẾ cái cũ bằng cái mới cùng loại (quần áo, người, bóng đèn).","items":[{"word":"変える","reading":"かえる","meaning":"thay đổi (tính chất, hình thức)","example":"考えを変えました。","example_reading":"かんがえをかえました。","example_meaning":"Tôi đã thay đổi suy nghĩ.","examples":[{"example":"髪型を変えて、気分も変わった。","example_reading":"かみがたをかえて、きぶんもかわった。","example_meaning":"Đổi kiểu tóc xong, tâm trạng cũng thay đổi."},{"example":"予定を変えてもいいですか。","example_reading":"よていをかえてもいいですか。","example_meaning":"Tôi thay đổi kế hoạch được không?"}]},{"word":"換える","reading":"かえる","meaning":"đổi (sang cái tương đương)","example":"円をドルに換えたい。","example_reading":"えんをどるにかえたい。","example_meaning":"Tôi muốn đổi yên sang đô la.","examples":[{"example":"窓を開けて、空気を換えましょう。","example_reading":"まどをあけて、くうきをかえましょう。","example_meaning":"Hãy mở cửa sổ để thay đổi không khí."},{"example":"新宿で地下鉄に乗り換えます。","example_reading":"しんじゅくでちかてつにのりかえます。","example_meaning":"Tôi sẽ đổi sang tàu điện ngầm ở Shinjuku."}]},{"word":"替える","reading":"かえる","meaning":"thay thế (cái mới cùng loại)","example":"シャツを替えて、出かけた。","example_reading":"しゃつをかえて、でかけた。","example_meaning":"Tôi thay áo sơ mi rồi ra ngoài.","examples":[{"example":"電球を新しいものに替えました。","example_reading":"でんきゅうをあたらしいものにかえました。","example_meaning":"Tôi đã thay bóng đèn mới."},{"example":"選手を替えて、試合に臨んだ。","example_reading":"せんしゅをかえて、しあいにのぞんだ。","example_meaning":"Họ thay cầu thủ rồi bước vào trận đấu."}]}]},
{"label":"越える／超える","note":"越える(こえる): VƯỢT QUA ranh giới, địa điểm, thời kỳ (núi, biên giới, khó khăn, năm tháng). 超える(こえる): VƯỢT QUÁ một con số, mức độ, giới hạn (nhiệt độ, số người, ngân sách).","items":[{"word":"越える","reading":"こえる","meaning":"vượt qua (ranh giới, khó khăn)","example":"山を越えると、海が見えた。","example_reading":"やまをこえると、うみがみえた。","example_meaning":"Vượt qua ngọn núi thì thấy biển.","examples":[{"example":"国境を越えて、隣の国に入った。","example_reading":"こっきょうをこえて、となりのくににはいった。","example_meaning":"Họ vượt qua biên giới và vào nước láng giềng."},{"example":"困難を越えて、夢をかなえた。","example_reading":"こんなんをこえて、ゆめをかなえた。","example_meaning":"Vượt qua khó khăn, anh ấy đã thực hiện được ước mơ."}]},{"word":"超える","reading":"こえる","meaning":"vượt quá (mức, con số)","example":"気温が三十五度を超えた。","example_reading":"きおんがさんじゅうごどをこえた。","example_meaning":"Nhiệt độ đã vượt quá 35 độ.","examples":[{"example":"参加者は千人を超えている。","example_reading":"さんかしゃはせんにんをこえている。","example_meaning":"Số người tham gia đã vượt quá một nghìn."},{"example":"予算を超えてしまった。","example_reading":"よさんをこえてしまった。","example_meaning":"Tôi lỡ vượt quá ngân sách mất rồi."}]}]},
{"label":"計る／測る／量る","note":"計る(はかる): ĐO/TÍNH thời gian, số lượng, tính toán thời cơ (タイム, 時間, タイミング). 測る(はかる): ĐO độ dài, độ cao, diện tích, nhiệt độ bằng dụng cụ. 量る(はかる): CÂN, ĐONG khối lượng, dung tích (体重, 重さ, 砂糖).","items":[{"word":"計る","reading":"はかる","meaning":"đo (thời gian, số lượng)","example":"百メートル走のタイムを計りました。","example_reading":"ひゃくめーとるそうのたいむをはかりました。","example_meaning":"Tôi đã đo thời gian chạy 100 mét.","examples":[{"example":"時間を計って、問題を解いた。","example_reading":"じかんをはかって、もんだいをといた。","example_meaning":"Tôi bấm giờ rồi giải bài tập."},{"example":"タイミングを計って、話しかけた。","example_reading":"たいみんぐをはかって、はなしかけた。","example_meaning":"Tôi chọn đúng thời điểm rồi mới bắt chuyện."}]},{"word":"測る","reading":"はかる","meaning":"đo (độ dài, nhiệt độ)","example":"体温を測ってください。","example_reading":"たいおんをはかってください。","example_meaning":"Xin hãy đo nhiệt độ cơ thể.","examples":[{"example":"部屋の広さを測った。","example_reading":"へやのひろさをはかった。","example_meaning":"Tôi đã đo diện tích căn phòng."},{"example":"身長を測ったら、去年より五センチ伸びていた。","example_reading":"しんちょうをはかったら、きょねんよりごせんちのびていた。","example_meaning":"Đo chiều cao thì thấy cao hơn năm ngoái 5 cm."}]},{"word":"量る","reading":"はかる","meaning":"cân, đong (khối lượng)","example":"体重を量りました。","example_reading":"たいじゅうをはかりました。","example_meaning":"Tôi đã cân cân nặng.","examples":[{"example":"砂糖を百グラム量って、鍋に入れた。","example_reading":"さとうをひゃくぐらむはかって、なべにいれた。","example_meaning":"Tôi cân 100 gram đường rồi cho vào nồi."},{"example":"荷物の重さを量ってもらった。","example_reading":"にもつのおもさをはかってもらった。","example_meaning":"Tôi nhờ người ta cân giúp trọng lượng hành lý."}]}]},
{"label":"熱い／暑い／厚い","note":"熱い(あつい): NÓNG của vật, chất khi chạm vào (nước, trà, canh, bàn tay). 暑い(あつい): NÓNG của thời tiết, khí hậu. 厚い(あつい): DÀY (sách, vải, thịt), cũng dùng nghĩa bóng 'nồng hậu' (友情, 支援).","items":[{"word":"熱い","reading":"あつい","meaning":"nóng (vật, chất)","example":"熱いお茶を飲んで、体が温まった。","example_reading":"あついおちゃをのんで、からだがあたたまった。","example_meaning":"Uống trà nóng xong, cơ thể ấm lên.","examples":[{"example":"このスープは熱いので、気をつけて。","example_reading":"このすーぷはあついので、きをつけて。","example_meaning":"Món súp này nóng nên hãy cẩn thận."},{"example":"熱いお風呂に入るのが好きだ。","example_reading":"あついおふろにはいるのがすきだ。","example_meaning":"Tôi thích tắm bồn nước nóng."}]},{"word":"暑い","reading":"あつい","meaning":"nóng (thời tiết)","example":"今日は朝から暑いですね。","example_reading":"きょうはあさからあついですね。","example_meaning":"Hôm nay trời nóng từ sáng nhỉ.","examples":[{"example":"夏のベトナムはとても暑い。","example_reading":"なつのべとなむはとてもあつい。","example_meaning":"Mùa hè ở Việt Nam rất nóng."},{"example":"暑いので、窓を開けた。","example_reading":"あついので、まどをあけた。","example_meaning":"Vì nóng nên tôi đã mở cửa sổ."}]},{"word":"厚い","reading":"あつい","meaning":"dày","example":"厚い本を一週間で読んだ。","example_reading":"あついほんをいっしゅうかんでよんだ。","example_meaning":"Tôi đã đọc xong cuốn sách dày trong một tuần.","examples":[{"example":"冬は厚いコートが欠かせない。","example_reading":"ふゆはあついこーとがかかせない。","example_meaning":"Mùa đông không thể thiếu chiếc áo khoác dày."},{"example":"二人は厚い友情で結ばれている。","example_reading":"ふたりはあついゆうじょうでむすばれている。","example_meaning":"Hai người gắn bó bởi một tình bạn sâu đậm."}]}]},
{"label":"早い／速い","note":"早い(はやい): SỚM (về thời điểm, thời gian: 朝が早い, まだ早い). 速い(はやい): NHANH (về tốc độ, chuyển động: 足が速い, 速い車).","items":[{"word":"早い","reading":"はやい","meaning":"sớm","example":"今日は朝が早かったので、眠い。","example_reading":"きょうはあさがはやかったので、ねむい。","example_meaning":"Hôm nay dậy sớm nên tôi buồn ngủ.","examples":[{"example":"まだ早いから、もう少し寝よう。","example_reading":"まだはやいから、もうすこしねよう。","example_meaning":"Vẫn còn sớm nên ngủ thêm chút nữa."},{"example":"結論を出すのは、まだ早いと思います。","example_reading":"けつろんをだすのは、まだはやいとおもいます。","example_meaning":"Tôi nghĩ vẫn còn quá sớm để đưa ra kết luận."}]},{"word":"速い","reading":"はやい","meaning":"nhanh (tốc độ)","example":"彼は走るのが速い。","example_reading":"かれははしるのがはやい。","example_meaning":"Anh ấy chạy nhanh.","examples":[{"example":"新幹線は車より速い。","example_reading":"しんかんせんはくるまよりはやい。","example_meaning":"Shinkansen nhanh hơn ô tô."},{"example":"速いスピードで、車が通り過ぎた。","example_reading":"はやいすぴーどで、くるまがとおりすぎた。","example_meaning":"Chiếc xe lao qua với tốc độ nhanh."}]}]},
{"label":"渡す／届ける／送る","note":"渡す(わたす): ĐƯA, TRAO tận tay cho ai (cũng là bắc qua). 届ける(とどける): GIAO ĐẾN tận nơi (mang tới địa chỉ, nộp đồ nhặt được). 送る(おくる): GỬI (bưu phẩm, tin nhắn), TIỄN/ĐƯA ai đó đi.","items":[{"word":"渡す","reading":"わたす","meaning":"trao, đưa tận tay","example":"この書類を部長に渡してください。","example_reading":"このしょるいをぶちょうにわたしてください。","example_meaning":"Hãy đưa tài liệu này cho trưởng phòng.","examples":[{"example":"友達に誕生日プレゼントを渡した。","example_reading":"ともだちにたんじょうびぷれぜんとをわたした。","example_meaning":"Tôi đã trao quà sinh nhật cho bạn."},{"example":"川に橋を渡して、村と村をつないだ。","example_reading":"かわにはしをわたして、むらとむらをつないだ。","example_meaning":"Họ bắc cầu qua sông để nối hai ngôi làng."}]},{"word":"届ける","reading":"とどける","meaning":"giao đến, mang tới","example":"忘れ物を交番に届けました。","example_reading":"わすれものをこうばんにとどけました。","example_meaning":"Tôi đã nộp đồ bỏ quên ở đồn cảnh sát.","examples":[{"example":"荷物を午前中に届けてもらえますか。","example_reading":"にもつをごぜんちゅうにとどけてもらえますか。","example_meaning":"Anh có thể giao hành lý trong buổi sáng được không?"},{"example":"祖母に手作りのパンを届けた。","example_reading":"そぼにてづくりのぱんをとどけた。","example_meaning":"Tôi đã mang bánh mì tự làm đến cho bà."}]},{"word":"送る","reading":"おくる","meaning":"gửi, tiễn","example":"母に荷物を送りました。","example_reading":"ははににもつをおくりました。","example_meaning":"Tôi đã gửi hành lý cho mẹ.","examples":[{"example":"駅まで友達を送った。","example_reading":"えきまでともだちをおくった。","example_meaning":"Tôi đã tiễn bạn ra tận ga."},{"example":"メールで資料を送ります。","example_reading":"めーるでしりょうをおくります。","example_meaning":"Tôi sẽ gửi tài liệu qua email."}]}]},
{"label":"持つ／抱える／背負う","note":"持つ(もつ): CẦM, MANG, SỞ HỮU (nói chung). 抱える(かかえる): ÔM trong tay, GÁNH (vật to; vấn đề, nợ nần, khó khăn). 背負う(せおう): ĐEO SAU LƯNG, GÁNH VÁC (trách nhiệm, gánh nặng lớn).","items":[{"word":"持つ","reading":"もつ","meaning":"cầm, mang, sở hữu","example":"かばんを持ってあげましょう。","example_reading":"かばんをもってあげましょう。","example_meaning":"Để tôi cầm cặp giúp bạn.","examples":[{"example":"彼は車を二台持っている。","example_reading":"かれはくるまをにだいもっている。","example_meaning":"Anh ấy có hai chiếc ô tô."},{"example":"日本語に興味を持っています。","example_reading":"にほんごにきょうみをもっています。","example_meaning":"Tôi có hứng thú với tiếng Nhật."}]},{"word":"抱える","reading":"かかえる","meaning":"ôm, gánh (vấn đề)","example":"大きな箱を両手で抱えて運んだ。","example_reading":"おおきなはこをりょうてでかかえてはこんだ。","example_meaning":"Tôi ôm cái hộp lớn bằng hai tay rồi mang đi.","examples":[{"example":"彼は多くの問題を抱えている。","example_reading":"かれはおおくのもんだいをかかえている。","example_meaning":"Anh ấy đang gánh nhiều vấn đề."},{"example":"頭を抱えて、考え込んだ。","example_reading":"あたまをかかえて、かんがえこんだ。","example_meaning":"Anh ôm đầu và chìm vào suy nghĩ."}]},{"word":"背負う","reading":"せおう","meaning":"đeo sau lưng, gánh vác","example":"重いリュックを背負って、山を登った。","example_reading":"おもいりゅっくをせおって、やまをのぼった。","example_meaning":"Tôi đeo ba lô nặng leo núi.","examples":[{"example":"彼は家族の生活を背負っている。","example_reading":"かれはかぞくのせいかつをせおっている。","example_meaning":"Anh ấy đang gánh vác cuộc sống của cả gia đình."},{"example":"若いうちから大きな責任を背負った。","example_reading":"わかいうちからおおきなせきにんをせおった。","example_meaning":"Anh ấy đã gánh trách nhiệm lớn từ khi còn trẻ."}]}]},
{"label":"確認／確かめる／点検","note":"確認(かくにん): XÁC NHẬN, KIỂM TRA LẠI cho chắc chắn (thông tin, thời gian, nội dung). 確かめる(たしかめる): KIỂM CHỨNG, làm cho rõ ràng (bằng mắt, tay, thực tế). 点検(てんけん): KIỂM TRA TỪNG HẠNG MỤC (máy móc, thiết bị, an toàn).","items":[{"word":"確認","reading":"かくにん","meaning":"xác nhận, kiểm tra lại","example":"予約の日時を確認してください。","example_reading":"よやくのにちじをかくにんしてください。","example_meaning":"Xin hãy xác nhận ngày giờ đặt chỗ.","examples":[{"example":"メールが届いたか、確認します。","example_reading":"めーるがとどいたか、かくにんします。","example_meaning":"Tôi sẽ kiểm tra xem email đã đến chưa."},{"example":"内容を確認してから、サインしてください。","example_reading":"ないようをかくにんしてから、さいんしてください。","example_meaning":"Hãy xem lại nội dung rồi hẵng ký tên."}]},{"word":"確かめる","reading":"たしかめる","meaning":"kiểm chứng, làm rõ","example":"自分の目で確かめたい。","example_reading":"じぶんのめでたしかめたい。","example_meaning":"Tôi muốn tự mắt mình kiểm chứng.","examples":[{"example":"火が消えたかどうか、確かめた。","example_reading":"ひがきえたかどうか、たしかめた。","example_meaning":"Tôi đã kiểm tra xem lửa đã tắt chưa."},{"example":"本当かどうか、電話で確かめてみよう。","example_reading":"ほんとうかどうか、でんわでたしかめてみよう。","example_meaning":"Thử gọi điện để xác minh xem có thật không."}]},{"word":"点検","reading":"てんけん","meaning":"kiểm tra từng hạng mục","example":"エレベーターを毎月点検している。","example_reading":"えれべーたーをまいつきてんけんしている。","example_meaning":"Thang máy được kiểm tra mỗi tháng.","examples":[{"example":"出発前に、車を点検した。","example_reading":"しゅっぱつまえに、くるまをてんけんした。","example_meaning":"Trước khi xuất phát, tôi đã kiểm tra xe."},{"example":"定期点検のため、運転を休止します。","example_reading":"ていきてんけんのため、うんてんをきゅうしします。","example_meaning":"Vì kiểm tra định kỳ nên tạm ngừng vận hành."}]}]},
{"label":"調べる／検査／調査","note":"調べる(しらべる): TRA CỨU, TÌM HIỂU (hàng ngày: từ điển, internet). 検査(けんさ): KIỂM TRA, XÉT NGHIỆM theo tiêu chuẩn (y tế, hành lý, chất lượng). 調査(ちょうさ): ĐIỀU TRA, KHẢO SÁT (nghiên cứu, thống kê, thực địa).","items":[{"word":"調べる","reading":"しらべる","meaning":"tra cứu, tìm hiểu","example":"辞書で意味を調べました。","example_reading":"じしょでいみをしらべました。","example_meaning":"Tôi đã tra nghĩa trong từ điển.","examples":[{"example":"電車の時間を調べておきます。","example_reading":"でんしゃのじかんをしらべておきます。","example_meaning":"Tôi sẽ tra sẵn giờ tàu."},{"example":"警察が事件の原因を調べている。","example_reading":"けいさつがじけんのげんいんをしらべている。","example_meaning":"Cảnh sát đang điều tra nguyên nhân vụ việc."}]},{"word":"検査","reading":"けんさ","meaning":"kiểm tra, xét nghiệm","example":"病院で血液検査を受けた。","example_reading":"びょういんでけつえきけんさをうけた。","example_meaning":"Tôi đã xét nghiệm máu ở bệnh viện.","examples":[{"example":"空港で荷物の検査があった。","example_reading":"くうこうでにもつのけんさがあった。","example_meaning":"Ở sân bay có kiểm tra hành lý."},{"example":"製品の品質を検査してから出荷する。","example_reading":"せいひんのひんしつをけんさしてからしゅっかする。","example_meaning":"Sản phẩm được kiểm tra chất lượng rồi mới xuất xưởng."}]},{"word":"調査","reading":"ちょうさ","meaning":"điều tra, khảo sát","example":"市民の生活について調査を行った。","example_reading":"しみんのせいかつについてちょうさをおこなった。","example_meaning":"Đã tiến hành khảo sát về cuộc sống của người dân.","examples":[{"example":"事故の原因を調査中です。","example_reading":"じこのげんいんをちょうさちゅうです。","example_meaning":"Đang điều tra nguyên nhân vụ tai nạn."},{"example":"アンケート調査の結果が発表された。","example_reading":"あんけーとちょうさのけっかがはっぴょうされた。","example_meaning":"Kết quả khảo sát bằng bảng hỏi đã được công bố."}]}]},
{"label":"報告／連絡／相談","note":"報告(ほうこく): BÁO CÁO (thường cấp dưới → cấp trên về kết quả, tiến độ). 連絡(れんらく): LIÊN LẠC, THÔNG BÁO (truyền đạt thông tin, giữ liên hệ). 相談(そうだん): BÀN BẠC, XIN Ý KIẾN trước khi quyết định.","items":[{"word":"報告","reading":"ほうこく","meaning":"báo cáo","example":"仕事の結果を課長に報告しました。","example_reading":"しごとのけっかをかちょうにほうこくしました。","example_meaning":"Tôi đã báo cáo kết quả công việc cho trưởng nhóm.","examples":[{"example":"問題があったら、すぐ報告してください。","example_reading":"もんだいがあったら、すぐほうこくしてください。","example_meaning":"Nếu có vấn đề thì hãy báo cáo ngay."},{"example":"出張の報告書を作成した。","example_reading":"しゅっちょうのほうこくしょをさくせいした。","example_meaning":"Tôi đã soạn báo cáo chuyến công tác."}]},{"word":"連絡","reading":"れんらく","meaning":"liên lạc, thông báo","example":"遅れる時は、必ず連絡してください。","example_reading":"おくれるときは、かならずれんらくしてください。","example_meaning":"Khi đến muộn nhất định hãy liên lạc.","examples":[{"example":"友達から連絡が来て、飲みに行くことになった。","example_reading":"ともだちかられんらくがきて、のみにいくことになった。","example_meaning":"Bạn liên lạc nên chúng tôi quyết định đi uống."},{"example":"連絡先を教えてもらえますか。","example_reading":"れんらくさきをおしえてもらえますか。","example_meaning":"Anh cho tôi xin thông tin liên lạc được không?"}]},{"word":"相談","reading":"そうだん","meaning":"bàn bạc, xin ý kiến","example":"進路について先生に相談しました。","example_reading":"しんろについてせんせいにそうだんしました。","example_meaning":"Tôi đã hỏi ý kiến thầy cô về hướng đi sau này.","examples":[{"example":"困ったことがあれば、いつでも相談してください。","example_reading":"こまったことがあれば、いつでもそうだんしてください。","example_meaning":"Nếu gặp khó khăn gì, hãy cứ trao đổi với tôi bất cứ lúc nào."},{"example":"家族と相談してから決めます。","example_reading":"かぞくとそうだんしてからきめます。","example_meaning":"Tôi sẽ bàn với gia đình rồi mới quyết định."}]}]},
{"label":"説明／解説／案内","note":"説明(せつめい): GIẢI THÍCH để người khác hiểu (nói chung). 解説(かいせつ): GIẢI THÍCH CHI TIẾT/BÌNH LUẬN của người am hiểu (tin tức, thể thao, sách). 案内(あんない): HƯỚNG DẪN, DẪN ĐƯỜNG, GIỚI THIỆU (chỉ đường, thông báo, thiệp mời).","items":[{"word":"説明","reading":"せつめい","meaning":"giải thích","example":"使い方を説明してもらいました。","example_reading":"つかいかたをせつめいしてもらいました。","example_meaning":"Tôi đã được giải thích cách sử dụng.","examples":[{"example":"遅れた理由を説明してください。","example_reading":"おくれたりゆうをせつめいしてください。","example_meaning":"Hãy giải thích lý do bạn đến muộn."},{"example":"先生の説明は分かりやすい。","example_reading":"せんせいのせつめいはわかりやすい。","example_meaning":"Lời giải thích của thầy rất dễ hiểu."}]},{"word":"解説","reading":"かいせつ","meaning":"giải thích chi tiết, bình luận","example":"ニュースの解説を聞いて、よく分かった。","example_reading":"にゅーすのかいせつをきいて、よくわかった。","example_meaning":"Nghe bình luận về bản tin xong tôi hiểu rõ hơn.","examples":[{"example":"サッカーの試合を専門家が解説している。","example_reading":"さっかーのしあいをせんもんかがかいせつしている。","example_meaning":"Chuyên gia đang bình luận trận bóng đá."},{"example":"この本には、文法の詳しい解説がある。","example_reading":"このほんには、ぶんぽうのくわしいかいせつがある。","example_meaning":"Cuốn sách này có phần giải thích ngữ pháp chi tiết."}]},{"word":"案内","reading":"あんない","meaning":"hướng dẫn, dẫn đường","example":"友達に京都を案内しました。","example_reading":"ともだちにきょうとをあんないしました。","example_meaning":"Tôi đã dẫn bạn đi tham quan Kyoto.","examples":[{"example":"駅から会場まで案内します。","example_reading":"えきからかいじょうまであんないします。","example_meaning":"Tôi sẽ dẫn bạn từ ga đến địa điểm tổ chức."},{"example":"結婚式の案内状が届いた。","example_reading":"けっこんしきのあんないじょうがとどいた。","example_meaning":"Thiệp mời đám cưới đã được gửi đến."}]}]},
{"label":"意見／考え／主張","note":"意見(いけん): Ý KIẾN, quan điểm nói ra với người khác (trong thảo luận, họp hành). 考え(かんがえ): SUY NGHĨ, Ý NGHĨ (trong đầu, mang tính cá nhân, rộng). 主張(しゅちょう): KHẲNG ĐỊNH, KIÊN QUYẾT TUYÊN BỐ quan điểm của mình.","items":[{"word":"意見","reading":"いけん","meaning":"ý kiến","example":"会議で自分の意見を言いました。","example_reading":"かいぎでじぶんのいけんをいいました。","example_meaning":"Tôi đã nói ý kiến của mình trong cuộc họp.","examples":[{"example":"みなさんの意見を聞かせてください。","example_reading":"みなさんのいけんをきかせてください。","example_meaning":"Xin hãy cho tôi nghe ý kiến của mọi người."},{"example":"私は彼の意見に反対です。","example_reading":"わたしはかれのいけんにはんたいです。","example_meaning":"Tôi phản đối ý kiến của anh ấy."}]},{"word":"考え","reading":"かんがえ","meaning":"suy nghĩ, ý nghĩ","example":"私の考えを聞いてください。","example_reading":"わたしのかんがえをきいてください。","example_meaning":"Hãy nghe suy nghĩ của tôi.","examples":[{"example":"彼とは考え方が違う。","example_reading":"かれとはかんがえかたがちがう。","example_meaning":"Cách suy nghĩ của tôi khác với anh ấy."},{"example":"留学するという考えが浮かんだ。","example_reading":"りゅうがくするというかんがえがうかんだ。","example_meaning":"Trong đầu tôi chợt nảy ra ý định đi du học."}]},{"word":"主張","reading":"しゅちょう","meaning":"khẳng định, tuyên bố","example":"彼は最後まで自分の無実を主張した。","example_reading":"かれはさいごまでじぶんのむじつをしゅちょうした。","example_meaning":"Anh ta khăng khăng khẳng định mình vô tội đến cùng.","examples":[{"example":"自分の主張ばかりしていると、嫌われる。","example_reading":"じぶんのしゅちょうばかりしていると、きらわれる。","example_meaning":"Cứ chỉ khăng khăng ý mình thì sẽ bị ghét."},{"example":"両方の主張を聞いて、判断する。","example_reading":"りょうほうのしゅちょうをきいて、はんだんする。","example_meaning":"Nghe lập luận của cả hai bên rồi mới phán đoán."}]}]},
{"label":"興味／関心／好奇心","note":"興味(きょうみ): HỨNG THÚ, thấy thú vị muốn biết (sở thích cá nhân). 関心(かんしん): QUAN TÂM, chú ý đến (vấn đề xã hội, tin tức, người khác). 好奇心(こうきしん): TÒ MÒ, ham muốn khám phá điều mới.","items":[{"word":"興味","reading":"きょうみ","meaning":"hứng thú","example":"日本の歴史に興味があります。","example_reading":"にほんのれきしにきょうみがあります。","example_meaning":"Tôi có hứng thú với lịch sử Nhật Bản.","examples":[{"example":"彼はスポーツには興味がないらしい。","example_reading":"かれはすぽーつにはきょうみがないらしい。","example_meaning":"Hình như anh ấy không hứng thú với thể thao."},{"example":"興味を持ったことは、すぐ調べる。","example_reading":"きょうみをもったことは、すぐしらべる。","example_meaning":"Điều gì thấy hứng thú là tôi tra cứu ngay."}]},{"word":"関心","reading":"かんしん","meaning":"quan tâm","example":"環境問題への関心が高まっている。","example_reading":"かんきょうもんだいへのかんしんがたかまっている。","example_meaning":"Sự quan tâm đến vấn đề môi trường đang tăng lên.","examples":[{"example":"若者は政治に関心が薄いと言われる。","example_reading":"わかものはせいじにかんしんがうすいといわれる。","example_meaning":"Người ta nói giới trẻ ít quan tâm đến chính trị."},{"example":"その事件は世間の関心を集めた。","example_reading":"そのじけんはせけんのかんしんをあつめた。","example_meaning":"Vụ việc đó đã thu hút sự quan tâm của dư luận."}]},{"word":"好奇心","reading":"こうきしん","meaning":"tính tò mò","example":"子どもは好奇心が強い。","example_reading":"こどもはこうきしんがつよい。","example_meaning":"Trẻ con rất tò mò.","examples":[{"example":"好奇心から、知らない道を歩いてみた。","example_reading":"こうきしんから、しらないみちをあるいてみた。","example_meaning":"Vì tò mò nên tôi thử đi vào con đường lạ."},{"example":"彼女の好奇心は、いつも新しい発見につながる。","example_reading":"かのじょのこうきしんは、いつもあたらしいはっけんにつながる。","example_meaning":"Sự tò mò của cô ấy luôn dẫn đến những khám phá mới."}]}]},
{"label":"能力／才能／実力","note":"能力(のうりょく): NĂNG LỰC, khả năng làm việc (có thể rèn luyện, đo đạc được). 才能(さいのう): TÀI NĂNG bẩm sinh (nghệ thuật, thể thao). 実力(じつりょく): THỰC LỰC, sức mạnh thật sự khi thể hiện ra.","items":[{"word":"能力","reading":"のうりょく","meaning":"năng lực, khả năng","example":"彼は問題を解決する能力が高い。","example_reading":"かれはもんだいをかいけつするのうりょくがたかい。","example_meaning":"Anh ấy có năng lực giải quyết vấn đề cao.","examples":[{"example":"日本語能力試験を受ける予定です。","example_reading":"にほんごのうりょくしけんをうけるよていです。","example_meaning":"Tôi dự định dự thi năng lực tiếng Nhật."},{"example":"能力に応じて、仕事を任せる。","example_reading":"のうりょくにおうじて、しごとをまかせる。","example_meaning":"Giao việc tùy theo năng lực."}]},{"word":"才能","reading":"さいのう","meaning":"tài năng","example":"彼女には音楽の才能がある。","example_reading":"かのじょにはおんがくのさいのうがある。","example_meaning":"Cô ấy có tài năng âm nhạc.","examples":[{"example":"才能があっても、努力しなければ伸びない。","example_reading":"さいのうがあっても、どりょくしなければのびない。","example_meaning":"Dù có tài năng, không nỗ lực thì cũng không tiến bộ."},{"example":"若い画家の才能が認められた。","example_reading":"わかいがかのさいのうがみとめられた。","example_meaning":"Tài năng của họa sĩ trẻ đã được công nhận."}]},{"word":"実力","reading":"じつりょく","meaning":"thực lực","example":"試験で実力を出し切ることができた。","example_reading":"しけんでじつりょくをだしきることができた。","example_meaning":"Tôi đã thể hiện hết thực lực trong kỳ thi.","examples":[{"example":"彼は実力のある選手だ。","example_reading":"かれはじつりょくのあるせんしゅだ。","example_meaning":"Anh ấy là tuyển thủ có thực lực."},{"example":"実力の差は、結果にはっきり表れた。","example_reading":"じつりょくのさは、けっかにはっきりあらわれた。","example_meaning":"Sự chênh lệch thực lực thể hiện rõ trong kết quả."}]}]},
{"label":"努力／頑張る／励む","note":"努力(どりょく): NỖ LỰC (danh từ, sự cố gắng liên tục vì mục tiêu). 頑張る(がんばる): CỐ GẮNG, KIÊN TRÌ không bỏ cuộc (khẩu ngữ, dùng để cổ vũ). 励む(はげむ): CHUYÊN TÂM, MIỆT MÀI vào việc (trang trọng: học hành, rèn luyện, công việc).","items":[{"word":"努力","reading":"どりょく","meaning":"nỗ lực","example":"毎日の努力が実を結んだ。","example_reading":"まいにちのどりょくがみをむすんだ。","example_meaning":"Nỗ lực mỗi ngày cuối cùng đã đơm hoa kết trái.","examples":[{"example":"彼は努力して、医者になった。","example_reading":"かれはどりょくして、いしゃになった。","example_meaning":"Anh ấy nỗ lực và đã trở thành bác sĩ."},{"example":"努力しても、うまくいかないこともある。","example_reading":"どりょくしても、うまくいかないこともある。","example_meaning":"Có những lúc dù nỗ lực vẫn không thuận lợi."}]},{"word":"頑張る","reading":"がんばる","meaning":"cố gắng, kiên trì","example":"試験まであと少し、頑張ろう。","example_reading":"しけんまであとすこし、がんばろう。","example_meaning":"Sắp đến kỳ thi rồi, cố lên nào.","examples":[{"example":"最後まで頑張ってください。","example_reading":"さいごまでがんばってください。","example_meaning":"Hãy cố gắng đến cùng nhé."},{"example":"疲れていたが、もう少し頑張ることにした。","example_reading":"つかれていたが、もうすこしがんばることにした。","example_meaning":"Tuy mệt nhưng tôi quyết định cố thêm một chút nữa."}]},{"word":"励む","reading":"はげむ","meaning":"chuyên tâm, miệt mài","example":"彼は毎日、勉強に励んでいる。","example_reading":"かれはまいにち、べんきょうにはげんでいる。","example_meaning":"Anh ấy miệt mài học tập mỗi ngày.","examples":[{"example":"仕事に励んで、昇進した。","example_reading":"しごとにはげんで、しょうしんした。","example_meaning":"Chuyên tâm làm việc nên anh ấy đã được thăng chức."},{"example":"選手たちは練習に励んでいます。","example_reading":"せんしゅたちはれんしゅうにはげんでいます。","example_meaning":"Các tuyển thủ đang miệt mài luyện tập."}]}]},
{"label":"成功／達成／実現","note":"成功(せいこう): THÀNH CÔNG (kết quả tốt: thí nghiệm, kinh doanh, kế hoạch). 達成(たっせい): ĐẠT ĐƯỢC mục tiêu, kỷ lục, chỉ tiêu. 実現(じつげん): HIỆN THỰC HÓA ước mơ, kế hoạch trở thành sự thật.","items":[{"word":"成功","reading":"せいこう","meaning":"thành công","example":"実験は見事に成功しました。","example_reading":"じっけんはみごとにせいこうしました。","example_meaning":"Thí nghiệm đã thành công rực rỡ.","examples":[{"example":"事業に成功して、大金持ちになった。","example_reading":"じぎょうにせいこうして、おおがねもちになった。","example_meaning":"Kinh doanh thành công nên anh ấy trở nên giàu có."},{"example":"失敗は成功のもとだ。","example_reading":"しっぱいはせいこうのもとだ。","example_meaning":"Thất bại là mẹ thành công."}]},{"word":"達成","reading":"たっせい","meaning":"đạt được (mục tiêu)","example":"目標を達成するまで、あきらめない。","example_reading":"もくひょうをたっせいするまで、あきらめない。","example_meaning":"Tôi sẽ không bỏ cuộc cho đến khi đạt được mục tiêu.","examples":[{"example":"今月の売上目標を達成した。","example_reading":"こんげつのうりあげもくひょうをたっせいした。","example_meaning":"Chúng tôi đã đạt chỉ tiêu doanh số tháng này."},{"example":"世界記録を達成した選手が表彰された。","example_reading":"せかいきろくをたっせいしたせんしゅがひょうしょうされた。","example_meaning":"Tuyển thủ lập kỷ lục thế giới đã được khen thưởng."}]},{"word":"実現","reading":"じつげん","meaning":"hiện thực hóa","example":"長年の夢がついに実現した。","example_reading":"ながねんのゆめがついにじつげんした。","example_meaning":"Ước mơ bao năm cuối cùng đã thành hiện thực.","examples":[{"example":"この計画は、実現が難しいかもしれない。","example_reading":"このけいかくは、じつげんがむずかしいかもしれない。","example_meaning":"Kế hoạch này có thể khó thực hiện được."},{"example":"彼は留学の夢を実現させた。","example_reading":"かれはりゅうがくのゆめをじつげんさせた。","example_meaning":"Anh ấy đã biến ước mơ du học thành hiện thực."}]}]},
{"label":"失敗／ミス／間違い","note":"失敗(しっぱい): THẤT BẠI (không đạt mục đích: kế hoạch, thử nghiệm, nấu ăn). ミス: LỖI SAI SÓT do bất cẩn (tính toán, thao tác, thể thao). 間違い(まちがい): SAI, NHẦM (đáp án, cách làm so với cái đúng).","items":[{"word":"失敗","reading":"しっぱい","meaning":"thất bại","example":"料理に失敗して、焦がしてしまった。","example_reading":"りょうりにしっぱいして、こがしてしまった。","example_meaning":"Nấu ăn hỏng, tôi làm cháy mất rồi.","examples":[{"example":"就職の面接で失敗した。","example_reading":"しゅうしょくのめんせつでしっぱいした。","example_meaning":"Tôi đã thất bại ở buổi phỏng vấn xin việc."},{"example":"失敗を恐れず、挑戦してみよう。","example_reading":"しっぱいをおそれず、ちょうせんしてみよう。","example_meaning":"Đừng sợ thất bại, hãy thử thách bản thân."}]},{"word":"ミス","reading":"みす","meaning":"lỗi sai sót (do bất cẩn)","example":"計算ミスで、点数を落とした。","example_reading":"けいさんみすで、てんすうをおとした。","example_meaning":"Vì sai sót khi tính toán nên tôi bị mất điểm.","examples":[{"example":"小さなミスが大きな事故につながる。","example_reading":"ちいさなみすがおおきなじこにつながる。","example_meaning":"Một sai sót nhỏ có thể dẫn đến tai nạn lớn."},{"example":"彼はミスをしても、すぐに認める。","example_reading":"かれはみすをしても、すぐにみとめる。","example_meaning":"Dù mắc lỗi, anh ấy cũng thừa nhận ngay."}]},{"word":"間違い","reading":"まちがい","meaning":"sai, nhầm","example":"答えに間違いがあります。","example_reading":"こたえにまちがいがあります。","example_meaning":"Đáp án có chỗ sai.","examples":[{"example":"間違いを見つけたら、教えてください。","example_reading":"まちがいをみつけたら、おしえてください。","example_meaning":"Nếu thấy lỗi sai thì hãy báo cho tôi."},{"example":"電話番号の間違いに気づいた。","example_reading":"でんわばんごうのまちがいにきづいた。","example_meaning":"Tôi đã nhận ra số điện thoại bị nhầm."}]}]},
{"label":"危険／危ない／物騒","note":"危険(きけん): NGUY HIỂM (danh từ/tính từ な, mối nguy tiềm tàng, trang trọng). 危ない(あぶない): NGUY HIỂM, COI CHỪNG (khẩu ngữ, sắp có tai nạn, dùng để cảnh báo). 物騒(ぶっそう): BẤT AN, không yên ổn (nơi chốn/thời buổi hay có tội phạm, vụ việc đáng sợ).","items":[{"word":"危険","reading":"きけん","meaning":"nguy hiểm","example":"この川で泳ぐのは危険です。","example_reading":"このかわでおよぐのはきけんです。","example_meaning":"Bơi ở con sông này rất nguy hiểm.","examples":[{"example":"危険を感じたら、すぐ逃げてください。","example_reading":"きけんをかんじたら、すぐにげてください。","example_meaning":"Nếu cảm thấy nguy hiểm, hãy chạy ngay."},{"example":"山登りには危険がつきものだ。","example_reading":"やまのぼりにはきけんがつきものだ。","example_meaning":"Leo núi luôn đi kèm với nguy hiểm."}]},{"word":"危ない","reading":"あぶない","meaning":"nguy hiểm, coi chừng","example":"危ない！車が来るよ。","example_reading":"あぶない！くるまがくるよ。","example_meaning":"Nguy hiểm! Xe đang tới kìa.","examples":[{"example":"夜道を一人で歩くのは危ない。","example_reading":"よみちをひとりであるくのはあぶない。","example_meaning":"Đi một mình trên đường đêm rất nguy hiểm."},{"example":"もう少しで、危ないところだった。","example_reading":"もうすこしで、あぶないところだった。","example_meaning":"Suýt chút nữa là nguy rồi."}]},{"word":"物騒","reading":"ぶっそう","meaning":"bất an, không yên ổn","example":"最近、この辺りは物騒になった。","example_reading":"さいきん、このあたりはぶっそうになった。","example_meaning":"Gần đây khu này trở nên mất an ninh.","examples":[{"example":"夜遅くに出かけるのは物騒だ。","example_reading":"よるおそくにでかけるのはぶっそうだ。","example_meaning":"Ra ngoài vào đêm khuya thì không an toàn."},{"example":"物騒な世の中なので、戸締まりをしっかりする。","example_reading":"ぶっそうなよのなかなので、とじまりをしっかりする。","example_meaning":"Thời buổi bất an nên tôi khóa cửa cẩn thận."}]}]},
{"label":"安全／安心／無事","note":"安全(あんぜん): AN TOÀN (không có nguy hiểm, mang tính khách quan). 安心(あんしん): YÊN TÂM (tâm trạng hết lo lắng, mang tính chủ quan). 無事(ぶじ): BÌNH AN VÔ SỰ (không có chuyện xấu xảy ra với người/chuyến đi).","items":[{"word":"安全","reading":"あんぜん","meaning":"an toàn","example":"この地域は安全です。","example_reading":"このちいきはあんぜんです。","example_meaning":"Khu vực này an toàn.","examples":[{"example":"安全のために、シートベルトを締めてください。","example_reading":"あんぜんのために、しーとべるとをしめてください。","example_meaning":"Vì sự an toàn, hãy thắt dây an toàn."},{"example":"安全な水を飲むことは大切だ。","example_reading":"あんぜんなみずをのむことはたいせつだ。","example_meaning":"Uống nước sạch an toàn là điều quan trọng."}]},{"word":"安心","reading":"あんしん","meaning":"yên tâm","example":"子どもが帰ってきて、安心しました。","example_reading":"こどもがかえってきて、あんしんしました。","example_meaning":"Con về đến nhà rồi, tôi yên tâm.","examples":[{"example":"医者の話を聞いて、安心した。","example_reading":"いしゃのはなしをきいて、あんしんした。","example_meaning":"Nghe bác sĩ nói xong tôi đã yên tâm."},{"example":"保険に入っているから、安心だ。","example_reading":"ほけんにはいっているから、あんしんだ。","example_meaning":"Vì đã mua bảo hiểm nên tôi yên tâm."}]},{"word":"無事","reading":"ぶじ","meaning":"bình an vô sự","example":"無事に着きましたので、ご安心ください。","example_reading":"ぶじにつきましたので、ごあんしんください。","example_meaning":"Tôi đã đến nơi bình an, xin đừng lo.","examples":[{"example":"事故に遭ったが、全員無事だった。","example_reading":"じこにあったが、ぜんいんぶじだった。","example_meaning":"Tuy gặp tai nạn nhưng mọi người đều bình an."},{"example":"旅行が無事に終わって、ほっとした。","example_reading":"りょこうがぶじにおわって、ほっとした。","example_meaning":"Chuyến du lịch kết thúc suôn sẻ, tôi thấy nhẹ nhõm."}]}]},
{"label":"普通／一般／平凡","note":"普通(ふつう): BÌNH THƯỜNG, THÔNG THƯỜNG (như hay thấy; còn là 'tàu thường'). 一般(いっぱん): CHUNG, ĐẠI CHÚNG (người bình thường nói chung, phổ biến). 平凡(へいぼん): TẦM THƯỜNG, BÌNH BÁN (thiếu điểm nổi bật, hơi tiêu cực).","items":[{"word":"普通","reading":"ふつう","meaning":"bình thường, thông thường","example":"普通は朝七時に起きます。","example_reading":"ふつうはあさしちじにおきます。","example_meaning":"Bình thường tôi dậy lúc 7 giờ sáng.","examples":[{"example":"これは普通のレストランとは違う。","example_reading":"これはふつうのれすとらんとはちがう。","example_meaning":"Đây không phải là nhà hàng bình thường."},{"example":"普通電車は各駅に停まります。","example_reading":"ふつうでんしゃはかくえきにとまります。","example_meaning":"Tàu thường dừng ở mọi ga."}]},{"word":"一般","reading":"いっぱん","meaning":"chung, đại chúng","example":"この博物館は、一般の人にも公開されている。","example_reading":"このはくぶつかんは、いっぱんのひとにもこうかいされている。","example_meaning":"Bảo tàng này cũng mở cửa cho công chúng.","examples":[{"example":"一般的に、日本人は時間に正確だ。","example_reading":"いっぱんてきに、にほんじんはじかんにせいかくだ。","example_meaning":"Nói chung, người Nhật rất đúng giờ."},{"example":"これは一般の家庭ではあまり使われない。","example_reading":"これはいっぱんのかていではあまりつかわれない。","example_meaning":"Thứ này không được dùng nhiều trong các gia đình thông thường."}]},{"word":"平凡","reading":"へいぼん","meaning":"tầm thường, bình bán","example":"平凡な毎日だが、幸せだ。","example_reading":"へいぼんなまいにちだが、しあわせだ。","example_meaning":"Tuy những ngày bình lặng nhưng tôi thấy hạnh phúc.","examples":[{"example":"彼の考えは平凡で、新しさがない。","example_reading":"かれのかんがえはへいぼんで、あたらしさがない。","example_meaning":"Ý tưởng của anh ta tầm thường, chẳng có gì mới."},{"example":"平凡な生活を送りたいと思っている。","example_reading":"へいぼんなせいかつをおくりたいとおもっている。","example_meaning":"Tôi muốn sống một cuộc sống bình dị."}]}]},
{"label":"特別／特殊／特有","note":"特別(とくべつ): ĐẶC BIỆT, KHÁC THƯỜNG (tốt hơn/khác mức thường, đối xử riêng). 特殊(とくしゅ): ĐẶC THÙ, ĐẶC DỊ (khác về tính chất, kỹ thuật, trường hợp ít gặp). 特有(とくゆう): ĐẶC TRƯNG, RIÊNG CÓ của một người/vật/vùng.","items":[{"word":"特別","reading":"とくべつ","meaning":"đặc biệt","example":"今日は特別な日です。","example_reading":"きょうはとくべつなひです。","example_meaning":"Hôm nay là một ngày đặc biệt.","examples":[{"example":"彼には特別な才能がある。","example_reading":"かれにはとくべつなさいのうがある。","example_meaning":"Anh ấy có tài năng đặc biệt."},{"example":"特別な予定はありません。","example_reading":"とくべつなよていはありません。","example_meaning":"Tôi không có kế hoạch gì đặc biệt."}]},{"word":"特殊","reading":"とくしゅ","meaning":"đặc thù, đặc dị","example":"特殊な技術が必要な仕事だ。","example_reading":"とくしゅなぎじゅつがひつようなしごとだ。","example_meaning":"Đây là công việc cần kỹ thuật đặc thù.","examples":[{"example":"この道具は特殊な形をしている。","example_reading":"このどうぐはとくしゅなかたちをしている。","example_meaning":"Dụng cụ này có hình dạng đặc biệt."},{"example":"特殊な事情があって、会議に出られなかった。","example_reading":"とくしゅなじじょうがあって、かいぎにでられなかった。","example_meaning":"Vì hoàn cảnh đặc biệt nên tôi không thể dự họp."}]},{"word":"特有","reading":"とくゆう","meaning":"đặc trưng, riêng có","example":"この花は熱帯地方特有の植物だ。","example_reading":"このはなはねったいちほうとくゆうのしょくぶつだ。","example_meaning":"Hoa này là loài thực vật đặc trưng của vùng nhiệt đới.","examples":[{"example":"関西特有の言葉もある。","example_reading":"かんさいとくゆうのことばもある。","example_meaning":"Cũng có những từ riêng chỉ có ở vùng Kansai."},{"example":"日本特有の文化を紹介する。","example_reading":"にほんとくゆうのぶんかをしょうかいする。","example_meaning":"Giới thiệu nền văn hóa đặc trưng của Nhật Bản."}]}]},
{"label":"全部／全体／すべて","note":"全部(ぜんぶ): TOÀN BỘ, TẤT CẢ (cộng từng cái lại, nói về số lượng, khẩu ngữ). 全体(ぜんたい): TOÀN THỂ, TỔNG THỂ (cả khối, đối lập với bộ phận). すべて: TẤT CẢ, MỌI THỨ (không sót thứ nào, hơi trang trọng).","items":[{"word":"全部","reading":"ぜんぶ","meaning":"toàn bộ, tất cả","example":"宿題を全部終わらせた。","example_reading":"しゅくだいをぜんぶおわらせた。","example_meaning":"Tôi đã làm xong toàn bộ bài tập.","examples":[{"example":"お金を全部使ってしまった。","example_reading":"おかねをぜんぶつかってしまった。","example_meaning":"Tôi đã lỡ tiêu hết sạch tiền."},{"example":"この本は全部で五百ページある。","example_reading":"このほんはぜんぶでごひゃくぺーじある。","example_meaning":"Cuốn sách này tổng cộng có 500 trang."}]},{"word":"全体","reading":"ぜんたい","meaning":"toàn thể, tổng thể","example":"クラス全体で協力しましょう。","example_reading":"くらすぜんたいできょうりょくしましょう。","example_meaning":"Cả lớp hãy cùng hợp tác với nhau.","examples":[{"example":"全体の雰囲気はとてもいい。","example_reading":"ぜんたいのふんいきはとてもいい。","example_meaning":"Bầu không khí chung rất tốt."},{"example":"まず、計画の全体を説明します。","example_reading":"まず、けいかくのぜんたいをせつめいします。","example_meaning":"Trước hết tôi sẽ giải thích tổng thể kế hoạch."}]},{"word":"すべて","reading":"すべて","meaning":"tất cả, mọi thứ","example":"すべてがうまくいった。","example_reading":"すべてがうまくいった。","example_meaning":"Mọi thứ đều suôn sẻ.","examples":[{"example":"すべての人に平等な機会がある。","example_reading":"すべてのひとにびょうどうなきかいがある。","example_meaning":"Mọi người đều có cơ hội bình đẳng."},{"example":"私は持っているものをすべて売った。","example_reading":"わたしはもっているものをすべてうった。","example_meaning":"Tôi đã bán hết mọi thứ mình có."}]}]},
{"label":"少し／ちょっと／わずか","note":"少し(すこし): MỘT CHÚT (số lượng/mức độ nhỏ, trung tính). ちょっと: HƠI, MỘT TÍ (khẩu ngữ; còn dùng để từ chối nhẹ nhàng). わずか: CHỈ VỎN VẸN, ÍT ỎI (nhấn mạnh là rất ít).","items":[{"word":"少し","reading":"すこし","meaning":"một chút","example":"少し休みましょう。","example_reading":"すこしやすみましょう。","example_meaning":"Hãy nghỉ một chút nào.","examples":[{"example":"お金が少しだけ残っている。","example_reading":"おかねがすこしだけのこっている。","example_meaning":"Vẫn còn lại chút ít tiền."},{"example":"日本語が少し話せます。","example_reading":"にほんごがすこしはなせます。","example_meaning":"Tôi nói được một chút tiếng Nhật."}]},{"word":"ちょっと","reading":"ちょっと","meaning":"hơi, một tí (khẩu ngữ)","example":"ちょっと待ってください。","example_reading":"ちょっとまってください。","example_meaning":"Xin chờ một chút.","examples":[{"example":"今夜はちょっと都合が悪いです。","example_reading":"こんやはちょっとつごうがわるいです。","example_meaning":"Tối nay hơi bất tiện với tôi."},{"example":"この靴は、ちょっと大きい。","example_reading":"このくつは、ちょっとおおきい。","example_meaning":"Đôi giày này hơi rộng."}]},{"word":"わずか","reading":"わずか","meaning":"chỉ vỏn vẹn, ít ỏi","example":"優勝まで、わずか一点の差だった。","example_reading":"ゆうしょうまで、わずかいってんのさだった。","example_meaning":"Chỉ cách chức vô địch đúng một điểm.","examples":[{"example":"残っているお金は、わずか千円だ。","example_reading":"のこっているおかねは、わずかせんえんだ。","example_meaning":"Số tiền còn lại chỉ vỏn vẹn một nghìn yên."},{"example":"わずかな時間でも、勉強するようにしている。","example_reading":"わずかなじかんでも、べんきょうするようにしている。","example_meaning":"Dù chỉ một chút thời gian, tôi cũng cố gắng học."}]}]},
{"label":"とても／非常に／かなり","note":"とても: RẤT (khẩu ngữ, dùng nhiều nhất hàng ngày). 非常に(ひじょうに): CỰC KỲ (trang trọng, văn viết, thuyết trình). かなり: KHÁ, KHÁ NHIỀU (mức độ cao nhưng không cực đoan, so với mong đợi).","items":[{"word":"とても","reading":"とても","meaning":"rất","example":"この料理はとてもおいしいです。","example_reading":"このりょうりはとてもおいしいです。","example_meaning":"Món ăn này rất ngon.","examples":[{"example":"今日はとても疲れました。","example_reading":"きょうはとてもつかれました。","example_meaning":"Hôm nay tôi rất mệt."},{"example":"とても静かな町に住んでいます。","example_reading":"とてもしずかなまちにすんでいます。","example_meaning":"Tôi sống ở một thị trấn rất yên tĩnh."}]},{"word":"非常に","reading":"ひじょうに","meaning":"cực kỳ (trang trọng)","example":"非常に重要な問題です。","example_reading":"ひじょうにじゅうようなもんだいです。","example_meaning":"Đây là vấn đề cực kỳ quan trọng.","examples":[{"example":"結果は非常に満足のいくものだった。","example_reading":"けっかはひじょうにまんぞくのいくものだった。","example_meaning":"Kết quả vô cùng đáng hài lòng."},{"example":"この薬は非常に高価だ。","example_reading":"このくすりはひじょうにこうかだ。","example_meaning":"Loại thuốc này cực kỳ đắt."}]},{"word":"かなり","reading":"かなり","meaning":"khá, khá nhiều","example":"かなり遠いので、タクシーで行きましょう。","example_reading":"かなりとおいので、たくしーでいきましょう。","example_meaning":"Khá xa nên chúng ta hãy đi bằng taxi.","examples":[{"example":"彼は日本語がかなり上手になった。","example_reading":"かれはにほんごがかなりじょうずになった。","example_meaning":"Tiếng Nhật của anh ấy đã khá giỏi."},{"example":"かなり待ったが、バスは来なかった。","example_reading":"かなりまったが、ばすはこなかった。","example_meaning":"Tôi đã đợi khá lâu nhưng xe buýt vẫn không đến."}]}]},
{"label":"まだ／いまだに／依然として","note":"まだ: VẪN CHƯA / VẪN CÒN (khẩu ngữ, việc chưa hoàn thành hoặc đang tiếp diễn). いまだに: CHO ĐẾN BÂY GIỜ VẪN (kéo dài đến nay, thường có sắc thái bất ngờ/tiếc nuối). 依然として(いぜんとして): VẪN NHƯ CŨ (trang trọng, tình trạng không thay đổi).","items":[{"word":"まだ","reading":"まだ","meaning":"vẫn chưa, vẫn còn","example":"宿題がまだ終わっていません。","example_reading":"しゅくだいがまだおわっていません。","example_meaning":"Tôi vẫn chưa làm xong bài tập.","examples":[{"example":"外はまだ雨が降っている。","example_reading":"そとはまだあめがふっている。","example_meaning":"Bên ngoài trời vẫn còn đang mưa."},{"example":"まだ時間があるから、コーヒーを飲もう。","example_reading":"まだじかんがあるから、こーひーをのもう。","example_meaning":"Vẫn còn thời gian nên mình uống cà phê đi."}]},{"word":"いまだに","reading":"いまだに","meaning":"đến bây giờ vẫn","example":"いまだにあの日のことが忘れられない。","example_reading":"いまだにあのひのことがわすれられない。","example_meaning":"Đến giờ tôi vẫn không quên được chuyện hôm đó.","examples":[{"example":"事故の原因は、いまだに分かっていない。","example_reading":"じこのげんいんは、いまだにわかっていない。","example_meaning":"Đến nay vẫn chưa rõ nguyên nhân vụ tai nạn."},{"example":"彼はいまだに昔の癖が直らない。","example_reading":"かれはいまだにむかしのくせがなおらない。","example_meaning":"Anh ta đến giờ vẫn chưa bỏ được thói quen cũ."}]},{"word":"依然として","reading":"いぜんとして","meaning":"vẫn như cũ (trang trọng)","example":"状況は依然として厳しい。","example_reading":"じょうきょうはいぜんとしてきびしい。","example_meaning":"Tình hình vẫn còn khắc nghiệt.","examples":[{"example":"依然として、行方不明者の捜索が続いている。","example_reading":"いぜんとして、ゆくえふめいしゃのそうさくがつづいている。","example_meaning":"Việc tìm kiếm người mất tích vẫn đang tiếp tục."},{"example":"物価は依然として高いままだ。","example_reading":"ぶっかはいぜんとしてたかいままだ。","example_meaning":"Giá cả vẫn ở mức cao như trước."}]}]}
]
};
